window.__HSK_CHAPTER_DATA__['chapter_11'] = [{"meanings_summary": {"en": "alarm clock; alarm", "es": "despertador; reloj despertador"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A metallic bell (钟) that makes a loud, clamorous noise (闹) to awaken you is an alarm clock (闹钟).", "composite_memory_hook_es": "Una campana metálica (钟) que arma ruido estridente (闹) para despertarte es el despertador (闹钟).", "cultural_and_cognitive_roots": "Traditional Chinese temple bell and drum towers (钟鼓楼) announced dawn and curfew; Western mechanical clocks replaced them in the late Qing.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by level high tone: 'nào zhōng' (51-55). Strike down on 'nào', then sustain a clear high ring on 'zhōng'."}, "semantic_boundary_contrasts": {"core_nuance": "闹钟 specifically denotes a timepiece designed to ring aloud at a pre-set alert time, distinguished from passive wall clocks.", "contrasts": [{"id": "1", "compared_word": "闹钟 vs. 时钟", "pinyin": "shízhōng", "analysis": "时钟 refers generically to any large clock or clock tower, while 闹钟 specifically features an audible alarm mechanism."}, {"id": "2", "compared_word": "闹钟 vs. 手表", "pinyin": "shǒubiǎo", "analysis": "手表 designates a personal wrist watch worn on the wrist, whereas 闹钟 typically rests on a bedside nightstand or phone app."}, {"id": "3", "compared_word": "闹钟 vs. 门铃", "pinyin": "ménlíng", "analysis": "门铃 is an entrance doorbell triggered by arriving visitors, not a wake-up scheduling alarm."}]}, "traps_and_cognates": {"look_alikes": [{"character": "闲", "pinyin": "xián", "meaning_en": "idle; leisure", "distinction_note": "Has wood 木 inside 门 instead of 市 in 闹"}, {"character": "阔", "pinyin": "kuò", "meaning_en": "broad; vast", "distinction_note": "Has 活 inside 门"}, {"character": "针", "pinyin": "zhēn", "meaning_en": "needle; pin", "distinction_note": "Has 十 on right of 钅 instead of 中 in 钟"}, {"character": "钢", "pinyin": "gāng", "meaning_en": "steel", "distinction_note": "Has 冈 on right of 钅"}], "etymological_cognates": [{"character": "表", "pinyin": "biǎo", "gloss_en": "watch; external surface"}, {"character": "铃", "pinyin": "líng", "gloss_en": "little bell; tinkling chime"}, {"character": "钲", "pinyin": "zhēng", "gloss_en": "ancient metallic gong"}, {"character": "铎", "pinyin": "duó", "gloss_en": "large ancient handbell"}]}, "id": "1", "hanzi": "闹钟", "pinyin": "nào zhōng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a clock equipped with an acoustic mechanism to awaken sleeper or alert at a preset hour", "definition_es": "reloj provisto de mecanismo sonoro para despertar al durmiente o avisar a una hora fijada", "example_phrase": "调好闹钟 (set the alarm clock)"}], "example_sentences": [{"id": "#1", "hanzi": "为了赶上清晨首班高铁，他在睡觉前特意把手机闹钟设置在清晨五点整。", "pinyin": "Wèile gǎnshàng qīngchén shǒubān gāotiě, tā zài shuìjiào qián tèyì bǎ shǒujī nàozhōng shèzhì zài qīngchén wǔ diǎn zhěng.", "en": "In order to catch the morning's first high-speed train, he deliberately set his phone alarm clock to five o'clock sharp before sleeping.", "es": "Para no perder el primer tren de alta velocidad de la mañana, programó el despertador del móvil a las cinco en punto antes de acostarse."}, {"id": "#2", "hanzi": "医学研究表明，长期被刺耳的机械闹钟突然惊醒容易引起心跳加速与情绪焦虑。", "pinyin": "Yīxué yánjiū biǎomíng, chángqī bèi cì'ěr de jīxiè nàozhōng tūrán jīngxǐng róngyì yǐnqǐ xīntiào jiāsù yǔ qíngxù jiāolǜ.", "en": "Medical research indicates that being startled awake for long periods by piercing mechanical alarms easily triggers rapid heartbeat and anxiety.", "es": "Estudios médicos señalan que ser despertado bruscamente por alarmas estridentes provoca taquicardia y desasosiego emocional prolongado."}], "collocations": [{"hanzi": "定闹钟", "en": "set an alarm clock"}, {"hanzi": "闹钟响了", "en": "alarm clock rings"}, {"hanzi": "机械闹钟", "en": "mechanical alarm clock"}, {"hanzi": "电子闹钟", "en": "electronic/digital alarm clock"}, {"hanzi": "关掉闹钟", "en": "turn off / silence alarm"}, {"hanzi": "静音闹钟", "en": "silent / vibration alarm"}], "idioms": [{"hanzi": "晨钟暮鼓", "pinyin": "chén zhōng mù gǔ", "meaning_en": "morning bell and evening drum; timely reminders of time's passing"}, {"hanzi": "警钟长鸣", "pinyin": "jǐng zhōng cháng míng", "meaning_en": "alarm bell ringing continuously; remain vigilant"}, {"hanzi": "鸡鸣戒旦", "pinyin": "jī míng jiè dàn", "meaning_en": "rooster crowing at dawn; diligent early rising"}, {"hanzi": "闻鸡起舞", "pinyin": "wén jī qǐ wǔ", "meaning_en": "rise upon hearing rooster crow to practice swords; hardworking vigor"}], "character_decomposition": [{"character": "闹", "pinyin": "nào", "meaning_en": "noisy; make noise; stir up; suffer from", "meaning_es": "ruidoso; alborotar; bullir; padecer", "radical": "门", "radical_meaning_en": "door / gate", "meaning_component": "门 (city marketplace gates) + 市 (bustling market)", "sound_component": "闹 (nào)", "stroke_count": "8", "composition_type": "半包围结构", "etymology_and_mnemonic": "Market crowds 市 shouting inside market gates 门; represents loud clamor, racket, and bustling commotion.", "visual_mnemonic_story_en": "A bustling market (市) clamors noisily inside open city gates (门), making a lively commotion (闹).", "visual_mnemonic_story_es": "El mercado bullicioso (市) vocifera tras las puertas (门) armando un alboroto sonoro (闹).", "tone_mnemonic_anchor": "51", "cangjie": "LSYB", "traditional": "鬧"}, {"character": "钟", "pinyin": "zhōng", "meaning_en": "clock; bell; cup; time unit", "meaning_es": "reloj; campana; copa; minuto", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (cast bronze metal) + 中 (straight upright spindle)", "sound_component": "重 (chóng/zhòng / phonetic origin)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Metal radical 钅 paired with a hanging vessel; originally an ancient musical bronze bell, later timepiece clocks.", "visual_mnemonic_story_en": "A bronze bell cast of metal (钅) rings at centered intervals (中) to mark the hour (钟).", "visual_mnemonic_story_es": "Una campana forjada en metal (钅) tañe con compás equilibrado (中) midiendo la hora (钟).", "tone_mnemonic_anchor": "55", "cangjie": "CLP", "traditional": "鐘"}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多上班族为了防止早晨赖床迟到，往往习惯在床头设置多个间隔五分钟的响亮闹钟。然而生理学家指出，反复被吵醒又迷糊入睡会打乱大脑正常的睡眠节律，反而让人整天昏昏沉沉、精力不济。", "pinyin": "Hěnduō shàngbānzú wèile fángzhǐ zǎochen làichuáng chídào, wǎngwǎng xíguàn zài chuángtóu shèzhì duō ge jiàngé wǔ fēnzhōng de xiǎngliàng nàozhōng. Rán'ér shēnglǐxuéjiā zhǐchū, fǎnfù bèi chǎoxǐng yòu míhu rùshuì huì dǎluàn dànǎo zhèngcháng de shuìmián jiélǜ, fǎn'ér ràng rén zhěng tiān hūnhūn-chénchén, jīnglì bújì.", "en": "Many office workers set multiple alarms five minutes apart to prevent oversleeping. Yet physiologists warn that repeatedly being jolted awake disrupts brain sleep cycles, causing lethargy all day long.", "es": "Muchos empleados programan varias alarmas cada cinco minutos para no dormirse. Empero, fisiólogos advierten que despertar y adormilarse en bucle rompe el ciclo circadiano, causando sopor y fatiga todo el día."}, {"id": "#2", "hanzi": "与刺耳突兀的传统机械铃声相比，新型智能光照闹钟能够模拟清晨自然日出的柔和光线。它在设定起床时间前半小时缓慢渐亮，温和地唤醒人体内部沉睡的生物钟，有效避免心血管系统骤然承受惊吓与血压波动。", "pinyin": "Yǔ cì'ěr tūwù de chuántǒng jīxiè língshēng xiāngbǐ, xīnxíng zhìnéng guāngzhào nàozhōng nénggòu mónǐ qīngchén zìrán rìchū de róuhé guāngxiàn. Tā zài shèdìng qǐchuáng shíjiān qián bàn xiǎoshí huǎnmàn jiànliàng, wēnhé de huànxǐng réntǐ nèibù chénsù de shēngwùzhōng, yǒuxiào bìmiǎn xīnxuèguǎn xìtǒng zhòurán chéngshòu jīngxià yǔ xuèyā bōdòng.", "en": "Compared with jarring mechanical rings, new smart sunrise alarms simulate morning dawn. Gradually brightening 30 minutes before waking, they gently awaken the internal biological clock without cardiovascular shocks.", "es": "Frente al estridente zumbador tradicional, los despertadores solares simulan el alba. Iluminando la estancia media hora antes, activan suavemente el reloj biológico sin sacudidas cardiovasculares ni alzas de presión."}]}, {"meanings_summary": {"en": "to harm; to jeopardize; to damage; harm; peril", "es": "dañar; perjudicar; atentar contra; peligro; daño"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Perched on a perilous cliff (危) while suffering painful damage (害) captures severe jeopardy (危害).", "composite_memory_hook_es": "Al borde del abismo peligroso (危) sufriendo un daño lesivo (害) se configura el perjuicio grave (危害).", "cultural_and_cognitive_roots": "Classical moral pairing: 危 (instability/hazard) compounded with 害 (malevolent harm/destruction); frequently used in legal statutes.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling tone: 'wēi hài' (55-51). Hold high pitch 55 on 'wēi', then descend sharply and heavily on 'hài'."}, "semantic_boundary_contrasts": {"core_nuance": "危害 highlights active, systemic jeopardy or severe societal/physiological harm.", "contrasts": [{"id": "1", "compared_word": "危害 vs. 损害", "pinyin": "sǔnhài", "analysis": "损害 emphasizes concrete financial loss or physical damage to interests and rights ('损害名誉', '损害利益'), while 危害 emphasizes perilous threats to safety and existence."}, {"id": "2", "compared_word": "危害 vs. 破坏", "pinyin": "pòhuài", "analysis": "破坏 emphasizes physical smashing or disrupting orders and treaties ('破坏公物', '破坏协议'), while 危害 can be invisible and chronic."}, {"id": "3", "compared_word": "危害 vs. 伤害", "pinyin": "shānghài", "analysis": "伤害 focuses primarily on biological injury to living bodies or wounded emotions ('伤害感情'), while 危害 applies broadly to public security, health, and ecosystems."}]}, "traps_and_cognates": {"look_alikes": [{"character": "免", "pinyin": "miǎn", "meaning_en": "exempt; avoid", "distinction_note": "Lacks the upper cliff lid 𠂆 of 危"}, {"character": "角", "pinyin": "jiǎo", "meaning_en": "horn; corner", "distinction_note": "Has central vertical stroke penetrating down"}, {"character": "割", "pinyin": "gē", "meaning_en": "cut; sever", "distinction_note": "Has knife radical 刂 on right of 害"}, {"character": "豁", "pinyin": "huò", "meaning_en": "open; exempt", "distinction_note": "Has 谷 on right of 害"}], "etymological_cognates": [{"character": "损", "pinyin": "sǔn", "gloss_en": "damage; decrease loss"}, {"character": "伤", "pinyin": "shāng", "gloss_en": "wound; injure flesh"}, {"character": "祸", "pinyin": "huò", "gloss_en": "calamity; disaster"}, {"character": "殃", "pinyin": "yāng", "gloss_en": "misfortune; disaster"}]}, "id": "2", "hanzi": "危害", "pinyin": "wēi hài", "level": "HSK 5", "part_of_speech": "Verb / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cause severe injury, damage, jeopardy, or impairment to health, safety, or society", "definition_es": "causar daño grave, perjuicio o menoscabo a la salud, seguridad o bienestar social", "example_phrase": "危害身体健康 (harm bodily health)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "harm, danger, detriment, or hazardous damage", "definition_es": "perjuicio, daño, peligro o estrago", "example_phrase": "认识吸烟的危害 (recognize harms of smoking)"}], "example_sentences": [{"id": "#1", "hanzi": "长期吸烟与吸二手烟会对人体肺部和心脑血管系统造成极大的不可逆危害。", "pinyin": "Chángqī xīyān yǔ xī èrshǒuyān huì duì réntǐ fèibù hé xīn-nǎoxiěguǎn xìtǒng zàochéng jí dà de bùkěnì wēihài.", "en": "Long-term smoking and second-hand smoke cause immense and irreversible harm to lungs and cardiovascular systems.", "es": "Fumar de forma prolongada e inhalar humo ajeno causa daños de enorme gravedad e irreversibles a los pulmones y vasos sanguíneos."}, {"id": "#2", "hanzi": "任何危害国家主权、安全与公共利益的违法犯罪行为，都必将受到法律的严惩。", "pinyin": "Rènhé wēihài guójiā zhǔquán, ānquán yǔ gōnggòng lìyì de wéifǎ fànzuì xíngwéi, dōu bìjiāng shòudào fǎlǜ de yánchéng.", "en": "Any illegal criminal conduct that jeopardizes national sovereignty, security, or public interests will be punished severely by law.", "es": "Toda conducta delictiva que atente contra la soberanía, la seguridad y el bien público será castigada con el rigor de la ley."}], "collocations": [{"hanzi": "严重危害", "en": "serious harm / severely jeopardize"}, {"hanzi": "危害健康", "en": "harm health"}, {"hanzi": "危害安全", "en": "jeopardize safety/security"}, {"hanzi": "环境危害", "en": "environmental hazard/harm"}, {"hanzi": "造成危害", "en": "cause harm / inflict damage"}, {"hanzi": "危害社会", "en": "harm society"}], "idioms": [{"hanzi": "后患无穷", "pinyin": "hòu huàn wú qióng", "meaning_en": "no end of future troubles; endless disastrous aftermath"}, {"hanzi": "贻害无穷", "pinyin": "yí hài wú qióng", "meaning_en": "leave boundless harm for future generations"}, {"hanzi": "防患未然", "pinyin": "fáng huàn wèi rán", "meaning_en": "prevent troubles before they happen; take precautions"}, {"hanzi": "除暴安良", "pinyin": "chú bào ān liáng", "meaning_en": "eliminate the violent and protect the peaceful"}], "character_decomposition": [{"character": "危", "pinyin": "wēi", "meaning_en": "danger; perilous; precarious; high", "meaning_es": "peligro; arriesgado; precario; alto", "radical": "厄", "radical_meaning_en": "distress / cliff", "meaning_component": "𠂆 (precipitous cliff) + 卩 (kneeling person on edge)", "sound_component": "危 (wēi)", "stroke_count": "6", "composition_type": "半包围结构", "etymology_and_mnemonic": "A person 卩 kneeling trembling atop a high, dizzying cliff 𠂆; signifies peril, danger, and precariousness.", "visual_mnemonic_story_en": "A figure crouches cautiously on the edge of a sheer cliff (𠂆), facing extreme danger (危).", "visual_mnemonic_story_es": "Una figura se agacha aterrada al borde de un risco escarpado (𠂆) ante el abismo peligroso (危).", "tone_mnemonic_anchor": "55", "cangjie": "NMSU", "traditional": ""}, {"character": "害", "pinyin": "hài", "meaning_en": "harm; damage; injure; evil", "meaning_es": "dañar; perjudicar; matar; mal", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (house roof) + 丰 (thorn weapon) + 口 (malevolent words)", "sound_component": "害 (hài)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Spiteful words 口 and sharp thorns entering a home 宀 to hurt inhabitants; signifies injury and damage.", "visual_mnemonic_story_en": "Harmful weapons and words pierce into a peaceful house (宀), causing painful injury (害).", "visual_mnemonic_story_es": "Espinas punzantes y rencores entran bajo el techo del hogar (宀) infligiendo daño (害).", "tone_mnemonic_anchor": "51", "cangjie": "JQMR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "随着现代工业文明飞速发展，未经妥善处理的塑料微粒和有毒工业废水正严重危害着海洋生态系统。有毒重金属在海洋鱼类体内持续富集，最终通过食物链回流至人类餐桌，对人体健康构成了潜在的长期危害。", "pinyin": "Suízhe xiàndài gōngyè wénmíng fēisù fāzhǎn, wèijīng tuǒshàn chǔlǐ de sùliào wēilì hé yǒudú gōngyè fèishuǐ zhèng yánzhòng wēihài zhe hǎiyáng shēngtài xìtǒng. Yǒudú zhòngjīnshǔ zài hǎiyáng yúlèi tǐnèi chíxù fùjí, zuìzhōng tōngguò shíwùliàn huíliú zhì rénlèi cānzhuō, duì réntǐ jiànkāng gòuchéng le qiánzài de chángqī wēihài.", "en": "With rapid industrialization, untreated microplastics and chemical effluents severely jeopardize marine ecosystems. Toxic heavy metals accumulate up food chains to dinner tables, posing long-term hazards to human health.", "es": "Con el auge industrial, microplásticos y aguas residuales tóxicas dañan gravemente la ecología marina. Metales pesados se bioacumulan en la fauna llegando a la mesa y amenazando la salud humana a largo plazo."}, {"id": "#2", "hanzi": "在数字化信息时代，网络谣言与虚假信息的广泛传播对正常社会秩序造成了不可忽视的重大危害。不法分子利用公众的焦虑情绪恶意炮制耸人听闻的谎言，挑拨社会矛盾，执法机关必须依法坚决打击、严厉惩治。", "pinyin": "Zài shùzìhuà xìnxī shídài, wǎngluò yáoyán yǔ xūjiǎ xìnxī de guǎngfàn chuánbō duì zhèngcháng shèhuì zhìxù zàochéng le bùkě hūshì de zhòngdà wēihài. Bùfǎ fènzǐ lìyòng gōngzhòng de jiāolǜ qíngxù èyì páozhì sǒngrén-tīngwén de huǎngyán, tiǎobō shèhuì máodùn, zhífǎ jīguān bìxū yīfǎ jiānjué dǎjī, yánlì chéngzhì.", "en": "In the digital era, proliferation of online rumors inflicts unignorable harm on social order. Criminals exploit anxiety to fabricate sensational lies and sow discord, demanding resolute crackdowns by law enforcement.", "es": "En la era digital, la proliferación de bulos causa estragos innegables en la paz social. Maleantes explotan la zozobra pública urdiendo patrañas para sembrar discordia, exigiendo una respuesta implacable de la justicia."}]}, {"meanings_summary": {"en": "humankind; humanity; mankind; human race", "es": "humanidad; género humano; especie humana; seres humanos"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The species (类) of upright thinking beings (人) makes up humankind (人类).", "composite_memory_hook_es": "La especie (类) que camina erguida pensando (人) conforma la humanidad (人类).", "cultural_and_cognitive_roots": "Universal collective biological noun: combines 人 (bipedal moral human) with 类 (taxonomic genus/kind), reflecting both natural history and humanism.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'rén lèi' (35-51). Rise smoothly on 'rén', then land firmly on 'lèi'."}, "semantic_boundary_contrasts": {"core_nuance": "人类 refers to the entire human species on a macroscopic, evolutionary, or global civilizational scale.", "contrasts": [{"id": "1", "compared_word": "人类 vs. 人们", "pinyin": "rénmen", "analysis": "人们 refers casually to ordinary people or a crowd of individuals present ('人们议论纷纷'), while 人类 is the biological species or civilization as a whole."}, {"id": "2", "compared_word": "人类 vs. 人口", "pinyin": "rénkǒu", "analysis": "人口 is a demographic statistical term counting numbers of inhabitants in a country or city, while 人类 is anthropological."}, {"id": "3", "compared_word": "人类 vs. 人员", "pinyin": "rényuán", "analysis": "人员 denotes staff or personnel belonging to an organization ('医务人员'), completely distinct from species-wide 人类."}]}, "traps_and_cognates": {"look_alikes": [{"character": "入", "pinyin": "rù", "meaning_en": "enter", "distinction_note": "Right stroke overlaps left stroke, opposite of 人"}, {"character": "八", "pinyin": "bā", "meaning_en": "eight", "distinction_note": "Two strokes do not touch at the top"}, {"character": "粪", "pinyin": "fèn", "meaning_en": "manure; dung", "distinction_note": "Has 共 underneath 米 instead of 大 in 类"}, {"character": "迷", "pinyin": "mí", "meaning_en": "bewilder; lost", "distinction_note": "Has movement radical 辶 enclosing 米"}], "etymological_cognates": [{"character": "群", "pinyin": "qún", "gloss_en": "crowd; flock of sheep"}, {"character": "生", "pinyin": "shēng", "gloss_en": "life; birth of plant"}, {"character": "属", "pinyin": "shǔ", "gloss_en": "belong to; taxonomic genus"}, {"character": "民", "pinyin": "mín", "gloss_en": "people; populace"}]}, "id": "3", "hanzi": "人类", "pinyin": "rén lèi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the human race or species collectively, distinct from animals and divine beings", "definition_es": "el conjunto de seres humanos o la especie Homo sapiens en su totalidad", "example_phrase": "人类文明 (human civilization)"}], "example_sentences": [{"id": "#1", "hanzi": "探索未知浩瀚宇宙、寻找地外宜居星球，是整个人类自古以来共同怀揣的浪漫梦想。", "pinyin": "Tànsuǒ wèizhī hàohàn yǔzhòu, xúnzhǎo dìwài yíjū xīngqiú, shì zhěng gè rénlèi zìgǔ yǐlái gòngtóng huáichuāi de làngmàn mèngxiǎng.", "en": "Exploring the vast unknown cosmos and searching for habitable exoplanets is a romantic dream shared by all humanity since ancient times.", "es": "Explorar el cosmos ignoto y buscar planetas habitables es un sueño poético que comparte la humanidad entera desde tiempos remotos."}, {"id": "#2", "hanzi": "文字的发明与普及是人类进化史上的一座丰碑，它让人类的智慧与思想得以世代相传。", "pinyin": "Wénzì de fāmíng yǔ pǔjí shì rénlèi jìnhuà shǐ shàng de yí zuò fēngbēi, tā ràng rénlèi de zhìhuì yǔ sīxiǎng déyǐ shìdài xiāngchuán.", "en": "The invention and spread of writing marks a milestone in human evolution, enabling human wisdom and ideas to be passed across generations.", "es": "La invención y difusión de la escritura marca un hito en la evolución humana, permitiendo transmitir la sabiduría de generación en generación."}], "collocations": [{"hanzi": "人类社会", "en": "human society"}, {"hanzi": "人类文明", "en": "human civilization"}, {"hanzi": "全人类", "en": "all humankind; entire humanity"}, {"hanzi": "人类历史", "en": "human history"}, {"hanzi": "人类基因", "en": "human genome/genes"}, {"hanzi": "人类命运共同体", "en": "community with a shared future for mankind"}], "idioms": [{"hanzi": "生生不息", "pinyin": "shēng shēng bù xī", "meaning_en": "perpetuate endlessly; continuous reproduction and renewal"}, {"hanzi": "源远流长", "pinyin": "yuán yuǎn liú cháng", "meaning_en": "have a long history and deep roots; date back to remote antiquity"}, {"hanzi": "改天换地", "pinyin": "gǎi tiān huàn dì", "meaning_en": "transform heaven and earth; reshape the physical world"}, {"hanzi": "薪火相传", "pinyin": "xīn huǒ xiāng chuán", "meaning_en": "pass the torch from generation to generation"}], "character_decomposition": [{"character": "人", "pinyin": "rén", "meaning_en": "person; human; mankind", "meaning_es": "persona; ser humano; hombre", "radical": "人", "radical_meaning_en": "human", "meaning_component": "人 (side profile of walking bipedal human)", "sound_component": "人 (rén)", "stroke_count": "2", "composition_type": "单一结构", "etymology_and_mnemonic": "Oracle bone pictograph depicting a person standing upright on two feet with arms extended forward.", "visual_mnemonic_story_en": "Two sturdy legs stride forward upright, embodying the noble human being (人).", "visual_mnemonic_story_es": "Dos piernas firmes avanzan erguidas dibujando la silueta del ser humano (人).", "tone_mnemonic_anchor": "35", "cangjie": "O", "traditional": ""}, {"character": "类", "pinyin": "lèi", "meaning_en": "kind; type; category; class; species", "meaning_es": "clase; especie; categoría; tipo", "radical": "米", "radical_meaning_en": "rice", "meaning_component": "米 (grains of rice of same variety) + 犬 (hound sorting species)", "sound_component": "类 (lèi)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Sorting grains of harvested rice 米 by variety and breed; signifies category, species, and kinds.", "visual_mnemonic_story_en": "Grains of rice (米) sorted into distinct types (大) define a biological class or species (类).", "visual_mnemonic_story_es": "Granos de arroz (米) seleccionados por variedades (大) tipifican una clase o especie (类).", "tone_mnemonic_anchor": "51", "cangjie": "FDK", "traditional": "類"}], "extended_reading_passages": [{"id": "#1", "hanzi": "从原始狩猎采集时代学会使用火与石器，到现代掌握人工智能与核能，人类在漫长的数万年漫漫岁月中创造了璀璨辉煌的物质与精神文明。然而伴随科技进步，如何与自然万物和谐相处，已成为全人类必须正视的课题。", "pinyin": "Cóng yuánshǐ shòuliè-cǎijí shídài xuéhuì shǐyòng huǒ yǔ shíqì, dào xiàndài zhǎngwò réngōng zhìnéng yǔ hénéng, rénlèi zài màncháng de shùwàn nián mànmàn suìyuè zhōng chuàngzào le cuǐcàn huīhuáng de wùzhì yǔ jīngshén wénmíng. Rán'ér bànsuí kējì jìnbù, rúhé yǔ zìrán wànwù héxié xiāngchǔ, yǐ chéngwéi quán rénlèi bìxū zhèngshì de kètí.", "en": "From mastering fire and flint tools to modern AI and nuclear energy, humankind created brilliant civilizations over millennia. Yet as science advances, living in harmony with nature is an imperative for all humanity.", "es": "Desde dominar el fuego y la piedra hasta la inteligencia artificial y la energía atómica, el ser humano forjó civilizaciones brillantes. Ahora, convivir en armonía con la biosfera es el gran dilema de la humanidad."}, {"id": "#2", "hanzi": "面对气候恶化、生态失衡与跨国流行疾病等重大全球性危机，没有哪一个国家或民族能够独善其身。各国应当超越意识形态偏见与地缘政治争端，秉持人类命运共同体理念，携手筑牢守护地球家园的安全屏障。", "pinyin": "Miànduì qìhòu èhuà, shēngtài shīhéng yǔ kuàguó liúxíng jíbìng děng zhòngdà quánqiúxìng wēijī, méiyǒu nǎ yí ge guójiā huò mínzú nénggòu dúshàn-qíshēn. Gèguó yīngdāng chāoyuè yìshí-xíngtài piānjiàn yǔ dìyuán zhèngzhì zhēngduān, bǐngchí rénlèi mìngyùn gòngtóngtǐ lǐniàn, xiéshǒu zhùláo shǒuhù Dìqiú jiāyuán de ānquán píngzhàng.", "en": "Confronting climate crises and pandemics, no country can stand in isolation. Transcending ideological biases, nations must uphold a shared community for mankind, building barriers to protect our planet.", "es": "Ante la crisis climática y las pandemias globales, ningún país se salva en solitario. Superando rivalidades geopolíticas, las naciones deben cobijar un destino compartido para blindar el hogar terrenal común."}]}, {"meanings_summary": {"en": "mechanism; internal workings; operating structure", "es": "mecanismo; engranaje interno; funcionamiento orgánico"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A machine trigger (机) functioning under regulated rules (制) constitutes a mechanism (机制).", "composite_memory_hook_es": "Un disparador mecánico (机) que actúa bajo una pauta regulada (制) integra un mecanismo (机制).", "cultural_and_cognitive_roots": "Scientific calque translating 'mechanism' (mechanics of machinery) into biological physiology (生理机制) and administrative governance.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling tone: 'jī zhì' (55-51). Hold high pitch 55 on 'jī', then descend firmly on 'zhì'."}, "semantic_boundary_contrasts": {"core_nuance": "机制 designates the dynamic internal processes and interrelationships causing an organism, engine, or policy to function.", "contrasts": [{"id": "1", "compared_word": "机制 vs. 体制", "pinyin": "tǐzhì", "analysis": "体制 refers to macroscopic static state structures and political/economic governance frameworks ('政治体制'), while 机制 refers to active operational processes."}, {"id": "2", "compared_word": "机制 vs. 制度", "pinyin": "zhìdù", "analysis": "制度 refers to written statutory rules, codes of conduct, or laws ('规章制度'), while 机制 is how components interact in practice."}, {"id": "3", "compared_word": "机制 vs. 器官", "pinyin": "qìguān", "analysis": "器官 is an anatomical bodily organ (heart, lungs), while 机制 is the physiological process coordinating those organs."}]}, "traps_and_cognates": {"look_alikes": [{"character": "饥", "pinyin": "jī", "meaning_en": "hungry; famine", "distinction_note": "Has food radical 饣 on left instead of wood 木 in 机"}, {"character": "肌", "pinyin": "jī", "meaning_en": "muscle; flesh", "distinction_note": "Has flesh radical 月 on left"}, {"character": "到", "pinyin": "dào", "meaning_en": "arrive; reach", "distinction_note": "Has 至 on left of 刂 instead of 制's left side"}, {"character": "刷", "pinyin": "shuā", "meaning_en": "brush; swipe", "distinction_note": "Has 尸 on left of 刂"}], "etymological_cognates": [{"character": "体", "pinyin": "tǐ", "gloss_en": "body; structural system"}, {"character": "理", "pinyin": "lǐ", "gloss_en": "jade veins; principle"}, {"character": "度", "pinyin": "dù", "gloss_en": "measure; degree; system"}, {"character": "构", "pinyin": "gòu", "gloss_en": "construct; frame of timbers"}]}, "id": "4", "hanzi": "机制", "pinyin": "jī zhì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the structural parts and interworking processes of a biological organism, machine, or social institution", "definition_es": "estructura, funcionamiento o conjunto de procesos coordinados de un organismo, máquina o sistema social", "example_phrase": "工作机制 / 防御机制 (working mechanism / defense mechanism)"}], "example_sentences": [{"id": "#1", "hanzi": "诺贝尔生理学或医学奖得主成功阐明了控制人体生物钟昼夜节律的分子运转机制。", "pinyin": "Nuòbèi'ěr shēnglǐxué huò yīxuéjiǎng dézhǔ chénggōng chǎnmíng le kòngzhì réntǐ shēngwùzhōng zhòuyè jiélǜ de fēnzǐ yùnzhuǎn jīzhì.", "en": "Nobel laureates in Physiology or Medicine successfully elucidated the molecular operating mechanism controlling the human circadian clock.", "es": "Los laureados con el Nobel de Medicina desentrañaron el mecanismo molecular que regula el ritmo circadiano del reloj biológico humano."}, {"id": "#2", "hanzi": "为了有效遏制市场垄断行为，监管部门迅速建立起了跨部门联合执法的常态化工作机制。", "pinyin": "Wèile yǒuxiào èzhì shìchǎng lǒngduàn xíngwéi, jiānguǎn bùmén xùnsù jiànlì qǐ le kuà-bùmén liánhé zhífǎ de chángtàihuà gōngzuò jīzhì.", "en": "To curb market monopolistic behavior, regulators rapidly instituted a normalized inter-departmental joint enforcement mechanism.", "es": "Para frenar prácticas monopolísticas, las autoridades supervisoras establecieron un mecanismo interdepartamental permanente de inspección conjunta."}], "collocations": [{"hanzi": "长效机制", "en": "long-term mechanism"}, {"hanzi": "运行机制", "en": "operating/functioning mechanism"}, {"hanzi": "激励机制", "en": "incentive mechanism"}, {"hanzi": "防御机制", "en": "defense mechanism"}, {"hanzi": "形成机制", "en": "formation mechanism"}, {"hanzi": "调解机制", "en": "mediation mechanism"}], "idioms": [{"hanzi": "环环相扣", "pinyin": "huán huán xiāng kòu", "meaning_en": "interlinked closely like rings of a chain; tightly linked"}, {"hanzi": "相辅相成", "pinyin": "xiāng fǔ xiāng chéng", "meaning_en": "complement and reinforce each other"}, {"hanzi": "自圆其说", "pinyin": "zì yuán qí shuō", "meaning_en": "make one's statement consistent and plausible"}, {"hanzi": "因势利导", "pinyin": "yīn shì lì dǎo", "meaning_en": "guide action according to circumstances"}], "character_decomposition": [{"character": "机", "pinyin": "jī", "meaning_en": "machine; mechanism; trigger; opportunity", "meaning_es": "máquina; mecanismo; disparador; ocasión", "radical": "木", "radical_meaning_en": "wood", "meaning_component": "木 (wooden loom/crossbow mechanism) + 几 (small table / trigger)", "sound_component": "几 (jī, small table / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A wooden loom or the trigger mechanism 几 of a wooden crossbow 木; represents triggers and machinery.", "visual_mnemonic_story_en": "Wooden components (木) and sensitive triggers (几) spring into coordinated machine motion (机).", "visual_mnemonic_story_es": "Piezas de madera (木) y un gatillo sensible (几) se ensamblan en un mecanismo coordinado (机).", "tone_mnemonic_anchor": "55", "cangjie": "DHN", "traditional": "機"}, {"character": "制", "pinyin": "zhì", "meaning_en": "system; make; formulate; control; restrict", "meaning_es": "sistema; elaborar; formular; controlar", "radical": "刂", "radical_meaning_en": "knife", "meaning_component": "刂 (knife cutting to pattern) + 未/制 (tree branches shaped)", "sound_component": "制 (zhì)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "A knife 刂 pruning overgrown tree branches to follow regular form; signifies rules, systems, and manufacturing.", "visual_mnemonic_story_en": "A sharp knife (刂) trims wild branches into orderly, regulated shape (制).", "visual_mnemonic_story_es": "Un cuchillo afilado (刂) poda ramas desordenadas imponiendo un patrón regulado (制).", "tone_mnemonic_anchor": "51", "cangjie": "HBLN", "traditional": "製"}], "extended_reading_passages": [{"id": "#1", "hanzi": "人体免疫机制是一道精密神奇的生理防线。当外界病毒侵入机体时，免疫细胞会迅速启动识别机制，分工协作产生抗体将病原体围剿消灭，同时建立免疫记忆机制，为下一次抵御同类病菌打下坚实屏障。", "pinyin": "Réntǐ miǎnyì jīzhì shì yí dào jīngmì shénqí de shēnglǐ fángxiàn. Dāng wàijiè bìngdú qīnrù jītǐ shí, miǎnyì xìbāo huì xùnsù qǐdòng shíbié jīzhì, fēngōng-xiézuò chǎnshēng kàngtǐ jiāng bìngyuántǐ wéijiǎo xiāomiè, tóngshí jiànlì miǎnyì jìyì jīzhì, wèi xià yí cì dǐyù tónglèi bìngjūn dǎxià jiānshí píngzhàng.", "en": "The human immune mechanism is an intricate biological defense line. Upon viral invasion, immune cells trigger recognition mechanisms, cooperating to generate antibodies and establish memory.", "es": "El sistema inmunológico humano es un portentoso mecanismo de defensa. Ante virus invasores activa sensores celulares coordinando anticuerpos y fijando memorias que blindan futuras infecciones."}, {"id": "#2", "hanzi": "推进现代高新技术成果转化，亟须打破科研院所与企业之间的壁垒，构建起产学研深度融合的利益共享机制。唯有完善科技成果评估体系与收益分配激励机制，才能充分调动科研人员创新创业的内生动力与澎湃活力。", "pinyin": "Tuījìn xiàndài gāoxīnjìshù chéngguǒ zhuǎnhuà, jíxū dǎpò kēyán yuànsuǒ yǔ qǐyè zhījiān de bìlěi, gòujiàn qǐ chǎn-xué-yán shēndù rónghé de lìyì gòngxiǎng jīzhì. Wéiyǒu wánshàn kējì chéngguǒ pínggū tǐxì yǔ shòuyì fēnpèi jīlì jīzhì, cáinéng chōngfèn diàodòng kēyán rényuán chuàngxīn-chuàngyè de nèishēng dònglì yǔ péngpài huólì.", "en": "Translating high-tech achievements demands breaking barriers between institutes and enterprises to build profit-sharing mechanisms. Reforming incentives stimulates researchers' innovation vitality.", "es": "Para transferir tecnología punta urge tender puentes entre academias y empresas creando mecanismos de beneficio mutuo. Recompensar el mérito investigador desata el dinamismo emprendedor."}]}, {"meanings_summary": {"en": "living organism; living creature; biology", "es": "ser vivo; organismo vivo; criatura; biología"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Living, growing entities (生) among the physical things of the world (物) constitute organisms (生物).", "composite_memory_hook_es": "Entidades que gozan de vida y crecimiento (生) entre las materias del orbe (物) son los seres vivos (生物).", "cultural_and_cognitive_roots": "Classical philosophy (万物: myriad entities); in modern science, 生物 translates both biological organisms and academic biology.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling tone: 'shēng wù' (55-51). Hold high pitch 55 on 'shēng', then drop decisively on 'wù'."}, "semantic_boundary_contrasts": {"core_nuance": "生物 is the comprehensive biological term for all living organisms possessing cellular metabolism.", "contrasts": [{"id": "1", "compared_word": "生物 vs. 动物", "pinyin": "dòngwù", "analysis": "动物 is a subset of 生物 specifically designating motile animals, whereas 生物 includes plants, fungi, and bacteria."}, {"id": "2", "compared_word": "生物 vs. 植物", "pinyin": "zhíwù", "analysis": "植物 specifically designates photosynthesizing flora, which is only one branch of 生物."}, {"id": "3", "compared_word": "生物 vs. 活物", "pinyin": "huówù", "analysis": "活物 is a folksy colloquial term for live animals ('笼子里有活物'), while 生物 is rigorous and academic."}]}, "traps_and_cognates": {"look_alikes": [{"character": "牛", "pinyin": "niú", "meaning_en": "cow; bull", "distinction_note": "Vertical stroke crosses top stroke, unlike 生"}, {"character": "午", "pinyin": "wǔ", "meaning_en": "noon; 7th earthly branch", "distinction_note": "Has two horizontal strokes"}, {"character": "特", "pinyin": "tè", "meaning_en": "special", "distinction_note": "Has 寺 on right of 牜 instead of 勿 in 物"}, {"character": "牧", "pinyin": "mù", "meaning_en": "herd; pasture", "distinction_note": "Has tap radical 攵 on right of 牜"}], "etymological_cognates": [{"character": "植", "pinyin": "zhí", "gloss_en": "plant; upright tree"}, {"character": "兽", "pinyin": "shòu", "gloss_en": "beast; four-footed mammal"}, {"character": "命", "pinyin": "mìng", "gloss_en": "life span; command"}, {"character": "禽", "pinyin": "qín", "gloss_en": "birds; feathered fowl"}]}, "id": "5", "hanzi": "生物", "pinyin": "shēng wù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "living beings having vitality, growth, metabolism, and reproduction (animals, plants, microbes)", "definition_es": "ser que posee vida, capaz de nutrirse, crecer y reproducirse (animales, plantas, microorganismos)", "example_phrase": "海洋生物 (marine organisms)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the academic subject or science of biology", "definition_es": "la asignatura académica o ciencia de la biología", "example_phrase": "生物课 (biology class)"}], "example_sentences": [{"id": "#1", "hanzi": "热带雨林是地球上生物多样性最为丰富的宝库，栖息着数百万种未被人类发现的奇异生物。", "pinyin": "Rèdài yǔlín shì Dìqiú shàng shēngwù duōyàngxìng zuìwéi fēngfù de bǎokù, qīxī zhe shùbǎiwàn zhǒng wèibèi rénlèi fāxiàn de qíyì shēngwù.", "en": "Tropical rainforests are Earth's richest treasure troves of biodiversity, harboring millions of exotic living species undiscovered by humans.", "es": "La selva tropical es el tesoro de mayor biodiversidad del planeta, albergando millones de singulares seres vivos aún ignotos para la ciencia."}, {"id": "#2", "hanzi": "高三年级的生物老师通过生动形象的三维模型动画，深入浅出地讲解了细胞分裂过程。", "pinyin": "Gāosān niánjí de shēngwù lǎoshī tōngguò shēngdòng-xíngxiàng de sānwéi móxíng dònghuà, shēnrù-qiǎnchū de jiǎngjiě le xìbāo fēnliè guòchéng.", "en": "The high school senior biology teacher used vivid 3D animation models to explain the cell division process with remarkable clarity.", "es": "El profesor de biología de bachillerato explicó el proceso de mitosis celular con diáfana sencillez mediante animaciones 3D."}], "collocations": [{"hanzi": "生物多样性", "en": "biodiversity"}, {"hanzi": "生物钟", "en": "biological clock; circadian rhythm"}, {"hanzi": "海洋生物", "en": "marine life / organisms"}, {"hanzi": "微生物", "en": "microorganism; microbe"}, {"hanzi": "生物工程", "en": "bioengineering; biotechnology"}, {"hanzi": "水生生物", "en": "aquatic organisms"}], "idioms": [{"hanzi": "万物复苏", "pinyin": "wàn wù fù sū", "meaning_en": "all living things revive and return to life in spring"}, {"hanzi": "生机勃勃", "pinyin": "shēng jī bó bó", "meaning_en": "brimming with vitality; flourishing and vigorous"}, {"hanzi": "生生不息", "pinyin": "shēng shēng bù xī", "meaning_en": "endless generation and ceaseless cycle of life"}, {"hanzi": "芸芸众生", "pinyin": "yún yún zhòng shēng", "meaning_en": "all living mortals; the teeming masses of beings"}], "character_decomposition": [{"character": "生", "pinyin": "shēng", "meaning_en": "life; give birth; grow; raw; fresh", "meaning_es": "vida; nacer; brotar; crudo; vivo", "radical": "生", "radical_meaning_en": "life / birth", "meaning_component": "土 (fertile soil) + 屮 (young sprout budding upward)", "sound_component": "生 (shēng)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Oracle bone pictograph of a green seedling 屮 sprouting out from the fertile earth 土; represents life, growth, and birth.", "visual_mnemonic_story_en": "A tender shoot sprouts up from fertile soil, bursting with fresh life (生).", "visual_mnemonic_story_es": "Un brote verde brota pujante de la tierra fértil rebosando nueva vida (生).", "tone_mnemonic_anchor": "55", "cangjie": "HQM", "traditional": ""}, {"character": "物", "pinyin": "wù", "meaning_en": "thing; object; matter; creature", "meaning_es": "cosa; objeto; materia; criatura", "radical": "牜", "radical_meaning_en": "cow / ox", "meaning_component": "牜 (spotted cattle) + 勿 (multicolored flags / diverse things)", "sound_component": "勿 (wù, do not / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Cattle radical 牜 paired with multicolored banners 勿; sorting speckled domestic cattle, generalizing to all worldly objects and creatures.", "visual_mnemonic_story_en": "An ox (牜) plows fields amidst diverse colored banners (勿), classifying things (物).", "visual_mnemonic_story_es": "Un buey (牜) pasta entre banderas multicolores (勿) que clasifican los seres y cosas (物).", "tone_mnemonic_anchor": "51", "cangjie": "HQPHI", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在漆黑冰冷的万米深海马里亚纳海沟底部，承受着常人难以想象的超高水压。然而科学家们惊喜地发现，这里并非生命的荒漠，许多特化的深海发光生物依靠地热喷口附近的化学能量生生不息，展现了生命极致的适应力。", "pinyin": "Zài qīhēi bīnglěng de wànmǐ shēnhǎi Mǎlǐyànà Hǎigōu dǐbù, chéngshòu zhe chángrén nányǐ xiǎngxiàng de chāogāo shuǐyā. Rán'ér kēxuéjiāmen jīngxǐ de fāxiàn, zhèlǐ bìngfēi shēngmìng de huāngmò, xǔduō tèhuà de shēnhǎi fāguāng shēngwù yīkào dìrè pēnkǒu fùjìn de huàxué néngliàng shēngshēng-bùxī, zhǎnxiàn le shēngmìng jízhì de shìyìnglì.", "en": "At the freezing bottom of the Mariana Trench, high hydrostatic pressures reign. Yet scientists discovered it is no desert; bioluminescent organisms thrive near hydrothermal vents, proving life's resilience.", "es": "En la sima de las Marianas reina una presión titánica. Empero, los oceanógrafos hallaron que no es un erial; seres bioluminiscentes prosperan junto a fumarolas térmicas revelando la tenacidad de la vida."}, {"id": "#2", "hanzi": "保护生物多样性就是保护人类自身的未来。每一种生物都是漫长演化历史中不可复制的宝贵基因库，一旦灭绝便永远无法挽回。建立国家公园体制、严格划定生态保护红线，正是为了给野生动植物留下充足繁衍生息的乐土。", "pinyin": "Bǎohù shēngwù duōyàngxìng jiùshì bǎohù rénlèi zìshēn de wèilái. Měi yì zhǒng shēngwù dōu shì màncháng yǎnhuà lìshǐ zhōng bùkě fùzhì de bǎoguì jīyīnkù, yídàn mièjué biàn yǒngyuǎn wúfǎ wǎnhuí. Jiànlì guójiā gōngyuán tǐzhì, yángé huàdìng shēngtài bǎohù hóngxiàn, zhèngshì wèile gěi yěshēng dòng-zhíwù liúxià chōngzú fányǎn-shēngxī de lètǔ.", "en": "Protecting biodiversity is safeguarding humanity's future. Every species is an irreplaceable genetic library; once extinct, it is lost forever. National park systems preserve habitats for wildlife to multiply.", "es": "Preservar la biodiversidad es blindar el porvenir humano. Cada organismo es un banco genético irrepetible cuya extinción es irreparable. La red de parques nacionales brinda a la fauna y flora un edén seguro."}]}, {"meanings_summary": {"en": "law; regular pattern; rule; regular; disciplined", "es": "ley natural; pauta regular; norma; ordenado; regular"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A compass establishing standards (规) combined with recorded legal and pitch codes (律) reveals regular laws (规律).", "composite_memory_hook_es": "El compás de trazar normas (规) y el código de leyes escritas (律) revelan las pautas regulares (规律).", "cultural_and_cognitive_roots": "Derived from classical standardizing tools (规 compass + 矩 square) paired with acoustic pitch pipes (十二律: twelve musical pitches); laws of the cosmos.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling tone: 'guī lǜ' (55-51). Hold high pitch 55 on 'guī', then drop down sharply on 'lǜ'."}, "semantic_boundary_contrasts": {"core_nuance": "规律 denotes the invariant, inherent objective laws of science/nature, or disciplined regularity of habits.", "contrasts": [{"id": "1", "compared_word": "规律 vs. 规则", "pinyin": "guīzé", "analysis": "规则 refers to artificial, human-made regulations and game rules ('交通规则', '比赛规则'), while 规律 refers to inviolable objective natural laws ('自然规律')."}, {"id": "2", "compared_word": "规律 vs. 法律", "pinyin": "fǎlǜ", "analysis": "法律 refers specifically to the penal and civil statutes enacted by the state legislature, whereas 规律 is universal and scientific."}, {"id": "3", "compared_word": "规律 vs. 惯例", "pinyin": "guànlì", "analysis": "惯例 denotes customary conventions established through precedent, not necessary underlying scientific patterns."}]}, "traps_and_cognates": {"look_alikes": [{"character": "视", "pinyin": "shì", "meaning_en": "look; inspect", "distinction_note": "Has altar radical 礻 on left instead of 夫 in 规"}, {"character": "现", "pinyin": "xiàn", "meaning_en": "appear; present", "distinction_note": "Has jade radical 王 on left of 见"}, {"character": "津", "pinyin": "jīn", "meaning_en": "ferry; saliva", "distinction_note": "Has water radical 氵 on left of 聿 instead of 彳 in 律"}, {"character": "建", "pinyin": "jiàn", "meaning_en": "build; construct", "distinction_note": "Has long stride 廴 enclosing 聿"}], "etymological_cognates": [{"character": "法", "pinyin": "fǎ", "gloss_en": "law; water level fairness"}, {"character": "矩", "pinyin": "jǔ", "gloss_en": "carpenter square rule"}, {"character": "则", "pinyin": "zé", "gloss_en": "knife carving standard rule"}, {"character": "常", "pinyin": "cháng", "gloss_en": "constant invariant cloth"}]}, "id": "6", "hanzi": "规律", "pinyin": "guī lǜ", "level": "HSK 5", "part_of_speech": "Noun / Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "objective inner connections and necessary laws governing the development of things", "definition_es": "ley intrínseca objetiva o pauta constante que rige el desarrollo de los fenómenos", "example_phrase": "自然规律 (laws of nature)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "regular, disciplined, and recurring at orderly predictable intervals", "definition_es": "ordenado, pautado o regular en horarios y hábitos", "example_phrase": "生活很有规律 (lead a regular/disciplined life)"}], "example_sentences": [{"id": "#1", "hanzi": "遵循大自然春生夏长、秋收冬藏的客观规律，农业生产才能获得丰厚的回报。", "pinyin": "Zūnxún dànzìrán chūnshēng-xiàzhǎng, qiūshōu-dōngcáng de kèguān guīlǜ, nóngyè shēngchǎn cáinéng huòdé fēnghòu de huíbào.", "en": "Only by following nature's objective laws of seasonal growth and harvest can agricultural production reap abundant yields.", "es": "Acatando las leyes objetivas de la naturaleza según las estaciones, el cultivo agrícola rinde cosechas ubérrimas."}, {"id": "#2", "hanzi": "坚持健康科学的作息规律，保证充足睡眠和合理饮食，是增强身体免疫力的基石。", "pinyin": "Jiānchí jiànkāng kēxué de zuòxī guīlǜ, bǎozhèng chōngzú shuìmián hé hélǐ yǐnshí, shì zēngqiáng shēntǐ miǎnyìlì de jīshí.", "en": "Maintaining regular, scientific daily routines with ample sleep and balanced diet forms the foundation of immune vitality.", "es": "Mantener hábitos diarios regulares y saludables con sueño reparador y dieta equilibrada es la base del vigor inmunológico."}], "collocations": [{"hanzi": "自然规律", "en": "laws of nature"}, {"hanzi": "客观规律", "en": "objective law/pattern"}, {"hanzi": "生活规律", "en": "regular lifestyle habits"}, {"hanzi": "作息规律", "en": "regular daily routine"}, {"hanzi": "寻找规律", "en": "search for patterns/laws"}, {"hanzi": "发展规律", "en": "developmental laws"}], "idioms": [{"hanzi": "按图索骥", "pinyin": "àn tú suǒ jì", "meaning_en": "look for a noble steed according to a picture; act by rules"}, {"hanzi": "墨守成规", "pinyin": "mò shǒu chéng guī", "meaning_en": "stick stubbornly to obsolete rules"}, {"hanzi": "循规蹈矩", "pinyin": "xún guī dǎo jǔ", "meaning_en": "follow rules strictly; abide by convention"}, {"hanzi": "铁证如山", "pinyin": "tiě zhèng rú shān", "meaning_en": "irrefutable evidence as solid as a mountain"}], "character_decomposition": [{"character": "规", "pinyin": "guī", "meaning_en": "compass; rule; regulate; plan", "meaning_es": "compás; regla; pauta; planificar", "radical": "见", "radical_meaning_en": "see", "meaning_component": "夫 (measuring master) + 见 (observing eye)", "sound_component": "规 (guī)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "A person observing with eye 见 holding a drawing compass 夫 to draw a perfect circle; represents rules and standards.", "visual_mnemonic_story_en": "A watchful eye (见) guides a compass (夫) to draw a perfect circle according to rule (规).", "visual_mnemonic_story_es": "Un ojo atento (见) guía el compás de dibujo (夫) trazando círculos según la regla (规).", "tone_mnemonic_anchor": "55", "cangjie": "QOUU", "traditional": "規"}, {"character": "律", "pinyin": "lǜ", "meaning_en": "law; pitch; regulate; rhythm", "meaning_es": "ley; tono; ritmo; precepto", "radical": "彳", "radical_meaning_en": "step / walk", "meaning_component": "彳 (step / walking on path) + 聿 (hand holding scribe brush)", "sound_component": "律 (lǜ)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "A scribe brush 聿 recording laws for travelers walking the public street 彳; represents laws, codes, and musical pitches.", "visual_mnemonic_story_en": "A hand writes laws with a brush (聿) to govern footsteps along public highways (彳).", "visual_mnemonic_story_es": "Una mano escribe decretos con pincel (聿) para ordenar los pasos por el camino real (彳).", "tone_mnemonic_anchor": "51", "cangjie": "HOLQ", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "日月星辰运行不息，春夏秋冬寒来暑往，大自然以其严整深邃的规律维系着生态系统的动态平衡。人类若狂妄自大企图凌驾于自然之上盲目索取，必将遭受客观自然规律的严厉惩罚与无回报应。", "pinyin": "Rì-yuè-xīngchén yùnxíng bùxī, chūn-xià-qiū-dōng hánlái-shǔwǎng, dànzìrán yǐ qí yánzhěng shēnsù de guīlǜ wéixì zhe shēngtài xìtǒng de dòngtài pínghéng. Rénlèi ruò kuángwàng-zìdà qǐtú língjià yú zìrán zhīshàng mángmù suǒqǔ, bìjiāng zāoshòu kèguān zìrán guīlǜ de yánlì chéngfá yǔ wúqíng bàoyìng.", "en": "Stars turn endlessly and seasons cycle; nature maintains ecological balance through deep laws. If humans arrogantly exploit resources blind to these laws, nature will punish us severely.", "es": "Los astros giran y las estaciones se suceden; la naturaleza preserva su equilibrio dinámico mediante leyes inexorables. Si el hombre depreda con soberbia, la ley cósmica impondrá su castigo."}, {"id": "#2", "hanzi": "在现代金融投资领域，优秀的基金经理从不轻信虚幻的市场传言，而是潜心通过历史大数据挖掘资本市场运转的内在规律。只有顺应宏观经济周期规律、坚守理性价值投资，才能在惊涛骇浪的市场波动中行稳致远。", "pinyin": "Zài xiàndài jīnróng tóuzī lǐngyù, yōuxiù de jījīn jīnglǐ cóng bù qīngxìn xūhuàn de shìchǎng chuányán, érshì qiánxīn tōngguò lìshǐ dàshùjù wājué zīběn shìchǎng yùnzhuǎn de nèizài guīlǜ. Zhǐyào shùnyìng hóngguān jīngjì zhōuqī guīlǜ, jiānshǒu lǐxìng jiàzhí tóuzī, cáinéng zài jīngtāo-hàilàng de shìchǎng bōdòng zhōng xíngwěn-zhìyuǎn.", "en": "In finance, astute fund managers rely on big data to uncover intrinsic patterns of capital markets rather than rumors. Following economic cycles and disciplined value investing yields steady returns amidst volatility.", "es": "En finanzas, los gestores expertos desdeñan rumores para rastrear las leyes del mercado mediante datos masivos. Acatar los ciclos macroeconómicos con sensatez garantiza navegar la volatilidad con éxito."}]}, {"meanings_summary": {"en": "light; light ray; beam of light", "es": "luz; rayo de luz; haz luminoso; iluminación"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Torches shedding radiant illumination (光) extending in linear threads (线) make beams of light (光线).", "composite_memory_hook_es": "La antorcha que alumbra (光) trazando hebras rectas en la penumbra (线) forma el haz de luz (光线).", "cultural_and_cognitive_roots": "Optical geometric physics; traditional Chinese shadow puppetry (皮影戏) mastered the projection of luminous lines through translucent parchment.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling fourth tone: 'guāng xiàn' (55-51). Hold high pitch 55 on 'guāng', then drop down sharply on 'xiàn'."}, "semantic_boundary_contrasts": {"core_nuance": "光线 designates linear rays of optical illumination or environmental ambient lighting conditions.", "contrasts": [{"id": "1", "compared_word": "光线 vs. 光芒", "pinyin": "guāngmáng", "analysis": "光芒 emphasizes brilliant, dazzling radiating halos ('太阳的光芒', '放射光芒'), while 光线 is neutral physical illumination ('光线太暗')."}, {"id": "2", "compared_word": "光线 vs. 阳光", "pinyin": "yángguāng", "analysis": "阳光 is specifically natural sunlight from the solar orb, while 光线 includes artificial bulbs, laser beams, and candles."}, {"id": "3", "compared_word": "光线 vs. 灯光", "pinyin": "dēngguāng", "analysis": "灯光 specifically denotes the glow produced by manufactured electric lamps, whereas 光线 covers all rays."}]}, "traps_and_cognates": {"look_alikes": [{"character": "先", "pinyin": "xiān", "meaning_en": "first; ancestor", "distinction_note": "Has 丿 on top instead of central dot and stroke of 光"}, {"character": "充", "pinyin": "chōng", "meaning_en": "fill; charge", "distinction_note": "Has 亠 atop 厶 and 儿"}, {"character": "钱", "pinyin": "qián", "meaning_en": "money; coin", "distinction_note": "Has metal radical 钅 on left instead of silk 纟 in 线"}, {"character": "浅", "pinyin": "qiǎn", "meaning_en": "shallow; light", "distinction_note": "Has water radical 氵 on left of 戋"}], "etymological_cognates": [{"character": "芒", "pinyin": "máng", "gloss_en": "ray of light; awn of grass"}, {"character": "束", "pinyin": "shù", "gloss_en": "bundle; beam of rays"}, {"character": "缕", "pinyin": "lǚ", "gloss_en": "strand; wisp of smoke/light"}, {"character": "照", "pinyin": "zhào", "gloss_en": "shine; illuminate path"}]}, "id": "7", "hanzi": "光线", "pinyin": "guāng xiàn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a ray, beam, or ambient condition of visible illumination emitted from a light source", "definition_es": "haz o rayo luminoso proyectado por una fuente de luz, o iluminación ambiental", "example_phrase": "光线充足 (plenty of light / well-lit)"}], "example_sentences": [{"id": "#1", "hanzi": "清晨拉开厚厚的窗帘，温暖明媚的金色光线洒满了整间宽敞的书房。", "pinyin": "Qīngchén lākāi hòuhòu de chuānglián, wēnnuǎn míngmèi de jīnsè guāngxiàn sǎmǎn le zhěng jiān kuānchǎng de shūfáng.", "en": "Drawing open thick curtains in the morning, warm golden rays of light spilled across the spacious study.", "es": "Al descorrer las tupidas cortinas por la mañana, los cálidos rayos dorados de luz inundaron el amplio despacho."}, {"id": "#2", "hanzi": "在光线昏暗的环境下长时间阅读电子屏幕，极易导致眼睛睫状肌疲劳与近视度数加深。", "pinyin": "Zài guāngxiàn hūn'àn de huánjìng xià cháng shíjiān yuèdú diànzǐ píngmù, jíyì dǎozhì yǎnjing jiézhuàngjī píbèi yǔ jìnshì dùshù jiāshēn.", "en": "Reading electronic screens for extended hours in dimly lit environments easily causes eye strain and worsening myopia.", "es": "Leer pantallas electrónicas en un entorno de luz tenue fatiga los músculos oculares y acelera la miopía."}], "collocations": [{"hanzi": "光线柔和", "en": "soft/gentle light"}, {"hanzi": "光线充足", "en": "well-lit; sufficient lighting"}, {"hanzi": "光线昏暗", "en": "dimly lit; poor lighting"}, {"hanzi": "强烈的阳光光线", "en": "intense sunlight rays"}, {"hanzi": "阻挡光线", "en": "block light"}, {"hanzi": "调整光线", "en": "adjust the lighting"}], "idioms": [{"hanzi": "浮光掠影", "pinyin": "fú guāng lüè yǐng", "meaning_en": "skimming over light and shadow; superficial impression"}, {"hanzi": "光彩夺目", "pinyin": "guāng cǎi duó mù", "meaning_en": "dazzlingly brilliant; radiant and colorful"}, {"hanzi": "日月生辉", "pinyin": "rì yuè shēng huī", "meaning_en": "sun and moon shining with radiant splendor"}, {"hanzi": "流光溢彩", "pinyin": "liú guāng yì cǎi", "meaning_en": "flowing with radiance and overflowing with color"}], "character_decomposition": [{"character": "光", "pinyin": "guāng", "meaning_en": "light; ray; glory; bare; only", "meaning_es": "luz; rayo; brillo; descalzo; solo", "radical": "儿", "radical_meaning_en": "human / legs", "meaning_component": "火 (fire torch) + 儿 (kneeling person carrying fire above head)", "sound_component": "光 (guāng)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Oracle bone pictograph of a human 儿 carrying a blazing torch 火 atop their head to illuminate the dark; represents light and radiance.", "visual_mnemonic_story_en": "A runner holds a blazing fire torch high overhead (火), illuminating the dark with radiant light (光).", "visual_mnemonic_story_es": "Una figura alza una antorcha de fuego (火) sobre su cabeza disipando las sombras con viva luz (光).", "tone_mnemonic_anchor": "55", "cangjie": "FMU", "traditional": ""}, {"character": "线", "pinyin": "xiàn", "meaning_en": "thread; string; wire; line; ray", "meaning_es": "hilo; hebra; línea; alambre; rayo", "radical": "纟", "radical_meaning_en": "silk", "meaning_component": "纟 (spun silk thread) + 戋 (small slender / phonetic)", "sound_component": "戋 (jiān, slender / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Spun silk threads 纟 stretching out in a thin linear fiber 戋; extended to geometric lines and straight optical rays.", "visual_mnemonic_story_en": "A delicate strand of silk (纟) pulls straight and thin like a linear beam (线).", "visual_mnemonic_story_es": "Una fina hebra de seda (纟) se estira recta y delgada dibujando una línea luminosa (线).", "tone_mnemonic_anchor": "51", "cangjie": "VMII", "traditional": "線"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在绘画与摄影艺术中，光线被称为塑造形象的“第二支画笔”。大师们熟练运用侧光展现人物面部坚毅深邃的轮廓，用逆光勾勒秀发的金色光晕，恰到好处的光线明暗反差赋予画面无限的生命力与艺术感染力。", "pinyin": "Zài huìhuà yǔ shèyǐng yìshù zhōng, guāngxiàn bèi chēngwéi sùzào xíngxiàng de 'dì-èr zhī huàbǐ'. Dàshīmen shúliàn yùnyòng cèguāng zhǎnxiàn rénwù miànbù jiānyì-shēnsù de lúnkuò, yòng nìguāng gōulè xiùfà de jīnsè guāngyùn, qiàdàohǎochù de guāngxiàn míng'àn fǎnchà fùyǔ huàmiàn wúxiàn de shēngmìnglì yǔ yìshù gǎnrǎnlì.", "en": "In painting and photography, light is called the second paintbrush. Masters skillfully use sidelight to sculpt facial profiles and backlighting to outline hair halos, infusing imagery with vital contrast.", "es": "En pintura y fotografía, la luz se considera el segundo pincel. Los maestros emplean luces laterales para cincelar perfiles y contraluces dorados, infundiendo un vivo contraste y plasticidad al lienzo."}, {"id": "#2", "hanzi": "盛夏午后烈日当空，茂密幽静的原始森林中，缕缕金色光线穿透重重叠叠的树冠枝叶倾泻而下，在布满松针的湿润地面上投下斑驳陆离的光影。这奇幻宁静的自然丁达尔效应景观，令人叹为观止、流连忘返。", "pinyin": "Shèngxià wǔhòu lièrì dāngkōng, màomì yōujìng de yuánshǐ sēnlín zhōng, lǚlǚ jīnsè guāngxiàn chuāntòu chóngchóng-diédié de shùguān zhīyè qīngxiè ér xià, zài bùmǎn sōngzhēn de shīrùn dīmiàn shàng tóuxià bānbó-lùlí de guāngyǐng. Zhè qíhuàn níngjìng de zìrán Dīngdá'ěr xiàoyìng jǐngguān, lìngrén tànwéiguānzhǐ, liúlián-wàngfǎn.", "en": "Under scorching midsummer sun, rays of golden light pierce dense forest canopies, casting dappled shadows over pine needles. This Tyndall effect phenomenon captivates visitors with quiet natural beauty.", "es": "Bajo el sol estival, hebras de luz dorada perforan el follaje del bosque virgen proyectando sombras sobre agujas de pino. El efecto Tyndall crea una estampa mágica y sosegada que embelesa al paseante."}]}, {"meanings_summary": {"en": "necessary; essential; indispensable", "es": "necesario; indispensable; esencial; imperativo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Decisive absolute certainty (必) paired with the vital waist pivot (要) makes something indispensable (必要).", "composite_memory_hook_es": "Certeza ineludible (必) y eje vital indispensable (要) conforman lo necesario (必要).", "cultural_and_cognitive_roots": "Philosophical logic pairing: 必 (categorical imperative) + 要 (vital pivot), widely used in logic (必要条件 vs. 充分条件).", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'bì yào' (51-51). Descend sharply on 'bì', then strike down firmly on 'yào'."}, "semantic_boundary_contrasts": {"core_nuance": "必要 emphasizes that a condition, action, or tool is indispensable and cannot be dispensed with.", "contrasts": [{"id": "1", "compared_word": "必要 vs. 重要", "pinyin": "zhòngyào", "analysis": "重要 describes high value, significance, or weight ('重要会议'), while 必要 emphasizes that an action is strictly mandatory or prerequisite ('有必要进行核实')."}, {"id": "2", "compared_word": "必要 vs. 必须", "pinyin": "bìxū", "analysis": "必须 is an adverb/auxiliary verb meaning 'must / have to' modifying verbs ('必须按时到达'), while 必要 is an adjective ('必要的步骤')."}, {"id": "3", "compared_word": "必要 vs. 需要", "pinyin": "xūyào", "analysis": "需要 functions as a common verb meaning 'to need / demand' ('需要帮助'), while 必要 is descriptive."}]}, "traps_and_cognates": {"look_alikes": [{"character": "心", "pinyin": "xīn", "meaning_en": "heart; mind", "distinction_note": "Lacks the long slash crossing stroke of 必"}, {"character": "毖", "pinyin": "bì", "meaning_en": "careful; caution", "distinction_note": "Consists of two 必 side by side"}, {"character": "耍", "pinyin": "shuǎ", "meaning_en": "play; juggle", "distinction_note": "Has 而 atop 女 instead of 覀 in 要"}, {"character": "妥", "pinyin": "tuǒ", "meaning_en": "proper; settled", "distinction_note": "Has 爪 atop 女"}], "etymological_cognates": [{"character": "需", "pinyin": "xū", "gloss_en": "rain on beard; need"}, {"character": "须", "pinyin": "xū", "gloss_en": "must; beard hairs"}, {"character": "重", "pinyin": "zhòng", "gloss_en": "heavy burden; important"}, {"character": "切", "pinyin": "qiè", "gloss_en": "cut close; urgent"}]}, "id": "8", "hanzi": "必要", "pinyin": "bì yào", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "indispensable, essential, or strictly required for achieving an objective", "definition_es": "indispensable, imperioso o preceptivo para lograr un fin o garantizar un resultado", "example_phrase": "有必要这样做 (it is necessary to do so)"}], "example_sentences": [{"id": "#1", "hanzi": "在野外进行高风险探险之前，做好充足的体能储备并携带必要的应急药品是绝对不可忽视的。", "pinyin": "Zài yěwài jìnxíng gāofēngxiǎn tànxiǎn zhīqián, zuòhǎo chōngzú de tǐnéng chǔbèi bìng xiédài bìyào de yīngjí yàopǐn shì juéduì bùkě hūshì de.", "en": "Before engaging in high-risk outdoor expeditions, preparing physical stamina and carrying necessary emergency medicines must never be neglected.", "es": "Antes de emprender una expedición arriesgada al aire libre, contar con buena preparación física y botiquines necesarios resulta imperativo."}, {"id": "#2", "hanzi": "为了确保工程项目保质保量如期交付，项目部认为有必要召开一次全员安全质量交底大会。", "pinyin": "Wèile quèbǎo gōngchéng xiàngmù bǎozhì-bǎoliàng rúqī jiāofù, xiàngmùbù rènwéi yǒu bìyào zhàokāi yí cì quányuán ānquán zhìliàng jiāodǐ dàhuì.", "en": "To ensure the engineering project is delivered on schedule with quality, the team considered it necessary to convene a safety briefing.", "es": "Para garantizar la entrega puntual y con calidad de la obra, la dirección estimó necesario convocar una junta general de seguridad."}], "collocations": [{"hanzi": "非常有必要", "en": "highly necessary; very essential"}, {"hanzi": "必要条件", "en": "necessary condition / prerequisite"}, {"hanzi": "必要措施", "en": "necessary measures"}, {"hanzi": "必要的准备", "en": "necessary preparations"}, {"hanzi": "毫无必要", "en": "completely unnecessary"}, {"hanzi": "视为必要", "en": "deemed necessary"}], "idioms": [{"hanzi": "不可或缺", "pinyin": "bù kě huò quē", "meaning_en": "indispensable; cannot do without"}, {"hanzi": "必不可少", "pinyin": "bì bù kě shǎo", "meaning_en": "absolutely essential; indispensable"}, {"hanzi": "刻不容缓", "pinyin": "kè bù róng huǎn", "meaning_en": "brook no delay; demand immediate action"}, {"hanzi": "迫在眉睫", "pinyin": "pò zài méi jié", "meaning_en": "imminent and urgent; pressing close to eyelashes"}], "character_decomposition": [{"character": "必", "pinyin": "bì", "meaning_en": "certainly; must; surely; necessary", "meaning_es": "sin falta; deber; forzoso; necesario", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "弋 (stake / split) + 八 (slash through / decisive resolve)", "sound_component": "必 (bì)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Originally a measuring weapon or divider stroke slashing decisively through; signifies certainty, necessity, and firmness.", "visual_mnemonic_story_en": "A firm slash cuts decisively across, making an unavoidable, necessary mark (必).", "visual_mnemonic_story_es": "Un trazo firme cruza con rotunda certeza fijando un imperativo ineludible (必).", "tone_mnemonic_anchor": "51", "cangjie": "PHX", "traditional": ""}, {"character": "要", "pinyin": "yào", "meaning_en": "want; need; must; vital; important", "meaning_es": "querer; necesitar; esencial; vital", "radical": "覀", "radical_meaning_en": "west / cover", "meaning_component": "覀 (two hands on human waist) + 女 (woman)", "sound_component": "要 (yào)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Original pictograph of hands resting on a woman's waist 女; waist being the vital pivot of the body, extended to vital necessity.", "visual_mnemonic_story_en": "Hands embrace the waist (覀) of a figure (女), holding the vital core of need (要).", "visual_mnemonic_story_es": "Manos que sujetan la cintura (覀) femenina (女) destacando el eje vital indispensable (要).", "tone_mnemonic_anchor": "51", "cangjie": "MWV", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代企业治理中，定期的财务审计是防范经营风险的必要手段。独立审计机构通过核查账目流水、盘点资产负债，能够及时发现管理漏洞与合规隐患，为企业稳健长远发展筑牢不可或缺的制度屏障。", "pinyin": "Zài xiàndài qǐyè zhìlǐ zhōng, dìngqī de cáiwù shěnjì shì fángfàn jīngyíng fēngxiǎn de bìyào shǒuduàn. Dúlì shěnjì jīgòu tōngguò héchá zhàngmù liúshuǐ, pándiǎn zīchǎn-fùzhài, nénggòu jíshí fāxiàn guǎnlǐ lòudòng yǔ hégūi yǐnhuàn, wèi qǐyè wěnjiàn chángyuǎn fāzhǎn zhùláo bùkě-huòquē de zhìdù píngzhàng.", "en": "In corporate governance, periodic financial audits are necessary tools to avert operational risks. Independent auditors verify balances to plug compliance loopholes, fortifying institutional barriers.", "es": "En la gestión corporativa, las auditorías financieras periódicas son un resorte necesario contra riesgos. Auditores independientes cotejan balances subsanando lagunas y afianzando la solvencia empresarial."}, {"id": "#2", "hanzi": "人际交往中，保持适当的心理边界是维护健康友谊的必要前提。即使再要好的知己朋友，也应当相互尊重彼此的私人空间与独立选择，不横加干涉。唯有保持这种有分寸的默契，友谊之花才能长盛不衰。", "pinyin": "Rénjì jiāowǎng zhōng, bǎochí shìdàng de xīnlǐ biānjiè shì wéihù jiànkāng yǒuyì de bìyào qiántí. Jíshǐ zài yàohǎo de zhījǐ péngyou, yě yīngdāng xiānghù zūnzhòng bǐcǐ de sīrén kōngjiān yǔ dúlì xuǎnzé, bù héngjiā gānshè. Wéiyǒu bǎochí zhè zhǒng yǒu fēncùn de mòqì, yǒuyì zhī huā cáinéng chángshèng-bùshuāi.", "en": "In interpersonal relations, healthy boundaries are a necessary prerequisite. Even the closest friends should respect private space and choices without meddling, allowing true friendship to flourish.", "es": "En el trato humano, delimitar el espacio personal es premisa necesaria para una amistad sana. Incluso íntimos camaradas deben respetar la intimidad ajena sin entrometerse para que florezca el aprecio mutuo."}]}, {"meanings_summary": {"en": "to transition; to transit; transition; interim phase", "es": "hacer la transición; transitar; transición; fase intermedia"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Crossing a boundary (过) like ferrying across a wide river (渡) achieves a smooth transition (过渡).", "composite_memory_hook_es": "Cruzar el linde (过) como quien cruza en barca el río (渡) describe la transición (过渡).", "cultural_and_cognitive_roots": "Ferry river crossing metaphor: ancient travelers took ferries (渡口) to cross treacherous currents; applied conceptually to shifts in politics and physiology.", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'guò dù' (51-51). Descend sharply on 'guò', then drop down decisively again on 'dù'."}, "semantic_boundary_contrasts": {"core_nuance": "过渡 emphasizes the progressive, intermediate bridging process between two distinct historical, physical, or physiological stages.", "contrasts": [{"id": "1", "compared_word": "过渡 vs. 转变", "pinyin": "zhuǎnbiàn", "analysis": "转变 emphasizes changing the direction, nature, or attitude of something ('转变观念'), while 过渡 emphasizes the temporal interim bridging phase."}, {"id": "2", "compared_word": "过渡 vs. 转换", "pinyin": "zhuǎnhuàn", "analysis": "转换 emphasizes switching between discrete modes or formats ('转换频道', '转换格式'), while 过渡 is a gradual smooth shift."}, {"id": "3", "compared_word": "过渡 vs. 过度", "pinyin": "guòdù", "analysis": "过度 (homophone with 度) means excessive or going beyond healthy limits ('过度疲劳', '过度饮酒'), while 过渡 means transition."}]}, "traps_and_cognates": {"look_alikes": [{"character": "这", "pinyin": "zhè", "meaning_en": "this", "distinction_note": "Has 文 inside 辶 instead of 寸 in 过"}, {"character": "进", "pinyin": "jìn", "meaning_en": "enter; advance", "distinction_note": "Has 井 inside 辶"}, {"character": "度", "pinyin": "dù", "meaning_en": "degree; measure", "distinction_note": "Lacks the water radical 氵 of 渡"}, {"character": "镀", "pinyin": "dù", "meaning_en": "plate; coat with metal", "distinction_note": "Has metal radical 钅 on left"}], "etymological_cognates": [{"character": "迁", "pinyin": "qiān", "gloss_en": "migrate; move house"}, {"character": "移", "pinyin": "yí", "gloss_en": "shift; transplant rice"}, {"character": "变", "pinyin": "biàn", "gloss_en": "change; alter form"}, {"character": "化", "pinyin": "huà", "gloss_en": "transform; melt"}]}, "id": "9", "hanzi": "过渡", "pinyin": "guò dù", "level": "HSK 5", "part_of_speech": "Verb / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to pass, shift, or transit smoothly from one stage, state, or era to another", "definition_es": "pasar, evolucionar o mudar paulatinamente de un estado o etapa a otra", "example_phrase": "平稳过渡 (smooth transition)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a transitional period, interim stage, or passage connecting two phases", "definition_es": "período de transición, fase intermedia o puente entre dos épocas", "example_phrase": "过渡时期 (transitional period)"}], "example_sentences": [{"id": "#1", "hanzi": "从深度睡眠到完全清醒，人体的中枢神经系统需要经历一段温和的生理过渡阶段。", "pinyin": "Cóng shēndù shuìmián dào wánquán qīngxǐng, réntǐ de zhōngshū shénjīng xìtǒng xūyào jīnglì yí duàn wēnhé de shēnglǐ guòdù jiēduàn.", "en": "From deep sleep to full alertness, the human central nervous system requires a gentle physiological transitional phase.", "es": "Del sueño profundo a la vigilia plena, el sistema nervioso central precisa un sosegado período de transición fisiológica."}, {"id": "#2", "hanzi": "在老厂长退休之际，新老管理团队密切配合，实现了企业经营管理权的平稳过渡。", "pinyin": "Zài lǎo chǎngzhǎng tuìxiū zhī jì, xīn-lǎo guǎnlǐ tuánduì mìqiè pèihé, shíxiàn le qǐyè jīngyíng guǎnlǐquán de píngwěn guòdù.", "en": "Upon the veteran director's retirement, new and old management teams collaborated closely, achieving a smooth handover of managerial power.", "es": "Con la jubilación del veterano director, la directiva saliente y entrante cooperaron estrechamente logrando un traspaso de poderes impecable."}], "collocations": [{"hanzi": "平稳过渡", "en": "smooth transition"}, {"hanzi": "过渡时期", "en": "transitional period"}, {"hanzi": "过渡阶段", "en": "interim/transition stage"}, {"hanzi": "自然过渡", "en": "natural transition"}, {"hanzi": "过渡性措施", "en": "transitional/interim measures"}, {"hanzi": "顺利过渡", "en": "successful/smooth transition"}], "idioms": [{"hanzi": "承前启后", "pinyin": "chéng qián qǐ hòu", "meaning_en": "carry forward the past and open up the future; link past and future"}, {"hanzi": "继往开来", "pinyin": "jì wǎng kāi lái", "meaning_en": "build on past achievements and open up path forward"}, {"hanzi": "渐入佳境", "pinyin": "jiàn rù jiā jìng", "meaning_en": "gradually enter a pleasant phase; steadily improve"}, {"hanzi": "水到渠成", "pinyin": "shuǐ dào qú chéng", "meaning_en": "water flows and a channel is formed; succeed naturally when ripe"}], "character_decomposition": [{"character": "过", "pinyin": "guò", "meaning_en": "pass; cross; go beyond; mistake", "meaning_es": "pasar; cruzar; sobrepasar; error", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (walk/movement) + 寸 (inch / hand measure)", "sound_component": "呙 (guō, twisted mouth / phonetic origin)", "stroke_count": "6", "composition_type": "半包围结构", "etymology_and_mnemonic": "Footsteps 辶 pacing across a threshold or measured mark 寸; signifies crossing over, passing through, or exceeding boundaries.", "visual_mnemonic_story_en": "Footsteps (辶) measure out distance (寸) to cross over the boundary line (过).", "visual_mnemonic_story_es": "Pasos firmes (辶) miden el espacio (寸) para cruzar la frontera hacia el otro lado (过).", "tone_mnemonic_anchor": "51", "cangjie": "YDI", "traditional": "過"}, {"character": "渡", "pinyin": "dù", "meaning_en": "ferry; cross river; transit; tide over", "meaning_es": "cruzar río; vadear; transitar; superar", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (water/river) + 度 (measure/ferry pace)", "sound_component": "度 (dù, degree/measure / phonetic)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Water radical 氵 paired with 度 (measure/capacity); crossing across rivers by ferryboat, extended to traversing transitions.", "visual_mnemonic_story_en": "A ferry carries passengers across deep waters (氵) to the opposite shore (度), crossing over safely (渡).", "visual_mnemonic_story_es": "Una barcaza surca las aguas (氵) arribando a la orilla opuesta (度) para vadear el río (渡).", "tone_mnemonic_anchor": "51", "cangjie": "EITO", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "四季更迭时节，秋天是大自然从夏日的繁盛喧嚣向冬日的沉静萧瑟平稳过渡的金色桥梁。树叶在阵阵微风中缓缓由绿变黄，候鸟成群结队整齐南飞，一切生物都在从容不迫地做好迎接寒冬的过渡准备。", "pinyin": "Sìjì gèngdié shíjié, qiūtiān shì dànzìrán cóng xiàrì de fánshèng xuānxiāo xiàng dōngrì de chénjìng xiāosè píngwěn guòdù de jīnsè qiáoliáng. Shùyè zài zhènzhèn wēifēng zhōng huǎnhuǎn yóu lǜ biàn huáng, hòuniǎo chéngqún-jiéduì zhěngqí nánfēi, yíqiè shēngwù dōu zài cóngróng-bùpò de zuòhǎo yíngjiē hándōng de guòdù zhǔnbèi.", "en": "During seasonal change, autumn is nature's golden bridge transitioning smoothly from summer lushness to winter dormancy. Leaves turn yellow and migratory birds fly south, readying for winter.", "es": "En la rueda del año, el otoño es puente áureo que transita con sosiego de la fronda estival al letargo invernal. Hojas amarillas y aves rumbo al sur preparan a la biosfera para el invierno."}, {"id": "#2", "hanzi": "从传统化石能源向绿色清洁能源转型，是一个涉及千行百业的宏大系统工程。在这个历史过渡时期，必须统筹兼顾能源安全保供与节能减排目标，合理发展天然气等过渡清洁替代能源，确保国民经济平稳运行。", "pinyin": "Cóng chuántǒng huàshí néngyuán xiàng lǜsè qīngjié néngyuán zhuǎnxíng, shì yí ge shèjí qiānháng-bǎiyè de hóngdà xìtǒng gōngchéng. Zài zhè ge lìshǐ guòdù shíqī, bìxū tǒngchóu jiāngù néngyuán ānquán bǎogōng yǔ jiénéng jiǎnpái mùbiāo, hélǐ fāzhǎn tiānránqì děng guòdù qīngjié tìdài néngyuán, quèbǎo guómín jīngjì píngwěn yùnxíng.", "en": "Transitioning from fossil fuels to clean energy is a vast systemic undertaking. In this transitional era, balancing energy security with emissions reduction via bridge fuels like natural gas ensures economic stability.", "es": "Migrar del combustible fósil a la energía limpia es un cambio estructural. En este período de transición, compaginar el suministro con la descarbonización mediante energías puente asegura la estabilidad económica."}]}, {"meanings_summary": {"en": "shallow; light (color/sleep); superficial; simple", "es": "poco profundo; superficial; claro (color); ligero (sueño)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Water (氵) that is scanty and narrow (戋) is shallow and light (浅).", "composite_memory_hook_es": "El agua (氵) escasa y menguada (戋) denota lo somero y claro (浅).", "cultural_and_cognitive_roots": "Spatial depth paired with cognitive depth: paired universally as an antonym with 深 (deep); symbolizes introductory knowledge (深入浅出).", "tone_sandhi_and_pitch_modulation": "Dipping third tone: 'qiǎn' (214). Dip down low into pitch 2 and curve gently back up to 4."}, "semantic_boundary_contrasts": {"core_nuance": "浅 strictly denotes lack of depth (physical water, cognitive learning, sleep, or color saturation).", "contrasts": [{"id": "1", "compared_word": "浅 vs. 薄", "pinyin": "báo", "analysis": "薄 refers to physical planar thickness or insubstantiality ('薄纸', '感情淡薄'), while 浅 refers to water depth, sleep lightness, or colors."}, {"id": "2", "compared_word": "浅 vs. 淡", "pinyin": "dàn", "analysis": "淡 focuses on flavor (mild/bland), scent, or weak concentration of liquids ('淡水', '味道淡'), while 浅 describes visual color hue or water level."}, {"id": "3", "compared_word": "浅 vs. 短", "pinyin": "duǎn", "analysis": "短 refers to linear physical length or chronological duration ('时间短'), while 浅 refers to vertical depth."}]}, "traps_and_cognates": {"look_alikes": [{"character": "钱", "pinyin": "qián", "meaning_en": "money; coin", "distinction_note": "Has metal radical 钅 on left instead of water 氵 in 浅"}, {"character": "线", "pinyin": "xiàn", "meaning_en": "thread; line", "distinction_note": "Has silk radical 纟 on left of 戋"}, {"character": "残", "pinyin": "cán", "meaning_en": "cruel; disabled; remnant", "distinction_note": "Has bone radical 歹 on left of 戋"}, {"character": "践", "pinyin": "jiàn", "meaning_en": "trample; fulfill", "distinction_note": "Has foot radical 足 on left of 戋"}], "etymological_cognates": [{"character": "薄", "pinyin": "báo", "gloss_en": "thin; slight layer"}, {"character": "浮", "pinyin": "fú", "gloss_en": "float on surface"}, {"character": "轻", "pinyin": "qīng", "gloss_en": "light weight; gentle"}, {"character": "淡", "pinyin": "dàn", "gloss_en": "mild; insipid; pale"}]}, "id": "10", "hanzi": "浅", "pinyin": "qiǎn", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "shallow in depth from surface to bottom (opposite of deep/深)", "definition_es": "de poca profundidad o fondo; somero (opuesto a profundo/深)", "example_phrase": "水很浅 (the water is shallow)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "light, superficial, or brief (of color, sleep, knowledge, or emotional bonds)", "definition_es": "claro (de color), superficial (de saber) o ligero y fácil de interrumpir (de sueño)", "example_phrase": "浅睡眠 / 浅蓝色 (light sleep / light blue)"}], "example_sentences": [{"id": "#1", "hanzi": "清澈见底的溪水很浅，刚没过脚踝，成群的银色小鱼在光滑的鹅卵石间欢快游动。", "pinyin": "Qīngchè jiàndǐ de xīshuǐ hěn qiǎn, gāng mòguò jiǎohuái, chéngqún de yínsè xiǎoyú zài guānghuá de éluǎnshí jiān huānkuài yóudòng.", "en": "The crystal-clear stream water is very shallow, barely covering ankles, as schools of silver minnows dart among smooth pebbles.", "es": "El arroyo cristalino es tan somero que apenas cubre los tobillos, con pececillos plateados nadando alegres entre cantos rodados."}, {"id": "#2", "hanzi": "在半夜处于浅睡眠阶段时，哪怕是远处传来极其微弱的关门声也容易让人警醒过来。", "pinyin": "Zài bànyè chǔyú qiǎn shuìmián jiēduàn shí, nǎpà shì yuǎnchù chuánlái jíqí wēiruò de guānmén shēng yě róngyì ràng rén jǐngxǐng guòlai.", "en": "When in the light sleep stage in the middle of the night, even a faint distant door-closing sound easily jolts one awake.", "es": "En la fase de sueño ligero a medianoche, el más leve chasquido de una puerta lejana despierta de inmediato al durmiente."}], "collocations": [{"hanzi": "浅睡眠", "en": "light sleep"}, {"hanzi": "浅色", "en": "light color"}, {"hanzi": "浅蓝色", "en": "light blue"}, {"hanzi": "由浅入深", "en": "from shallow to deep; step by step"}, {"hanzi": "水浅", "en": "shallow water"}, {"hanzi": "学识浅薄", "en": "shallow learning / superficial knowledge"}], "idioms": [{"hanzi": "浅尝辄止", "pinyin": "qiǎn cháng zhé zhǐ", "meaning_en": "stop after tasting a little; skim the surface without deep study"}, {"hanzi": "深浅莫测", "pinyin": "shēn qiǎn mò cè", "meaning_en": "depth unpredictable; unfathomable and hard to gauge"}, {"hanzi": "深入浅出", "pinyin": "shēn rù qiǎn chū", "meaning_en": "explain profound truths in simple, accessible language"}, {"hanzi": "浅见寡闻", "pinyin": "qiǎn jiàn guǎ wén", "meaning_en": "have superficial views and limited experience"}], "character_decomposition": [{"character": "浅", "pinyin": "qiǎn", "meaning_en": "shallow; light; superficial", "meaning_es": "poco profundo; claro; superficial", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (water flow) + 戋 (small / narrow / shallow)", "sound_component": "戋 (jiān, small / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Water radical 氵 combined with 戋 (two small halberds / petty); little depth of water, meaning shallow or light.", "visual_mnemonic_story_en": "Water drops (氵) pool only in tiny, narrow amounts (戋), revealing a shallow stream (浅).", "visual_mnemonic_story_es": "Un hilillo de agua (氵) apenas llena un cuenco menguado (戋) formando un charco somero (浅).", "tone_mnemonic_anchor": "214", "cangjie": "EII", "traditional": "淺"}], "extended_reading_passages": [{"id": "#1", "hanzi": "初学者研读晦涩深奥的古代哲学经典，最忌讳浅尝辄止与浮躁求快。唯有循序渐进、由浅入深，耐下心来一字一句细细推敲字里行间的微言大义，方能真正领会圣贤先哲博大精深的治世智慧与处世哲学。", "pinyin": "Chūxuézhě yándú huìsè shēn'ào de gǔdài zhéxué jīngdiǎn, zuì jìhuì qiǎncháng-zhézhǐ yǔ fúzào qiúkuài. Wéiyǒu xúnxù-jiànjìn, yóuqiǎn-rùshēn, nàixià xīnlái yízì-yíjù xìxì tuīqiāo zìlǐ-hángjiān de wēiyán-dàyì, fāngnéng zhēnzhèng lǐnghuì shèngxián-xiānzhé bódà-jīngshēn de zhìshì zhìhuì yǔ chǔshì zhéxué.", "en": "When novices study ancient philosophy, superficial skimming and impatient haste are worst. Only progressing step by step from shallow to deep and pondering sentences carefully can one grasp profound wisdom.", "es": "Al abordar la filosofía clásica, el peor vicio es el desdén superficial. Solo avanzando con sosiego de lo elemental a lo hondo y saboreando cada renglón se asimila la magna sabiduría de los sabios."}, {"id": "#2", "hanzi": "盛夏时节，年轻女孩换上一袭优雅的浅绿色亚麻连衣裙，微风吹拂裙摆如荷叶摇曳，给人一种清爽宜人的清凉之感。浅色系服饰不仅在视觉上令人赏心悦目，更能在炎炎夏日有效反射刺目的阳光热量。", "pinyin": "Shèngxià shíjié, niánqīng nǚhái huànshàng yì xí yōuyǎ de qiǎnlǜsè yàmá liányīqún, wēifēng chuīfú qúnbǎi rú héyè yáoyè, jǐrén yì zhǒng qīngshuǎng yírén de qīngliángzhīgǎn. Qiǎnsèxì fúshì bùjǐn zài shìjué shàng lìngrén shǎnxīn-yuèmù, gèng néng zài yányán xiàrì yǒuxiào fǎnshè cìmù de yángguāng rèliàng.", "en": "In midsummer, a girl wears a light green linen dress, swaying like lotus leaves in the breeze with refreshing coolness. Light-colored clothing pleases the eye and reflects scorching sunlight heat effectively.", "es": "En canícula, un vestido de lino verde claro ondea como hoja de loto brindando una grata frescura. La gama de tonos claros deleita la vista y refleja el calor del sol abrasador con eficacia."}]}, {"meanings_summary": {"en": "modern times; the contemporary era; modern; contemporary", "es": "época moderna; era contemporánea; moderno; actual"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The era (代) manifesting in the living present (现) is the modern era (现代).", "composite_memory_hook_es": "La época o relevo (代) que se manifiesta en el presente vivo (现) es la era moderna (现代).", "cultural_and_cognitive_roots": "Historiographical era triad: 古代 (ancient times), 近代 (modern era from late Qing/Opium War to May Fourth), 现代 (contemporary era).", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'xiàn dài' (51-51). Descend sharply on 'xiàn', then land with a firm snap on 'dài'."}, "semantic_boundary_contrasts": {"core_nuance": "现代 denotes the present historical era (spanning roughly from the 20th century to the present day).", "contrasts": [{"id": "1", "compared_word": "现代 vs. 当代", "pinyin": "dāngdài", "analysis": "当代 specifically denotes the immediate current living generation (post-1949 or current decades), while 现代 broadly spans the 20th century forward."}, {"id": "2", "compared_word": "现代 vs. 近代", "pinyin": "jìndài", "analysis": "近代 in Chinese historiography designates the era from the 1840 Opium War to 1919 May Fourth Movement, strictly distinct from 现代."}, {"id": "3", "compared_word": "现代 vs. 目前", "pinyin": "mùqián", "analysis": "目前 is a short-term temporal adverb meaning 'at present / currently' ('目前没有问题'), whereas 现代 is macroscopic historical time."}]}, "traps_and_cognates": {"look_alikes": [{"character": "规", "pinyin": "guī", "meaning_en": "rule; compass", "distinction_note": "Has 夫 on left of 见 instead of jade 王 in 现"}, {"character": "视", "pinyin": "shì", "meaning_en": "look; inspect", "distinction_note": "Has altar 礻 on left of 见"}, {"character": "伐", "pinyin": "fá", "meaning_en": "cut down; attack", "distinction_note": "Has dagger-axe 戈 on right of 亻 instead of 弋 in 代"}, {"character": "化", "pinyin": "huà", "meaning_en": "transform", "distinction_note": "Has 匕 on right of 亻"}], "etymological_cognates": [{"character": "今", "pinyin": "jīn", "gloss_en": "present time; now"}, {"character": "世", "pinyin": "shì", "gloss_en": "generation of thirty years; world"}, {"character": "纪", "pinyin": "jì", "gloss_en": "silk thread era; century"}, {"character": "新", "pinyin": "xīn", "gloss_en": "new; fresh timber"}]}, "id": "11", "hanzi": "现代", "pinyin": "xiàn dài", "level": "HSK 5", "part_of_speech": "Noun / Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the historical period of current or recent times", "definition_es": "período histórico actual o reciente; la época contemporánea", "example_phrase": "现代社会 (modern society)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "belonging to or characteristic of present or recent times; up-to-date", "definition_es": "perteneciente o relativo a la época presente; avanzado y actual", "example_phrase": "现代化的设施 (modernized facilities)"}], "example_sentences": [{"id": "#1", "hanzi": "高速发展的高新科技正在以惊人的速度深刻重塑着现代人们的日常生活方式。", "pinyin": "Gāosù fāzhǎn de gāoxīnkējì zhèngzài yǐ jīngrén de sùdù shēnkè chóngsù zhe xiàndài rénmen de rìcháng shēnghuó fāngshì.", "en": "Rapidly advancing high technology is deeply reshaping the everyday lifestyles of modern people at an astonishing pace.", "es": "El veloz desarrollo de la alta tecnología está remodelando profundamente y a ritmo vertiginoso el modo de vida de las personas de hoy."}, {"id": "#2", "hanzi": "这座新建的国际机场航站楼设计前卫，配备了世界顶尖水准的现代化智能值机系统。", "pinyin": "Zhè zuò xīnjiàn de guójì jīchǎng hángzhànlóu shèjì qiánwèi, pèibèi le shìjiè dǐngjiān shuǐzhǔn de xiàndàihuà zhìnéng zhíjī xìtǒng.", "en": "The newly built international airport terminal boasts avant-garde design and is equipped with world-class modernized smart check-in systems.", "es": "La nueva terminal del aeropuerto internacional luce un diseño vanguardista y cuenta con sistemas de facturación inteligentes de última generación."}], "collocations": [{"hanzi": "现代社会", "en": "modern society"}, {"hanzi": "现代化", "en": "modernization; modernize"}, {"hanzi": "现代科学", "en": "modern science"}, {"hanzi": "现代生活", "en": "modern life"}, {"hanzi": "现代艺术", "en": "modern/contemporary art"}, {"hanzi": "现代汉语", "en": "Modern Chinese (Putonghua)"}], "idioms": [{"hanzi": "与时俱进", "pinyin": "yǔ shí jù jìn", "meaning_en": "advance with the times; keep abreast of developments"}, {"hanzi": "日新月异", "pinyin": "rì xīn yuè yì", "meaning_en": "change and progress with each passing day"}, {"hanzi": "古为今用", "pinyin": "gǔ wéi jīn yòng", "meaning_en": "make the ancient serve the present"}, {"hanzi": "革故鼎新", "pinyin": "gé gù dǐng xīn", "meaning_en": "cast off the old and embrace the new"}], "character_decomposition": [{"character": "现", "pinyin": "xiàn", "meaning_en": "appear; present; current; now", "meaning_es": "aparecer; presente; actual; ahora", "radical": "王", "radical_meaning_en": "jade", "meaning_component": "王 (fine jade emerging) + 见 (observing eye seeing clearly)", "sound_component": "见 (jiàn / phonetic origin)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Carving raw jade stone 王 until its inner luster becomes visible to the eye 见; denotes appearing, manifesting, or the present moment.", "visual_mnemonic_story_en": "A lapidary polishes jade (王) until its brilliant luster appears (现) before our eyes (见).", "visual_mnemonic_story_es": "Un artesano pule el jade (王) hasta que su brillo resplandece patente (现) a la vista (见).", "tone_mnemonic_anchor": "51", "cangjie": "MGBU", "traditional": "現"}, {"character": "代", "pinyin": "dài", "meaning_en": "generation; era; substitute; replace", "meaning_es": "generación; era; época; sustituir", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person) + 弋 (stake marking boundary/shift)", "sound_component": "弋 (yì, stake / phonetic)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 standing guard at a post marked by a stake 弋 until replaced by the next sentinel; represents generations, eras, and substitution.", "visual_mnemonic_story_en": "A guard (亻) takes over the post marked by a stake (弋), handing duties down from generation to generation (代).", "visual_mnemonic_story_es": "Un centinela (亻) releva la guardia junto a la estaca (弋) transmitiendo el relevo generacional (代).", "tone_mnemonic_anchor": "51", "cangjie": "OIP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "步入现代社会，都市生活节奏日益加快，琳琅满目的智能手机与移动网络极大地便利了人们的衣食住行。然而伴随信息爆炸与全天候连接，现代人也面临着前所未有的心理压力、数字焦虑与睡眠剥夺挑战。", "pinyin": "Bùrù xiàndài shèhuì, dūshì shēnghuó jiézòu rìyì jiākuài, línláng-mǎnmù de zhìnéng shǒujī yǔ yídòng wǎngluò jídà de biànlì le rénmen de yī-shí-zhù-xíng. Rán'ér bànsuí xìnxī bàozhà yǔ quántiānhòu liánjiē, xiàndàirén yě miànlín zhe qiánsuǒwèijiàn de xīnlǐ yālì, shùzì jiāolǜ yǔ shuìmián bōduó tiǎozhàn.", "en": "Entering modern society, urban tempos accelerate as smartphones and mobile networks streamline life. Yet alongside information explosions and perpetual connectivity, modern people face unprecedented mental stress and sleep deprivation.", "es": "En la sociedad moderna el ritmo urbano se acelera con móviles y redes telemáticas. Empero, la hiperconexión acarrea tensiones inéditas, ansiedad digital y privación del descanso reparador."}, {"id": "#2", "hanzi": "中国式现代化既有各国现代化的共同特征，更有基于自己国情的鲜明中国特色。它是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，为人类探索更好社会制度贡献了中国智慧。", "pinyin": "Zhōngguóshì xiàndàihuà jì yǒu gèguó xiàndàihuà de gòngtóng tèzhēng, gèng yǒu jīyú zìjǐ guóqíng de xiānmíng Zhōngguó tèsè. Tā shì rénkǒu guīmó jùdà de xiàndàihuà, shì quántǐ rénmín gòngtóng fùyù de xiàndàihuà, shì wùzhì wénmíng hé jīngshén wénmíng xiāng xiétiáo de xiàndàihuà, wèi rénlèi tànsuǒ gèng hǎo shèhuì zhìdù gòngxiàn le Zhōngguó zhìhuì.", "en": "Chinese modernization shares universal traits while rooted in national conditions: massive population scale, common prosperity, and harmony between material and cultural progress, contributing wisdom to human institutions.", "es": "La modernización china combina rasgos universales y peculiaridades propias: escala demográfica ingente, prosperidad compartida y armonía material y espiritual, enriqueciendo la gobernanza global."}]}, {"meanings_summary": {"en": "to enjoy; to savor; enjoyment; treat; benefit", "es": "disfrutar; gozar de; deleitarse; disfrute; goce"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Feasting on temple delicacies (享) and receiving them gratefully with open hands (受) means to enjoy (享受).", "composite_memory_hook_es": "Participar del banquete grato (享) recibiéndolo con ambas manos (受) es disfrutar a fondo (享受).", "cultural_and_cognitive_roots": "Derived from classical sacrificial communion (享通: spiritual reception); shifted in modern vernacular to hedonistic or aesthetic pleasures.", "tone_sandhi_and_pitch_modulation": "Dipping third tone followed by falling fourth tone: 'xiǎng shòu' (214-51). Dip deeply on 'xiǎng', then drop down firmly on 'shòu'."}, "semantic_boundary_contrasts": {"core_nuance": "享受 emphasizes deep, comfortable sensory, psychological, or material gratification.", "contrasts": [{"id": "1", "compared_word": "享受 vs. 贪图", "pinyin": "tāntú", "analysis": "贪图 has a negative connotation of coveting comfort or illicit gain ('贪图安逸', '贪图小便宜'), while 享受 is neutral or positive."}, {"id": "2", "compared_word": "享受 vs. 忍受", "pinyin": "rěnshòu", "analysis": "忍受 means enduring pain or unpleasant hardship ('忍受痛苦'), the polar emotional opposite of pleasant 享受."}, {"id": "3", "compared_word": "享受 vs. 欣赏", "pinyin": "xīnshǎng", "analysis": "欣赏 emphasizes intellectual and aesthetic appraisal of art or talent ('欣赏画作', '欣赏才华'), while 享受 is holistic sensory delight."}]}, "traps_and_cognates": {"look_alikes": [{"character": "亨", "pinyin": "hēng", "meaning_en": "prosperous; smooth", "distinction_note": "Lacks the central horizontal stroke of 子 in 享"}, {"character": "孝", "pinyin": "xiào", "meaning_en": "filial piety", "distinction_note": "Has 老-top atop 子 instead of 亠 and 口"}, {"character": "爱", "pinyin": "ài", "meaning_en": "love", "distinction_note": "Has friend 友 at bottom instead of 又 in 受"}, {"character": "妥", "pinyin": "tuǒ", "meaning_en": "proper; settled", "distinction_note": "Has woman 女 at bottom instead of 又"}], "etymological_cognates": [{"character": "乐", "pinyin": "lè", "gloss_en": "joy; cheerful music"}, {"character": "悦", "pinyin": "yuè", "gloss_en": "pleased in heart"}, {"character": "欣", "pinyin": "xīn", "gloss_en": "joyous laughter"}, {"character": "怡", "pinyin": "yí", "gloss_en": "serene harmony of mind"}]}, "id": "12", "hanzi": "享受", "pinyin": "xiǎng shòu", "level": "HSK 5", "part_of_speech": "Verb / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to take pleasure in, savor, or benefit from pleasant conditions, treatment, or sensations", "definition_es": "gozar, deleitarse o beneficiarse de condiciones gratas, delicias o derechos", "example_phrase": "享受生活 (enjoy life)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "pleasure, gratification, or luxurious satisfaction derived from experience", "definition_es": "deleite, fruición, bienestar o placer derivado de una vivencia", "example_phrase": "是一种精神享受 (is a spiritual treat)"}], "example_sentences": [{"id": "#1", "hanzi": "周末的午后，他喜欢泡上一壶芬芳的乌龙茶，静静地享受阳光洒满窗台的惬意时光。", "pinyin": "Zhōumò de wǔhòu, tā xǐhuan pào shàng yì hú fēnfāng de wūlóngchá, jìngjìng de xiǎngshòu yángguāng sǎmǎn chuāngtái de qièyì shíguāng.", "en": "On weekend afternoons, he loves brewing a fragrant pot of Oolong tea, quietly savoring the cozy hours of sunlight bathing the windowsill.", "es": "Los fines de semana por la tarde le complace preparar una tetera de aromático té Oolong, disfrutando de la agradable luz sobre el alféizar."}, {"id": "#2", "hanzi": "聆听这位享誉世界的钢琴大师演奏古典协奏曲，对在场的所有乐迷而言无疑是一场无与伦比的艺术享受。", "pinyin": "Língtīng zhè wèi xiǎngyù-shìjiè de gāngqín dàshī yǎnzòu gǔdiǎn xiézòuqǔ, duì zàichǎng de suǒyǒu yuèmí éryán wúyí shì yì chǎng wúyǔlúnbǐ de yìshù xiǎngshòu.", "en": "Listening to the world-renowned pianist perform classical concertos was undoubtedly an incomparable artistic treat for all music lovers.", "es": "Escuchar al célebre virtuoso interpretar conciertos clásicos al piano constituyó un deleite estético incomparable para todos los melómanos."}], "collocations": [{"hanzi": "享受生活", "en": "enjoy life"}, {"hanzi": "物质享受", "en": "material comfort/enjoyment"}, {"hanzi": "精神享受", "en": "spiritual/aesthetic enjoyment"}, {"hanzi": "享受待遇", "en": "enjoy benefits / receive entitlements"}, {"hanzi": "享受美食", "en": "savor delicacies"}, {"hanzi": "尽情享受", "en": "enjoy to the fullest"}], "idioms": [{"hanzi": "乐在其中", "pinyin": "lè zài qí zhōng", "meaning_en": "find joy in it; derive great pleasure from an activity"}, {"hanzi": "怡然自得", "pinyin": "yí rán zì dé", "meaning_en": "contented and serene; peaceful self-satisfaction"}, {"hanzi": "养尊处优", "pinyin": "yǎng zūn chǔ yōu", "meaning_en": "live in luxury and comfort; coddled lifestyle"}, {"hanzi": "其乐无穷", "pinyin": "qí lè wú qióng", "meaning_en": "boundless joy and endless amusement"}], "character_decomposition": [{"character": "享", "pinyin": "xiǎng", "meaning_en": "enjoy; benefit; sacrificial banquet", "meaning_es": "disfrutar; gozar; banquete de ofrenda", "radical": "亠", "radical_meaning_en": "lid", "meaning_component": "高 (lofty ancestral temple roof) + 子 (offspring presenting feast)", "sound_component": "享 (xiǎng)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "An ancestral temple lid 亠 where offspring 子 present aromatic sacrificial banquets for spirits to partake; denotes enjoying feast and favor.", "visual_mnemonic_story_en": "Under a decorated roof (亠), filial children (子) present fine food to enjoy together (享).", "visual_mnemonic_story_es": "Bajo el alero del templo (亠), los vástagos (子) ofrecen un manjar exquisito para disfrutarlo (享).", "tone_mnemonic_anchor": "214", "cangjie": "YRND", "traditional": ""}, {"character": "受", "pinyin": "shòu", "meaning_en": "receive; accept; endure; suffer", "meaning_es": "recibir; aceptar; soportar; experimentar", "radical": "又", "radical_meaning_en": "hand", "meaning_component": "爪 (hand from above giving) + 又 (hand from below receiving)", "sound_component": "舟 (zhōu, boat / vessel in between)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A hand from above 爪 passing a vessel into an eager hand below 又; denotes receiving, accepting, and experiencing sensations.", "visual_mnemonic_story_en": "Two hands pass and receive (受) a generous gift vessel smoothly.", "visual_mnemonic_story_es": "Una mano superior entrega y otra inferior acoge (受) una copa con deleite.", "tone_mnemonic_anchor": "51", "cangjie": "BBME", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "忙碌的工作之余，我们要学会放慢脚步，用心去感知生活中的点滴美好。不必追求奢华的物质铺张，清晨的一缕暖阳、窗台的一抹花香、与家人围坐的一顿热饭，都是值得我们细细品味与感念的无上享受。", "pinyin": "Mánglù de gōngzuò zhīyú, wǒmen yào xuéhuì fàngmàn jiǎobù, yòngxīn qù gǎnzhī shēnghuó zhōng de diǎndī měihǎo. Búbì zhuīqiú shēhuá de wùzhì pūzhāng, qīngchén de yì lǚ nuǎnyáng, chuāngtái de yì mǒ huāxiāng, yǔ jiārén wéizuò de yí dùn rèfàn, dōu shì zhíde wǒmen xìxì pǐnwèi yǔ gǎnniàn de wúshàng xiǎngshòu.", "en": "Amid busy work, we should learn to slow our steps to perceive life's simple joys. Luxuries are unneeded; morning sun, floral scents, and a warm meal with family are supreme delights worthy of savoring.", "es": "Entre el ajetreo laboral conviene pausar el paso y saborear la belleza menuda. Sin ostentaciones superfluas, el sol matinal, el aroma de una flor y una cena en familia son un goce inestimable para el alma."}, {"id": "#2", "hanzi": "现代社会保障体系的建立与健全，让越来越多的劳动者在年老退休后能够切实享受到国家发展带来的民生红利。按时足额发放的养老金与普惠性医疗保障，为千万老年人安享幸福尊严的晚年生活提供了坚实后盾。", "pinyin": "Xiàndài shèhuì bǎozhàng tǐxì de jiànlì yǔ jiànquán, ràng yuèláiyuè duō de láodòngzhě zài niánlǎo tuìxiū hòu nénggòu qièshí xiǎngshòudào guójiā fāzhǎn dàilái de mínshēng hónglì. Ànshí zú'é fāfàng de yǎnglǎojīn yǔ pǔhuìxìng yīliáo bǎozhàng, wèi qiānwàn lǎoniánrén ānxiǎng xìngfú zūnyán de wǎnnián shēnghuó tígōng le jiānshí hòudùn.", "en": "The modern social safety net ensures retirees enjoy the fruits of national development. Timely pensions and universal healthcare provide firm backing for millions of seniors to enjoy dignified twilight years.", "es": "La red de protección social moderna permite a los jubilados gozar de las conquistas del progreso. Pensiones dignas y cobertura médica universal garantizan una vejez plácida y honrosa a millones de ancianos."}]}, {"meanings_summary": {"en": "use; purpose; practical application; function", "es": "uso; utilidad; aplicación práctica; finalidad"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The path or avenue (途) along which a tool is put to use (用) is its purpose or application (用途).", "composite_memory_hook_es": "El camino o vía (途) por donde se aplica un útil (用) define su destino y uso (用途).", "cultural_and_cognitive_roots": "Utilitarian philosophy (体用之道: essence and utility); 途 maps out the functional trajectory through which matter serves human needs.", "tone_sandhi_and_pitch_modulation": "Falling fourth tone followed by rising second tone: 'yòng tú' (51-35). Drop sharply on 'yòng', then climb smoothly on 'tú'."}, "semantic_boundary_contrasts": {"core_nuance": "用途 emphasizes the practical objective purpose or utilitarian domain an object is applied to.", "contrasts": [{"id": "1", "compared_word": "用途 vs. 功能", "pinyin": "gōngnéng", "analysis": "功能 refers to the inherent technical capability or feature of a device ('手机拍照功能'), while 用途 refers to what human purpose it serves in practice ('用途是防盗')."}, {"id": "2", "compared_word": "用途 vs. 作用", "pinyin": "zuòyòng", "analysis": "作用 focuses on the effect, positive impact, or influence exerted on another object ('起到关键作用'), while 用途 is the intended application."}, {"id": "3", "compared_word": "用途 vs. 目的", "pinyin": "mùdì", "analysis": "目的 refers to a person's conscious goal or target ('达到目的'), whereas 用途 applies to inanimate tools, funds, or materials."}]}, "traps_and_cognates": {"look_alikes": [{"character": "甩", "pinyin": "shuǎi", "meaning_en": "fling; swing", "distinction_note": "Tail curves to right at bottom instead of central vertical stroke of 用"}, {"character": "角", "pinyin": "jiǎo", "meaning_en": "horn; angle", "distinction_note": "Has ⺈ on top of enclosure"}, {"character": "除", "pinyin": "chú", "meaning_en": "eliminate; divide", "distinction_note": "Has hill radical 阝 on left of 余 instead of 辶 in 途"}, {"character": "叙", "pinyin": "xù", "meaning_en": "narrate", "distinction_note": "Has 又 on right of 余"}], "etymological_cognates": [{"character": "功", "pinyin": "gōng", "gloss_en": "merit; functional work"}, {"character": "效", "pinyin": "xiào", "gloss_en": "efficacy; imitate result"}, {"character": "路", "pinyin": "lù", "gloss_en": "road; route of journey"}, {"character": "径", "pinyin": "jìng", "gloss_en": "narrow path; diameter"}]}, "id": "13", "hanzi": "用途", "pinyin": "yòng tú", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the practical application, utility, or specific purpose for which something is used", "definition_es": "aplicación práctica, destino o finalidad a que sirve un objeto o recurso", "example_phrase": "用途广泛 (has a wide range of uses)"}], "example_sentences": [{"id": "#1", "hanzi": "竹子在我国南方民间用途极其广泛，不仅可以制作坚韧耐用的家具，还能用来造纸和编织工艺品。", "pinyin": "Zhúzi zài wǒguó nánfāng mínjiān yòngtú jíqí guǎngfàn, bùjǐn kěyǐ zhìzuò jiānrèn nàiyòng de jiājù, hái néng yònglái zàozhǐ hé biānzhī gōngyìpǐn.", "en": "Bamboo has an exceptionally wide range of uses in southern Chinese folk life, crafting sturdy furniture as well as papermaking and weaving.", "es": "El bambú tiene incontables usos en el sur de China: no solo sirve para fabricar muebles robustos, sino también para papel y cestería."}, {"id": "#2", "hanzi": "财务制度明确严格规定，任何专项扶贫资金都必须专款专用，严禁挪作他用或改变资金用途。", "pinyin": "Cáiwù zhìdù míngquè yángé guīdìng, rènhé zhuānxiàng fúpín zījīn dōu bìxū zhuānkuǎn-zhuānyòng, yánjìn nuózuò tāyòng huò gǎibiàn zījīn yòngtú.", "en": "Financial regulations strictly stipulate that special poverty-alleviation funds must be ear-marked, barring diversion or altered purposes.", "es": "La normativa fiscal estipula que los fondos de ayuda deben destinarse a su fin exclusivo, prohibiendo desviar su uso o aplicación."}], "collocations": [{"hanzi": "用途广泛", "en": "widely used; versatile utility"}, {"hanzi": "实际用途", "en": "practical use/purpose"}, {"hanzi": "资金用途", "en": "allocation / use of funds"}, {"hanzi": "军事用途", "en": "military applications"}, {"hanzi": "改变用途", "en": "change the purpose/use"}, {"hanzi": "说明用途", "en": "explain the purpose"}], "idioms": [{"hanzi": "大材小用", "pinyin": "dà cái xiǎo yòng", "meaning_en": "put fine timber to petty use; waste great talents on menial jobs"}, {"hanzi": "物尽其用", "pinyin": "wù jìn qí yòng", "meaning_en": "make the best and fullest use of all resources"}, {"hanzi": "学以致用", "pinyin": "xué yǐ zhì yòng", "meaning_en": "study in order to apply in practice"}, {"hanzi": "别有用意", "pinyin": "bié yǒu yòng yì", "meaning_en": "have ulterior motives; have special hidden purpose"}], "character_decomposition": [{"character": "用", "pinyin": "yòng", "meaning_en": "use; employ; apply; utility", "meaning_es": "usar; emplear; utilizar; utilidad", "radical": "用", "radical_meaning_en": "use", "meaning_component": "卜 (divination oracle bone) + 中 (centering target hit)", "sound_component": "用 (yòng)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Oracle bone pictograph of a bronze tripod vessel or divination bone hitting the target 中; signifies effectiveness, application, and using tools.", "visual_mnemonic_story_en": "A wooden tool is grabbed firmly by its frame to use (用) it for daily tasks.", "visual_mnemonic_story_es": "Un útil resistente se empuña por el bastidor para usarlo (用) en la labor cotidiana.", "tone_mnemonic_anchor": "51", "cangjie": "BQ", "traditional": ""}, {"character": "途", "pinyin": "tú", "meaning_en": "way; route; road; path", "meaning_es": "camino; ruta; vía; sendero", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (walk/movement) + 余 (thatched hut shelter along path)", "sound_component": "余 (yú, surplus / phonetic)", "stroke_count": "10", "composition_type": "半包围结构", "etymology_and_mnemonic": "Footsteps 辶 traveling along a highway lined with post huts 余; denotes routes, paths, destinations, or avenues of development.", "visual_mnemonic_story_en": "Footsteps (辶) follow a well-trodden route past roadside huts (余), marking the path (途).", "visual_mnemonic_story_es": "Pasos firmes (辶) transitan la calzada junto a ventas camineras (余) siguiendo la ruta (途).", "tone_mnemonic_anchor": "35", "cangjie": "YOMD", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "石墨烯作为一种颠覆性的新型纳米碳素材料，凭借其超轻薄、超强韧性与卓越的导电导热性能，拥有极其广泛的工业用途。无论是应用于下一代超快充电电池，还是航空航天防热涂层，都展现出巨大的应用前景。", "pinyin": "Shímòxī zuòwéi yì zhǒng diānfùxìng de xīnxíng nàmǐ tànsù cáiliào, píngjiè qí chāoqīngbáo, chāoqiáng rènxìng yǔ zhuóyuè de dǎodiàn dǎorè xìngnéng, yǒngyǒu jíqí guǎngfàn de gōngyè yòngtú. Wúlùn shì yìngyòng yú xià yí dài chāokuài chōngdiàn diànchí, háishì hángkōng-hángtiān fángrè túcéng, dōu zhǎnxiàn chū jùdà de yìngyòng qiánjǐng.", "en": "As a disruptive nanomaterial, graphene possesses wide industrial uses due to ultra-thinness, strength, and conductivity. From fast-charging batteries to aerospace coatings, it shows immense application prospects.", "es": "Como nanomaterial disruptivo, el grafeno ofrece incontables aplicaciones por su ligereza, dureza y conductividad. Desde baterías ultrarrápidas hasta revestimientos aeroespaciales, promete una revolución técnica."}, {"id": "#2", "hanzi": "科研人员在野外考察时发现了一种具有特殊荧光特性的深海植物。经过实验室深入分析，专家们不仅证实了其作为生物传感器的新奇用途，更为开发无毒无害的新型医学造影试剂开辟了一条富有前景的创新技术路径。", "pinyin": "Kēyán rényuán zài yěwài kǎochá shí fāxiàn le yì zhǒng jùyǒu tèshū yíngguāng tèxìng de shēnhǎi zhíwù. Jīngguò shíyànshì shēnrù fēnxī, zhuānjiāmen bùjǐn zhèngshí le qí zuòwéi shēngwù chuángǎnqì de xīnqí yòngtú, gèng wèi kāifā wúdú-wúhài de xīnxíng yīxué zàoyǐng shìjì kāipì le yì tiáo fùyǒu qiánjǐng de chuàngxīn jìshù lùjìng.", "en": "Researchers on field surveys discovered a deep-sea plant with fluorescent properties. Laboratory analysis confirmed its novel use as a biosensor, opening paths to develop non-toxic medical imaging agents.", "es": "Exploradores hallaron una planta abisal de fluorescencia singular. Análisis de laboratorio demostraron su insólito uso como biosensor, abriendo una prometedora vía para agentes de contraste médico inocuos."}]}, {"meanings_summary": {"en": "experiment; scientific test; to experiment; to test", "es": "experimento; ensayo científico; experimentar; probar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Using solid tangible physical facts (实) to verify hypotheses (验) defines a laboratory experiment (实验).", "composite_memory_hook_es": "Usar hechos tangibles y sólidos (实) para verificar principios (验) define el experimento científico (实验).", "cultural_and_cognitive_roots": "Scientific epistemology (实事求是); imported modernly as the standard translation for empirical experimental science (empiricism).", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'shí yàn' (35-51). Rise smoothly on 'shí', then drop down sharply and decisively on 'yàn'."}, "semantic_boundary_contrasts": {"core_nuance": "实验 highlights controlled laboratory testing to uncover natural laws or verify scientific hypotheses.", "contrasts": [{"id": "1", "compared_word": "实验 vs. 试验", "pinyin": "shìyàn", "analysis": "实验 emphasizes rigorous laboratory verification of scientific natural laws ('物理实验'), while 试验 refers to practical field trials of prototypes or seed crops ('田间试验')."}, {"id": "2", "compared_word": "实验 vs. 实践", "pinyin": "shíjiàn", "analysis": "实践 denotes broad philosophical human social activity and real-world implementation, while 实验 is a specialized scientific method."}, {"id": "3", "compared_word": "实验 vs. 化验", "pinyin": "huàyàn", "analysis": "化验 specifically denotes laboratory chemical analysis of blood, urine, or soil samples ('抽血化验'), a subset of scientific tests."}]}, "traps_and_cognates": {"look_alikes": [{"character": "买", "pinyin": "mǎi", "meaning_en": "buy; purchase", "distinction_note": "Has 头 underneath 乛 instead of 宀 in 实"}, {"character": "卖", "pinyin": "mài", "meaning_en": "sell", "distinction_note": "Has 十 on top of 头"}, {"character": "脸", "pinyin": "liǎn", "meaning_en": "face", "distinction_note": "Has flesh radical 月 on left of 佥 instead of horse 马 in 验"}, {"character": "险", "pinyin": "xiǎn", "meaning_en": "danger", "distinction_note": "Has hill radical 阝 on left"}], "etymological_cognates": [{"character": "测", "pinyin": "cè", "gloss_en": "measure water depth; gauge"}, {"character": "试", "pinyin": "shì", "gloss_en": "test against model template"}, {"character": "证", "pinyin": "zhèng", "gloss_en": "prove with words; testify"}, {"character": "查", "pinyin": "chá", "gloss_en": "inspect trees; investigate"}]}, "id": "14", "hanzi": "实验", "pinyin": "shí yàn", "level": "HSK 5", "part_of_speech": "Noun / Verb", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a controlled scientific test or trial conducted in a laboratory to prove hypotheses or uncover natural laws", "definition_es": "operación científica controlada realizada en laboratorio para comprobar hipótesis o descubrir leyes", "example_phrase": "物理实验 (physics experiment)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to conduct controlled experiments in order to test theories or explore phenomena", "definition_es": "realizar ensayos o pruebas sistemáticas para contrastar un principio", "example_phrase": "在实验室反复实验 (experiment repeatedly in lab)"}], "example_sentences": [{"id": "#1", "hanzi": "化学老师在通风橱前为全班同学演示了浓硫酸与铜片在加热条件下发生反应的对比实验。", "pinyin": "Huàxué lǎoshī zài tōngfēngchú qián wèi quánbān tóngxué yǎnshì le nóngliúsuān yǔ tóngpiàn zài jiārè tiáojiàn xià fāshēng fǎnyìng de duìbǐ shíyàn.", "en": "The chemistry teacher demonstrated a comparative experiment under the fume hood showing reactions between concentrated sulfuric acid and copper under heat.", "es": "El profesor de química realizó ante los alumnos una prueba comparativa en la campana extractora con ácido sulfúrico concentrado y cobre al calor."}, {"id": "#2", "hanzi": "科研攻关团队经过上万次失败的实验摸索，终于成功合成了具有超导性能的全新结晶化合物。", "pinyin": "Kēyán gōngguān tuánduì jīngguò shàngwàn cì shībài de shíyàn mōsuǒ, zhōngyú chénggōng héchéng le jùyǒu chāodǎo xìngnéng de quánxīn jiéjīng huàhéwù.", "en": "After exploring through tens of thousands of failed experiments, the research team finally synthesized a new crystalline compound with superconducting properties.", "es": "Tras tantear en decenas de miles de experimentos fallidos, el equipo de investigación sintetizó con éxito un compuesto superconductor inédito."}], "collocations": [{"hanzi": "实验室", "en": "laboratory / research lab"}, {"hanzi": "做实验", "en": "conduct/run an experiment"}, {"hanzi": "科学实验", "en": "scientific experiment"}, {"hanzi": "对比实验", "en": "comparative/control experiment"}, {"hanzi": "实验结果", "en": "experimental results"}, {"hanzi": "实验数据", "en": "experimental data"}], "idioms": [{"hanzi": "真凭实据", "pinyin": "zhēn píng shí jù", "meaning_en": "ironclad, irrefutable evidence and solid facts"}, {"hanzi": "按图索骥", "pinyin": "àn tú suǒ jì", "meaning_en": "seek a thoroughbred according to picture; follow instructions mechanically"}, {"hanzi": "实事求是", "pinyin": "shí shì qiú shì", "meaning_en": "seek truth from facts; be practical and realistic"}, {"hanzi": "身体力行", "pinyin": "shēn tǐ lì xíng", "meaning_en": "practice personally what one preaches"}], "character_decomposition": [{"character": "实", "pinyin": "shí", "meaning_en": "solid; real; true; fruit; honest", "meaning_es": "sólido; real; verdadero; fruto; lleno", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (house roof) + 头/贯 (strings of cowrie currency filling home)", "sound_component": "实 (shí)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A house 宀 fully packed with stringed cowrie riches 贯; signifies substance, reality, truth, and solid fulfillment.", "visual_mnemonic_story_en": "A house (宀) packed solid with real treasures embodies truth and reality (实).", "visual_mnemonic_story_es": "Una casa (宀) colmada de riquezas tangibles personifica lo sólido y veraz (实).", "tone_mnemonic_anchor": "35", "cangjie": "JND", "traditional": "實"}, {"character": "验", "pinyin": "yàn", "meaning_en": "examine; check; verify; test", "meaning_es": "examinar; comprobar; verificar; eficaz", "radical": "马", "radical_meaning_en": "horse", "meaning_component": "马 (horse inspected for pedigree) + 佥 (all together / assembled)", "sound_component": "佥 (qiān, all / phonetic carrier)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Horse radical 马 paired with 佥 (assembled traits); thoroughly inspecting an equine to verify health, age, and pedigree.", "visual_mnemonic_story_en": "A breeder examines a horse (马) thoroughly to verify (验) its authentic pedigree.", "visual_mnemonic_story_es": "Un perito examina al corcel (马) de pies a cabeza para verificar (验) su brío y salud.", "tone_mnemonic_anchor": "51", "cangjie": "NMSOI", "traditional": "驗"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在空间站微重力环境下，中国航天员顺利完成了多项具有国际前沿水准的空间生命科学实验。研究人员通过实时下传的高清实验数据，细致观测植物根系与哺乳动物骨细胞在太空微重力状态下的发育演化规律。", "pinyin": "Zài kōngjiānzhàn wēizhònglì huánjìng xià, Zhōngguó hángtiānyuán shùnlì wánchéng le duō xiàng jùyǒu guójì qiányán shuǐzhǔn de kōngjiān shēngmìng kēxué shíyàn. Yánjiū rényuán tōngguò shíshí xiàchuán de gāoqīng shíyàn shùjù, xìzhì guāncè zhíwù gēnxì yǔ shǔlèi dòngwù gǔxìbāo zài tàikōng wēizhònglì zhuàngtài xià de fāyù yǎnhuà guīlǜ.", "en": "In space station microgravity, Chinese astronauts completed frontier life science experiments. Researchers used real-time high-definition data to observe plant roots and bone cell development in space.", "es": "En microgravedad en la estación espacial, los astronautas chinos culminaron experimentos punteros de biología cósmica. Con datos en tiempo real observaron raíces y células óseas bajo ingravidez."}, {"id": "#2", "hanzi": "现代医学的每一次巨大进步，都深深植根于严谨科学的临床对照实验。从新型抗癌靶向药物的分阶段人体试验，到大数据双盲对照评估，唯有经过确凿真实的实验证据检验，创新疗法才能获准走向临床挽救生命。", "pinyin": "Xiàndài yīxué de měi yí cì jùdà jìnbù, dōu shēnsēn zhígēn yú yánjǐn kēxué de línchuáng duìbǐ shíyàn. Cóng xīnxíng kàng'ái bǎxiàng yàowù de fēnjiēduàn réntǐ shìyàn, dào dàshùjù shuāngmáng duìbǐ pínggū, wéiyǒu jīngguò quèzáo zhēnshí de shíyàn zhèngjù jiǎnyàn, chuàngxīn liáofǎ cáinéng huòzhǔn zǒuxiàng línchuáng wǎnjiù shēngmìng.", "en": "Every progress in modern medicine is rooted in rigorous controlled clinical experiments. From phased trials of targeted drugs to double-blind assessments, only verified therapies reach clinics to save lives.", "es": "Los avances de la medicina moderna descansan en rigurosos ensayos clínicos de control. Desde pruebas farmacológicas hasta análisis a doble ciego, solo la evidencia experimental fidedigna avala tratamientos que salvan vidas."}]}, {"meanings_summary": {"en": "bell; chime; ring; buzzer", "es": "campana; campanilla; timbre; cascabel"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A metal object (钅) that rings to command attention (令) is a bell (铃).", "composite_memory_hook_es": "Una pieza metálica (钅) que tañe dando la voz de orden (令) es el timbre o cascabel (铃).", "cultural_and_cognitive_roots": "Bronze bell culture; ancient carriages had chariot bells (銮铃) to announce imperial convoys, transforming into modern school bells and electronic ringtones.", "tone_sandhi_and_pitch_modulation": "Rising second tone: 'líng' (35). Sweep upward cleanly from pitch 3 to high pitch 5 like a crisp bell chime."}, "semantic_boundary_contrasts": {"core_nuance": "铃 designates small acoustic bells, chimes, or electronic buzzers, distinct from colossal temple bells.", "contrasts": [{"id": "1", "compared_word": "铃 vs. 钟", "pinyin": "zhōng", "analysis": "钟 refers to large hanging bronze bells or timepiece clocks, while 铃 refers to small handheld bells, door buzzers, or bicycle bells."}, {"id": "2", "compared_word": "铃 vs. 锣", "pinyin": "luó", "analysis": "锣 is a flat bronze gong struck with a mallet, producing a flat resonant clash rather than tinkling 铃."}, {"id": "3", "compared_word": "铃 vs. 哨", "pinyin": "shào", "analysis": "哨 is a blown whistle producing high-pitched acoustic air vibrations, not struck metal."}]}, "traps_and_cognates": {"look_alikes": [{"character": "领", "pinyin": "lǐng", "meaning_en": "collar; lead", "distinction_note": "Has page/head radical 页 on right of 令 instead of 钅 in 铃"}, {"character": "冷", "pinyin": "lěng", "meaning_en": "cold", "distinction_note": "Has ice radical 冫 on left of 令"}, {"character": "钟", "pinyin": "zhōng", "meaning_en": "clock; large bell", "distinction_note": "Has 中 on right of 钅 instead of 令"}, {"character": "钢", "pinyin": "gāng", "meaning_en": "steel", "distinction_note": "Has 冈 on right of 钅"}], "etymological_cognates": [{"character": "铎", "pinyin": "duó", "gloss_en": "large handbell with wooden clapper"}, {"character": "磬", "pinyin": "qìng", "gloss_en": "sonorous chime stone"}, {"character": "钲", "pinyin": "zhēng", "gloss_en": "army gong used to halt soldiers"}, {"character": "叮", "pinyin": "dīng", "gloss_en": "tinkling metallic sound"}]}, "id": "15", "hanzi": "铃", "pinyin": "líng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a hollow metallic acoustic device with a clapper that rings when struck, or an electrical buzzer", "definition_es": "dispositivo acústico metálico hueco con badajo que tintinea al agitarse, o timbre eléctrico", "example_phrase": "按门铃 (press the doorbell)"}], "example_sentences": [{"id": "#1", "hanzi": "清脆悦耳的下课铃声刚刚响起，安静的教学楼走廊里瞬间充满了欢声笑语。", "pinyin": "Qīngcuì yuè'ěr de xiàkè língshēng gānggāng xiǎngqǐ, ānjìng de jiàoxuélóu zǒuláng lǐ shùnjiān chōngmǎn le huānshēng-xiàoyǔ.", "en": "Just as the crisp, melodious end-of-class bell rang, quiet hallways erupted into cheers and laughter in an instant.", "es": "Apenas sonó el timbre alegre de fin de clase, los silenciosos pasillos se llenaron al instante de risas y algarabía."}, {"id": "#2", "hanzi": "小猫咪的脖子上系着一枚精致小巧的金色小铜铃，走起路来发出叮叮当当的声响。", "pinyin": "Xiǎomāomī de bózi shàng jì zhe yì méi jīngzhì xiǎoqiǎo de jīnsè xiǎotónglíng, zǒu qǐ lù lai fāchū dīngdīng-dāngdāng de shēngxiǎng.", "en": "The kitten had an exquisite golden brass bell tied to its neck, making tinkling sounds as it trotted along.", "es": "El gatito llevaba atado al cuello un primoroso cascabel de latón dorado que tintineaba con gracia a cada paso."}], "collocations": [{"hanzi": "门铃", "en": "doorbell"}, {"hanzi": "铃声", "en": "ringtone; bell chime"}, {"hanzi": "闹铃", "en": "alarm chime"}, {"hanzi": "车铃", "en": "bicycle bell"}, {"hanzi": "铜铃", "en": "bronze bell"}, {"hanzi": "摇铃", "en": "handbell / ring bell"}], "idioms": [{"hanzi": "掩耳盗铃", "pinyin": "yǎn ěr dào líng", "meaning_en": "cover one's ears while stealing a bell; deceive oneself"}, {"hanzi": "解铃系铃", "pinyin": "jiě líng xì líng", "meaning_en": "whoever tied the bell must untie it; solve what one caused"}, {"hanzi": "顺手牵羊", "pinyin": "shùn shǒu qiān yáng", "meaning_en": "lead away sheep in passing; steal opportunistically"}, {"hanzi": "铜铃大眼", "pinyin": "tóng líng dà yǎn", "meaning_en": "eyes as wide and round as bronze bells"}], "character_decomposition": [{"character": "铃", "pinyin": "líng", "meaning_en": "bell; chime; ring; small rattle", "meaning_es": "campana; timbre; cascabel; campanilla", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (cast bronze/brass metal) + 令 (order / command)", "sound_component": "令 (lìng, command / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Metal radical 钅 paired with 令 (issuing commands); small cast bronze bells rung by heralds to assemble people for public orders.", "visual_mnemonic_story_en": "A small bell of metal (钅) rings to issue authoritative commands (令) to listeners (铃).", "visual_mnemonic_story_es": "Una campanilla de metal (钅) tañe para promulgar bandos y órdenes (令) a la vecindad (铃).", "tone_mnemonic_anchor": "35", "cangjie": "COEI", "traditional": "鈴"}], "extended_reading_passages": [{"id": "#1", "hanzi": "漫步在风光旖旎的江南水乡古镇，微风吹拂屋檐，悬挂在古刹飞檐四角的铜质风铃随风摇曳，发出一阵阵空灵悠扬的叮当铃声。那纯净清脆的回响洗涤着旅人的浮躁尘心，令人仿佛置身于物我两忘的世外桃源。", "pinyin": "Mànbù zài fēngguāng-yǐnǐ de Jiāngnán shuǐxiāng gǔzhèn, wēifēng chuīfú wūyán, xuánguà zài gǔchà fēiyán sì jiǎo de tóngzhì fēnglíng suífēng yáoyè, fāchū yízhènzhèn kōnglíng yōuyáng de dīngdāng língshēng. Nà chúnjìng qīngcuì de huíxiǎng xǐdí zhe lǚrén de fúzào chénxīn, lìngrén fǎngfú zhìshēn yú wù-wǒ-liǎngwàng de shìwàitáoyuán.", "en": "Strolling through an ancient southern wetland town, breezes caress eaves where brass wind chimes sway, chiming melodiously. That crisp echo washes away travelers' restless thoughts, transporting minds into tranquil seclusion.", "es": "Paseando por una villa fluvial del sur, la brisa mece los carillones de bronce colgados de los aleros del templo, emitiendo un tintineo místico que sosiega el espíritu del caminante en un remanso de paz."}, {"id": "#2", "hanzi": "古代成语“掩耳盗铃”生动讽刺了自欺欺人的愚蠢行为。春秋时期有人偷盗大钟，因钟体太重难以搬运便妄图用锤子敲碎，又害怕发出响亮铃声被他人发觉，竟自作聪明地用棉花捂住自己的耳朵，最终落得人赃俱获的下场。", "pinyin": "Gǔdài chéngyǔ 'yǎn'ěr-dàolíng' shēngdòng fěngcì le zìqī-qīrén de yúchǔn xíngwéi. Chūnqiū shíqī yǒurén tōudào dàzhōng, yīn zhōngtǐ tài zhòng nányǐ bānyùn biàn wàngtú yòng chuízi qiāosuì, yòu hàipà fāchū xiǎngliàng língshēng bèi tārén fājué, jìng zìzuò-cōngmíng de yòng miánhuā wǔzhù zìjǐ de ěrduo, zuìzhōng luòdé rénzāng-jùhuò de xiàchǎng.", "en": "The idiom 'cover one's ears to steal a bell' mocks self-deceit. A thief broke a bell with a hammer, but fearing its ring, stuffed his own ears with cotton, getting caught red-handed in foolish delusion.", "es": "La locución 'taparse los oídos para robar el cascabel' censura el autoengaño necio. Un ladrón quiso quebrar una campana para llevarse el bronce; temiendo el tañido se tapó los oídos cayendo preso en flagrante ridículo."}]}, {"meanings_summary": {"en": "structural particle (that which / receiver of action); measure word for buildings; place", "es": "partícula estructural (lo que / aquello que); clasificador de edificios; lugar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An axe (斤) at the door (户) establishes a physical place, or tags 'that which' (suǒ, 所).", "composite_memory_hook_es": "El hacha (斤) ante la puerta (户) levanta un recinto y marca 'aquello que' (suǒ, 所).", "cultural_and_cognitive_roots": "Classical Chinese grammatical marker (所字结构): prefixing 所 to transitive verbs nominalizes action, creating literary relative clauses ('所学', '所作').", "tone_sandhi_and_pitch_modulation": "Dipping third tone: 'suǒ' (214). Dip down to pitch 2 then rise lightly to 4."}, "semantic_boundary_contrasts": {"core_nuance": "所 functions syntactically as a nominalizing verbal prefix ('所+V') or classifier for institutions.", "contrasts": [{"id": "1", "compared_word": "所 vs. 处", "pinyin": "chù", "analysis": "处 is primarily a noun designating a physical geographic spot or administrative bureau ('到处', '教务处'), while 所 has rich grammatical nominalizing particle roles."}, {"id": "2", "compared_word": "所 vs. 家", "pinyin": "jiā", "analysis": "家 is the classifier for commercial companies, restaurants, and shops ('一家公司'), while 所 counts schools and hospitals ('一所学校')."}, {"id": "3", "compared_word": "所 vs. 个", "pinyin": "gè", "analysis": "个 is a generic classifier, while 所 conveys institutional formality when counting establishments."}]}, "traps_and_cognates": {"look_alikes": [{"character": "斤", "pinyin": "jīn", "meaning_en": "half kilogram; axe", "distinction_note": "Single character lacking door radical 户 on left of 所"}, {"character": "斥", "pinyin": "chì", "meaning_en": "reproach; scold", "distinction_note": "Has extra dot at upper right of 斤"}, {"character": "房", "pinyin": "fáng", "meaning_en": "room; house", "distinction_note": "Has 方 underneath 户 instead of 斤 in 所"}, {"character": "启", "pinyin": "qǐ", "meaning_en": "open; start", "distinction_note": "Has 口 underneath 户"}], "etymological_cognates": [{"character": "处", "pinyin": "chù", "gloss_en": "place; location"}, {"character": "地", "pinyin": "dì", "gloss_en": "earth; ground territory"}, {"character": "方", "pinyin": "fāng", "gloss_en": "square; direction; place"}, {"character": "居", "pinyin": "jū", "gloss_en": "dwell; reside under roof"}]}, "id": "16", "hanzi": "所", "pinyin": "suǒ", "level": "HSK 5", "part_of_speech": "Particle / Measure Word / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Particle", "register": "Standard", "definition_en": "particle placed before a transitive verb to form a nominal phrase representing the object or receiver of the action", "definition_es": "partícula antepuesta al verbo que nominaliza la acción señalando al objeto paciente ('lo que')", "example_phrase": "所见所闻 / 他所说的 (what is seen and heard / what he said)"}, {"sense_number": "2", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "measure word used for houses, schools, hospitals, and institutional establishments", "definition_es": "clasificador numeral empleado para escuelas, hospitales, institutos o edificios", "example_phrase": "一所大学 / 一所医院 (a university / a hospital)"}], "example_sentences": [{"id": "#1", "hanzi": "正如古人所说，“读万卷书，行万里路”，唯有将理论求知与社会实践紧密结合，才能增长才干。", "pinyin": "Zhèngrú gǔrén suǒ shuō, 'dú wànjuǎn shū, xíng wànlǐ lù', wéiyǒu jiāng lǐlùn qiúzhī yǔ shèhuì shíjiàn jǐnmì jiéhé, cáinéng zēngzhǎng cáigàn.", "en": "Just as the ancients said, 'read ten thousand books and travel ten thousand miles'; only by linking theory with practice can ability flourish.", "es": "Tal como decían los antiguos: 'leer diez mil tomos y recorrer diez mil leguas'; solo aunando teoría y práctica crece el talento."}, {"id": "#2", "hanzi": "经过多年的持续建设，这所位于西北偏远山区的小学拥有了明亮宽敞的多媒体网络教室。", "pinyin": "Jīngguò duōnián de chíxù jiànshè, zhè suǒ wèiyú xīběi piānyuǎn shānqū de xiǎoxué yǒngyǒu le míngliàng kuānchǎng de duōméitǐ wǎngluò jiàoshì.", "en": "Through years of sustained construction, this primary school located in remote northwestern mountains gained bright, multimedia classrooms.", "es": "Tras años de mejoras sostenidas, esta escuela de la serranía noroccidental cuenta ya con aulas multimedia luminosas y conectadas."}], "collocations": [{"hanzi": "一所学校", "en": "a school"}, {"hanzi": "一所医院", "en": "a hospital"}, {"hanzi": "所见所闻", "en": "what one sees and hears"}, {"hanzi": "所谓", "en": "so-called; what is meant by"}, {"hanzi": "所有人", "en": "everyone; owner"}, {"hanzi": "无所畏惧", "en": "fearless; afraid of nothing"}], "idioms": [{"hanzi": "各得其所", "pinyin": "gè dé qí suǒ", "meaning_en": "each is in their proper place; everyone is well-accommodated"}, {"hanzi": "无所适从", "pinyin": "wú suǒ shì cóng", "meaning_en": "at a loss what to follow; not knowing which way to turn"}, {"hanzi": "无所作为", "pinyin": "wú suǒ zuò wéi", "meaning_en": "accomplish nothing; passive and ineffective"}, {"hanzi": "无所不能", "pinyin": "wú suǒ bù néng", "meaning_en": "omnipotent; capable of doing anything"}], "character_decomposition": [{"character": "所", "pinyin": "suǒ", "meaning_en": "place; that which; structural particle; classifier for houses", "meaning_es": "lugar; lo que; partícula estructural; clasificador de edificios", "radical": "户", "radical_meaning_en": "door", "meaning_component": "户 (single-leaf doorway / household) + 斤 (carpenter axe)", "sound_component": "斤 (jīn, axe / sound of chopping)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "A carpenter's axe 斤 hewing wood beside a doorway 户 to clear building timber; originally sound of chopping wood, generalized to a building site or place.", "visual_mnemonic_story_en": "An axe (斤) shapes building timber beside a wooden door (户) to build an establishment (所).", "visual_mnemonic_story_es": "Un hacha (斤) desbasta maderos junto a la puerta (户) para alzar un edificio (所).", "tone_mnemonic_anchor": "214", "cangjie": "HSHML", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代先哲老子在《道德经》中曾深刻指出，“知人者智，自知者明。胜人者有力，自胜者强。”先贤所阐发的辩证哲理历经数千年历史淘洗，依然在今天闪耀着穿越时空的智慧光芒，指引着人们修身克己。", "pinyin": "Zhōngguó gǔdài xiānzhé Lǎozǐ zài Dàodéjīng zhōng céng shēnkè zhǐchū, 'zhīrén zhě zhì, zìzhī zhě míng. Shèngrén zhě yǒulì, zìshèng zhě qiáng.' Xiānxián suǒ chǎnfā de biànzhèng zhélǐ lìjīng shùqiān nián lìshǐ táoxǐ, yīrán zài jīntiān shǎnyào zhe chuānyuè shíkōng de zhìhuì guāngmáng, zhǐyǐn zhe rénmen xiūshēn-kèjǐ.", "en": "In the Tao Te Ching, Laozi observed that knowing others is intelligence, while self-knowledge is true enlightenment. The dialectical wisdom expounded by sages shines timelessly across millennia, guiding self-cultivation.", "es": "Lao Tse afirmó en el Tao Te King que conocer a los demás es sabiduría, mas conocerse a sí mismo es iluminación. Aquello que dilucidaron los antiguos sabios alumbra la conciencia moral con fulgor eterno."}, {"id": "#2", "hanzi": "百年大计，教育为本。近十年来，国家财政性教育经费持续向农村中西部倾斜，新建改建了数以万计标准化乡村中小学校。在这每一所现代化的校园里，偏远山区的孩子们都能通过宽带互联网共享全国名校的优质名师网络课程。", "pinyin": "Bǎinián dàjì, jiàoyù wéiběn. Jìn shí nián lái, guójiā cáizhèngxìng jiàoyù jīngfèi chíxù xiàng nóngcūn qīngxié, xīnjiàn gǎijiàn le shùyǐwànjì biāozhǔnhuà xiāngcūn zhōng-xiǎoxué. Zài zhè měi yì suǒ xiàndàihuà de xiàoyuán lǐ, piānyuǎn shānqū de háizimen dōunéng tōngguò kuāndài hùliánwǎng gòngxiǎng quánguó míngxiào de yōuzhì míngshī wǎngluò kèchéng.", "en": "Education is foundational to a nation's destiny. Over the past decade, public funding built tens of thousands of rural schools. In each modernized school, rural children access courses from top teachers via internet.", "es": "La enseñanza es cimiento de la nación. La inversión pública ha levantado decenas de miles de escuelas rurales en el interior. En cada una de estas escuelas los escolares acceden a lecciones magistrales por red."}]}, {"meanings_summary": {"en": "state; condition; status; situation", "es": "estado; condición; situación; disposición"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Physical posture (状) combined with internal mental disposition (态) establishes a comprehensive state (状态).", "composite_memory_hook_es": "La postura exterior (状) combinada con la disposición interna (态) configura el estado (状态).", "cultural_and_cognitive_roots": "Physics, psychology, and cybernetics calque: 状 (visible morphological configuration) paired with 态 (internal phase/state of matter: 固态, 液态, 气态).", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'zhuàng tài' (51-51). Descend sharply on 'zhuàng', then strike down firmly on 'tài'."}, "semantic_boundary_contrasts": {"core_nuance": "状态 designates the immediate operational mode, health condition, or psychological state of a person, machine, or matter.", "contrasts": [{"id": "1", "compared_word": "状态 vs. 情况", "pinyin": "qíngkuàng", "analysis": "情况 refers to external situational facts, circumstances, and developments ('了解具体情况'), while 状态 refers to the internal condition or functioning mode of a subject ('身体状态')."}, {"id": "2", "compared_word": "状态 vs. 态度", "pinyin": "tàidù", "analysis": "态度 denotes subjective human attitude, stance, or behavioral disposition toward others ('工作态度认真'), while 状态 is objective condition."}, {"id": "3", "compared_word": "状态 vs. 形式", "pinyin": "xíngshì", "analysis": "形式 refers to external aesthetic structure, genre, or format ('表现形式'), whereas 状态 is operational condition."}]}, "traps_and_cognates": {"look_alikes": [{"character": "壮", "pinyin": "zhuàng", "meaning_en": "strong; robust", "distinction_note": "Has 士 on right instead of hound dog 犬 in 状"}, {"character": "伏", "pinyin": "fú", "meaning_en": "prostrate; bend down", "distinction_note": "Has person radical 亻 on left of 犬"}, {"character": "怂", "pinyin": "sǒng", "meaning_en": "timid; instigate", "distinction_note": "Has 从 atop 心 instead of 太 in 态"}, {"character": "思", "pinyin": "sī", "meaning_en": "think; ponder", "distinction_note": "Has field 田 atop 心"}], "etymological_cognates": [{"character": "形", "pinyin": "xíng", "gloss_en": "shape; physical form"}, {"character": "况", "pinyin": "kuàng", "gloss_en": "condition; compare water"}, {"character": "势", "pinyin": "shì", "gloss_en": "momentum; physical force"}, {"character": "相", "pinyin": "xiàng", "gloss_en": "appearance; posture"}]}, "id": "17", "hanzi": "状态", "pinyin": "zhuàng tài", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the current physical, mental, biological, or operational mode and condition of a person or system", "definition_es": "modo de estar físico, anímico, biológico u operativo en que se halla una persona, sistema o materia", "example_phrase": "处于良好状态 (be in good condition)"}], "example_sentences": [{"id": "#1", "hanzi": "大赛开始前，教练通过科学的心理疏导帮助运动员迅速调整到了最佳竞技状态。", "pinyin": "Dàsài kāishǐ qián, jiàoliàn tōngguò kēxué de xīnlǐ shūdǎo bāngzhù yùndòngyuán xùnsù tiáozhěng dào le zuìjiā jìngjì zhuàngtài.", "en": "Before the tournament began, the coach helped athletes adjust rapidly into peak competitive condition through psychological counseling.", "es": "Antes del certamen, el entrenador ayudó a los atletas a alcanzar su estado competitivo óptimo mediante asesoramiento psicológico."}, {"id": "#2", "hanzi": "经过长途连续飞行，飞机发动机各项监测参数均显示正常，整机处于完全适航状态。", "pinyin": "Jīngguò chángtú liánxù fēixíng, fēijī fādòngjī gèxiàng jiāncè cānshù jūn xiǎnshì zhèngcháng, zhěngjī chǔyú wánquán shìháng zhuàngtài.", "en": "After long-distance continuous flight, all aircraft engine monitoring parameters read normal, the plane remaining in airworthy condition.", "es": "Tras un vuelo prolongado sin escalas, los parámetros de las turbinas marcaron normalidad hallándose el aparato en perfecto estado de vuelo."}], "collocations": [{"hanzi": "心理状态", "en": "psychological state / mindset"}, {"hanzi": "精神状态", "en": "mental state; spiritual vigor"}, {"hanzi": "处于状态", "en": "in a state of"}, {"hanzi": "调整状态", "en": "adjust one's state/mindset"}, {"hanzi": "工作状态", "en": "working state / operational mode"}, {"hanzi": "最佳状态", "en": "peak condition / best state"}], "idioms": [{"hanzi": "渐入佳境", "pinyin": "jiàn rù jiā jìng", "meaning_en": "gradually enter a pleasant condition; steadily improve"}, {"hanzi": "浑然一体", "pinyin": "hún rán yì tǐ", "meaning_en": "integrated into an organic whole; seamless harmony"}, {"hanzi": "如入梦境", "pinyin": "rú rù mèng jìng", "meaning_en": "as if entering a dreamland; entranced state"}, {"hanzi": "安之若素", "pinyin": "ān zhī ruò sù", "meaning_en": "bear hardships with tranquil composure as if habitual"}], "character_decomposition": [{"character": "状", "pinyin": "zhuàng", "meaning_en": "form; shape; state; certificate; describe", "meaning_es": "forma; aspecto; estado; acta; describir", "radical": "犬", "radical_meaning_en": "dog", "meaning_component": "丬 (wooden bed split) + 犬 (hound dog form)", "sound_component": "状 (zhuàng)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A hound dog 犬 lying against a split wooden bed board 丬; picturing the posture, visible outline, or condition of creatures.", "visual_mnemonic_story_en": "A dog (犬) rests beside a bed plank (丬), showing its physical form and posture (状).", "visual_mnemonic_story_es": "Un lebrel (犬) reposa junto a un tablón de lecho (丬) mostrando su aspecto y postura (状).", "tone_mnemonic_anchor": "51", "cangjie": "LMID", "traditional": ""}, {"character": "态", "pinyin": "tài", "meaning_en": "manner; appearance; voice; posture; state", "meaning_es": "ademán; porte; actitud; postura; estado", "radical": "心", "radical_meaning_en": "heart / mind", "meaning_component": "太 (grand / excessive) + 心 (heart/mind posture)", "sound_component": "太 (tài, great / phonetic)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Grand appearance 太 guided by internal mental dispositions of the heart 心; denotes external demeanor, attitude, or physical phase.", "visual_mnemonic_story_en": "A grand demeanor (太) guided by feelings inside the heart (心) shapes posture (态).", "visual_mnemonic_story_es": "Un porte altivo (太) regido por los impulsos del corazón (心) define la actitud y estado (态).", "tone_mnemonic_anchor": "51", "cangjie": "KIP", "traditional": "態"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代高压职场环境中，保持良好的心理健康状态是战胜困难与实现自我突破的关键。当感到焦虑烦躁时，主动停下手中繁重的事务做深呼吸，适度散步放空大脑，有助于迅速摆脱精神内耗，重回专注高效的工作状态。", "pinyin": "Zài xiàndài gāoyā zhíchǎng huánjìng xià, bǎochí liánghǎo de xīnlǐ jiànkāng zhuàngtài shì zhànshèng kùnnán yǔ shíxiàn zìwǒ tūpò de guānjiàn. Dāng gǎndào jiāolǜ fánzào shí, zhǔdòng tíngxià shǒuzhōng fánzhòng de shìwù zuò shēnhūxī, shìdù sànbù fàngkōng dànǎo, yǒuzhùyú xùnsù bǎituō jīngshén nèihào, chónghuí zhuānzhù gāoxiào de gōngzuò zhuàngtài.", "en": "In high-pressure workplaces, maintaining good mental state is key to overcoming obstacles. When feeling anxious, pausing for deep breaths and a stroll clears the mind, shedding friction to regain productive focus.", "es": "En la vorágine laboral, guardar un estado anímico equilibrado es clave para superar escollos. Ante la zozobra, respirar hondo y pasear oxigena la mente, disipando el estrés para rendir con lucidez."}, {"id": "#2", "hanzi": "高铁列车在以每小时三百五十公里飞驰时，车体各部传感器实时采集受电弓、轴承与制动系统的运行状态数据。车载中央电脑利用智能算法对机车运行状态进行毫秒级高频诊断，确保列车始终处于绝对安全运行状态。", "pinyin": "Gāotiě lièchē zài yǐ měi xiǎoshí sānbǎi wǔshí gōnglǐ fēichí shí, chētǐ gèbù chuángǎnqì shíshí cǎijí shòudiàngōng, zhóuchéng yǔ zhìdòng xìtǒng de yùnxíng zhuàngtài shùjù. Chēzài zhōngyāng diànnǎo lìyòng zhìnéng suànfǎ duì jīchē yùnxíng zhuàngtài jìnxíng háomiǎojí gāopín zhěnduàn, quèbǎo lièchē shǐzhōng chǔyú juéduì ānquán yùnxíng zhuàngtài.", "en": "As bullet trains race at 350 km/h, sensors collect operational data on pantographs, bearings, and brakes. Computers diagnose running states at millisecond speeds, ensuring absolute safety throughout journeys.", "es": "A 350 km/h, sensores del tren bala monitorizan pantógrafos, cojinetes y frenos en tiempo real. Ordenadores a bordo diagnostican el estado del convoy al milisegundo garantizando un viaje enteramente seguro."}]}, {"meanings_summary": {"en": "clear-headed; sober; awake; to regain consciousness; to sober up", "es": "lúcido; sobrio; despierto; despejado; recobrar el conocimiento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Clear water (清) dispels wine fumes as dawn breaks (醒), making one clear-headed and awake (清醒).", "composite_memory_hook_es": "El agua cristalina (清) disipa los vapores del vino al romper el alba (醒), recobrando la lucidez (清醒).", "cultural_and_cognitive_roots": "Derived from classical Chinese drinking culture and philosophical mindfulness (屈原: 众人皆醉我独醒: all the world is drunk, I alone am sober).", "tone_sandhi_and_pitch_modulation": "Level high tone followed by dipping third tone: 'qīng xǐng' (55-214). Maintain steady high pitch 55 on 'qīng', then dip and rise on 'xǐng'."}, "semantic_boundary_contrasts": {"core_nuance": "清醒 emphasizes cognitive lucidity and rational wakefulness, free from intoxication, delirium, or illusion.", "contrasts": [{"id": "1", "compared_word": "清醒 vs. 醒来", "pinyin": "xǐnglái", "analysis": "醒来 focuses on the physical transitional action of opening eyes and leaving sleep ('从梦中醒来'), while 清醒 describes state of alertness or recovering from coma/drunkenness."}, {"id": "2", "compared_word": "清醒 vs. 明白", "pinyin": "míngbai", "analysis": "明白 denotes intellectual understanding of a concept or fact ('我明白了'), whereas 清醒 is the physiological and psychological state of alertness."}, {"id": "3", "compared_word": "清醒 vs. 镇静", "pinyin": "zhènjìng", "analysis": "镇静 emphasizes emotional calm and lack of agitation in panic ('保持镇静'), while 清醒 is intellectual lucidity."}]}, "traps_and_cognates": {"look_alikes": [{"character": "晴", "pinyin": "qíng", "meaning_en": "sunny; clear", "distinction_note": "Has sun radical 日 on left of 青 instead of water 氵 in 清"}, {"character": "请", "pinyin": "qǐng", "meaning_en": "please; invite", "distinction_note": "Has speech radical 讠 on left of 青"}, {"character": "醉", "pinyin": "zuì", "meaning_en": "drunk; intoxicated", "distinction_note": "Has 卒 on right of 酉 instead of 星 in 醒"}, {"character": "醋", "pinyin": "cù", "meaning_en": "vinegar", "distinction_note": "Has 昔 on right of 酉"}], "etymological_cognates": [{"character": "觉", "pinyin": "jué", "gloss_en": "awaken to sense; feel"}, {"character": "明", "pinyin": "míng", "gloss_en": "bright; lucid mind"}, {"character": "悟", "pinyin": "wù", "gloss_en": "apprehend truth; enlighten"}, {"character": "澈", "pinyin": "chè", "gloss_en": "limpid; penetrate through"}]}, "id": "18", "hanzi": "清醒", "pinyin": "qīng xǐng", "level": "HSK 5", "part_of_speech": "Adjective / Verb", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "clear-headed, sober, alert, and rationally aware (not drunk, asleep, or confused)", "definition_es": "despierto, despejado, sereno y con pleno uso de las facultades racionales", "example_phrase": "头脑清醒 (clear-headed)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to regain consciousness after fainting, coma, or intoxication", "definition_es": "volver en sí, despejarse o recobrar el sentido tras desmayo o embriaguez", "example_phrase": "病人已经清醒过来 (the patient has regained consciousness)"}], "example_sentences": [{"id": "#1", "hanzi": "面对突如其来的巨大利益诱惑与外界吹捧，保持清醒的头脑是做出明智判断的底线。", "pinyin": "Miànduì tūrúqílái de jùdà lìyì yòuhuò yǔ wàijiè chuīpěng, bǎochí qīngxǐng de tóunǎo shì zuòchū míngzhì pànduàn de dǐxiàn.", "en": "Confronted with sudden temptations of huge profit and outside flattery, keeping a clear head is the bottom line for making wise decisions.", "es": "Ante la tentación de pingües ganancias y halagos desmedidos, mantener la mente despejada es premisa ineludible para obrar con juicio."}, {"id": "#2", "hanzi": "在重症监护室医护人员连续两天的精心治疗下，陷入深度昏迷的伤者终于逐渐清醒了过来。", "pinyin": "Zài zhòngzhèng jiānhùshì yīhù rényuán liánxù liǎng tiān de jīngxīn zhìliáo xià, xiànrù shēndù hūnmí de shāngzhě zhōngyú zhújiàn qīngxǐng le guòlai.", "en": "Under two days of intensive care by ICU medical staff, the critically injured patient in a deep coma finally regained consciousness gradually.", "es": "Gracias a los minuciosos cuidados en la unidad de cuidados intensivos, el herido en coma profundo recobró paulatinamente el conocimiento."}], "collocations": [{"hanzi": "头脑清醒", "en": "clear-headed; sober-minded"}, {"hanzi": "清醒过来", "en": "regain consciousness / come round"}, {"hanzi": "保持清醒", "en": "stay alert / remain sober"}, {"hanzi": "十分清醒", "en": "fully awake / wide awake"}, {"hanzi": "清醒认识", "en": "sober understanding / clear realization"}, {"hanzi": "难以清醒", "en": "hard to sober up"}], "idioms": [{"hanzi": "大梦初醒", "pinyin": "dà mèng chū xǐng", "meaning_en": "as if waking from a long dream; sudden awakening to reality"}, {"hanzi": "神志清醒", "pinyin": "shén zhì qīng xǐng", "meaning_en": "fully conscious and alert; completely lucid"}, {"hanzi": "如梦初醒", "pinyin": "rú mèng chū xǐng", "meaning_en": "wake up as from a dream; suddenly see the light"}, {"hanzi": "从容不迫", "pinyin": "cóng róng bù pò", "meaning_en": "calm and unhurried; serene composure"}], "character_decomposition": [{"character": "清", "pinyin": "qīng", "meaning_en": "clear; pure; clean; quiet; settle", "meaning_es": "claro; puro; limpio; transparente; saldar", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (clear spring water) + 青 (lush green / pure)", "sound_component": "青 (qīng, green/pure / phonetic)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Water radical 氵 combined with 青 (lush pure green); clear, limpid water without sediment, extended to mental clarity.", "visual_mnemonic_story_en": "Water (氵) as pure and tranquil as spring greenery (青) reflects crystal clarity (清).", "visual_mnemonic_story_es": "El agua (氵) tan pura y diáfana como el verdor primaveral (青) destila transparencia (清).", "tone_mnemonic_anchor": "55", "cangjie": "EQMB", "traditional": ""}, {"character": "醒", "pinyin": "xǐng", "meaning_en": "wake up; sober up; awaken; realize", "meaning_es": "despertar; despejarse; volver en sí; despabilar", "radical": "酉", "radical_meaning_en": "wine / vessel", "meaning_component": "酉 (fermenting wine vessel) + 星 (bright stars in morning sky)", "sound_component": "星 (xīng, stars / phonetic origin)", "stroke_count": "16", "composition_type": "左右结构", "etymology_and_mnemonic": "Wine vessel 酉 dissipating intoxication as morning stars 星 shine; recovering sobriety and waking from slumber.", "visual_mnemonic_story_en": "Fumes from a wine jar (酉) clear away as bright morning stars (星) signal waking up (醒).", "visual_mnemonic_story_es": "Los vapores del jarro de vino (酉) se disipan cuando las estrellas matinales (星) despabilan al durmiente (醒).", "tone_mnemonic_anchor": "214", "cangjie": "MWAHM", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "古往今来，身处顺境高位时最难能可贵的便是保持内心的清醒与戒惧。战国楚国大诗人屈原曾慨叹“举世皆浊我独清，众人皆醉我独醒”。在名利喧嚣中守住本心，不为浮华所惑，方能行止有度、立身长远。", "pinyin": "Gǔwǎng-jīnlái, shēnchǔ shùnjìng gāowèi shí zuì nánnéng-kěguì de biànshì bǎochí nèixīn de qīngxǐng yǔ jièjù. Zhànguó Chǔguó dà shīrén Qū Yuán céng kǎitàn 'jǔshì jiē zhuó wǒ dú qīng, zhòngrén jiē zuì wǒ dú xǐng'. Zài mínglì xuānxiāo zhōng shǒuzhù běnxīn, bù wéi fúhuá suǒ huò, fāngnéng xíngzhǐ-yǒudù, lìshēn chángyuǎn.", "en": "Throughout history, staying lucid and vigilant in prosperity is rare. Poet Qu Yuan lamented, 'The whole world is turbid, I alone am pure; all are drunk, I alone am sober.' Staying grounded amidst fame leads to lasting integrity.", "es": "A lo largo de los siglos, guardar la lucidez y la prudencia en el éxito ha sido la más rara virtud. Como sentenció el poeta Qu Yuan: 'Ebrio está el mundo, solo yo velo lúcido'. Desoír los halagos vanos forja un carácter intachable."}, {"id": "#2", "hanzi": "早晨被刺耳闹钟惊醒的人，常常会经历长达十数分钟的“睡眠惯性”状态。此时大脑皮层尚未彻底恢复清醒，血液循环与思维反应相对迟钝，若立即下床剧烈运动极易头晕目眩，应静坐片刻温和苏醒。", "pinyin": "Zǎochen bèi cì'ěr nàozhōng jīngxǐng de rén, chángcháng huì jīnglì chángdá shíshù fēnzhōng de 'shuìmián guànxìng' zhuàngtài. Cǐshí dànǎo pícéng shàngwèi chèdǐ huīfù qīngxǐng, xuèyè xúnhuán yǔ sīwéi fǎnyìng xiāngduì chídùn, ruò lìjí xiàchuáng jùliè yùndòng jíyì tóuyūn-mùxuàn, yīng jìngzuò piànkè wēnhé sùxǐng.", "en": "Those jolted awake by loud alarms often endure minutes of sleep inertia. The cerebral cortex has not regained full lucidity, blood flow is sluggish; jumping out of bed causes dizziness, so resting gently is best.", "es": "Quien despierta sobresaltado por el despertador padece minutos de inercia del sueño. La corteza cerebral aún no está despejada y la mente reacciona lenta; levantarse de golpe causa mareos, siendo prudente reposar un momento."}]}, {"meanings_summary": {"en": "to breathe; to respire; respiration; breath", "es": "respirar; respiración; aliento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Blowing air out (呼) and drawing air in (吸) forms the natural rhythm of respiration (呼吸).", "composite_memory_hook_es": "Expulsar el aire (呼) y tomar aire hacia adentro (吸) constituye el ciclo de la respiración (呼吸).", "cultural_and_cognitive_roots": "Daoist inner cultivation (吐纳之术: spitting out turbid air and inhaling fresh qi); breathing forms the vital conduit linking cosmos and human physiology.", "tone_sandhi_and_pitch_modulation": "Double level high first tones: 'hū xī' (55-55). Hold level high pitch 55 smoothly across both syllables like calm, steady breathing."}, "semantic_boundary_contrasts": {"core_nuance": "呼吸 is the comprehensive biological term for the complete cycle of inhaling and exhaling.", "contrasts": [{"id": "1", "compared_word": "呼吸 vs. 喘气", "pinyin": "chuǎnqì", "analysis": "喘气 specifically describes rapid, labored gasping for breath after exhausting physical exercise, while 呼吸 is regular calm respiration."}, {"id": "2", "compared_word": "呼吸 vs. 叹气", "pinyin": "tànqì", "analysis": "叹气 refers to sighing out of sorrow, frustration, or relief ('唉声叹气'), not physiological gas exchange."}, {"id": "3", "compared_word": "呼吸 vs. 气息", "pinyin": "qìxī", "analysis": "气息 refers to the faint stream of air from the nostrils/mouth or emotional atmosphere ('春天的气息'), while 呼吸 is the bodily process."}]}, "traps_and_cognates": {"look_alikes": [{"character": "乎", "pinyin": "hū", "meaning_en": "modal particle", "distinction_note": "Lacks the mouth radical 口 of 呼"}, {"character": "呼", "pinyin": "hū", "meaning_en": "breathe out; call", "distinction_note": "Has mouth radical 口 on left"}, {"character": "及", "pinyin": "jí", "meaning_en": "reach; and", "distinction_note": "Lacks mouth radical 口 of 吸"}, {"character": "级", "pinyin": "jí", "meaning_en": "level; grade", "distinction_note": "Has silk radical 纟 on left of 及"}], "etymological_cognates": [{"character": "气", "pinyin": "qì", "gloss_en": "vapor; vital air/energy"}, {"character": "喘", "pinyin": "chuǎn", "gloss_en": "pant; gasp for breath"}, {"character": "吸", "pinyin": "xī", "gloss_en": "inhale into mouth"}, {"character": "吐", "pinyin": "tǔ", "gloss_en": "spit out; exhale"}]}, "id": "19", "hanzi": "呼吸", "pinyin": "hū xī", "level": "HSK 5", "part_of_speech": "Verb / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to inhale oxygen and exhale carbon dioxide through respiratory organs", "definition_es": "inhalar oxígeno y exhalar dióxido de carbono a través de los órganos respiratorios", "example_phrase": "深呼吸 (take a deep breath)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the physiological process or sound of breathing; respiration", "definition_es": "el proceso fisiológico o sonido del aire al respirar; respiración", "example_phrase": "呼吸急促 (rapid and hurried breathing)"}], "example_sentences": [{"id": "#1", "hanzi": "清晨漫步在松柏苍翠的山间小路上，深深地呼吸着富含负氧离子的清新空气，顿觉心旷神怡。", "pinyin": "Qīngchén mànbù zài sōngbǎi cāngcuì de shānjiān xiǎolù shàng, shēnshēn de hūxī zhe fùhán fùyǎnglízǐ de qīngxīn kōngqì, dùnjué xīnkuàng-shényí.", "en": "Strolling on pine-lined mountain paths in the morning, breathing deeply the fresh air rich in negative oxygen ions brings instant serenity.", "es": "Paseando al amanecer por un sendero entre pinos y respirando hondo el aire puro del bosque, el espíritu se serena y regocija."}, {"id": "#2", "hanzi": "医生仔细检查患者的胸腔起伏与脉搏跳动，发现其呼吸极其微弱，立刻组织团队展开紧急气管插管抢救。", "pinyin": "Yīshēng zǐxì jiǎnchá huànzhě de xiōngqiāng qǐfú yǔ màibó tiàodòng, fāxiàn qí hūxī jíqí wēiruò, lìkè zǔzhī tuánduì zhǎnkāi jǐnjí qìguǎn chāguǎn qiǎngjiù.", "en": "The doctor checked chest movements and pulse, finding the patient's breathing extremely faint, immediately organizing intubation rescue.", "es": "El médico comprobó el pulso y el tórax del paciente hallando su respiración sumamente débil, procediendo a una intubación traqueal de urgencia."}], "collocations": [{"hanzi": "深呼吸", "en": "deep breath; take a deep breath"}, {"hanzi": "呼吸困难", "en": "difficulty breathing; dyspnea"}, {"hanzi": "呼吸系统", "en": "respiratory system"}, {"hanzi": "屏住呼吸", "en": "hold one's breath"}, {"hanzi": "呼吸急促", "en": "rapid breathing; shortness of breath"}, {"hanzi": "人工呼吸", "en": "artificial respiration / CPR"}], "idioms": [{"hanzi": "同呼吸共命运", "pinyin": "tóng hū xī gòng mìng yùn", "meaning_en": "breathe the same air and share the same destiny; united in fate"}, {"hanzi": "屏气凝神", "pinyin": "bǐng qì níng shén", "meaning_en": "hold one's breath and concentrate with rapt attention"}, {"hanzi": "气喘吁吁", "pinyin": "qì chuǎn xū xū", "meaning_en": "panting and out of breath after exertion"}, {"hanzi": "苟延残喘", "pinyin": "gǒu yán cán chuǎn", "meaning_en": "barely manage to prolong lingering breath; scrape along"}], "character_decomposition": [{"character": "呼", "pinyin": "hū", "meaning_en": "call; shout; exhale; breathe out", "meaning_es": "llamar; gritar; exhalar; expirar", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (open mouth) + 乎 (sound of air sighing out)", "sound_component": "乎 (hū, sighing exhalation / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Open mouth 口 blowing air outward or sighing 乎; signifies exhalation, calling out, or shouting.", "visual_mnemonic_story_en": "An open mouth (口) exhales air smoothly outward into the wind (乎), breathing out (呼).", "visual_mnemonic_story_es": "Una boca abierta (口) exhala el aire hacia afuera en suave suspiro (乎), espirando (呼).", "tone_mnemonic_anchor": "55", "cangjie": "RHFD", "traditional": ""}, {"character": "吸", "pinyin": "xī", "meaning_en": "inhale; breathe in; absorb; suck", "meaning_es": "inhalar; inspirar; absorber; chupar", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (mouth opening) + 及 (hand reaching and catching)", "sound_component": "及 (jí, reach / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Mouth 口 catching and drawing air into the body 及; represents inhalation, sucking, or absorption.", "visual_mnemonic_story_en": "A mouth (口) reaches inward to draw in (及) fresh air, inhaling deeply (吸).", "visual_mnemonic_story_es": "Una boca (口) atrae hacia adentro (及) el aire fresco, inspirando con hondura (吸).", "tone_mnemonic_anchor": "55", "cangjie": "RNHE", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代瑜伽与冥想练习中，调整呼吸被视为平复思绪与连接身心的核心纽带。练习者通过放慢呼吸节奏、进行腹式深呼吸，能够有效激活体内副交感神经系统，促使紧绷的心率与血压平稳回落，带来深度的平静与放松。", "pinyin": "Zài xiàndài yújiā yǔ míngxiǎng liànxí zhōng, tiáozhěng hūxī bèi shìwéi píngfù sīxù yǔ liánjiē shēn-xīn de héxīn niǔdài. Liànxízhě tōngguò fàngmàn hūxī jiézòu, jìnxíng fùshì shēnhūxī, nénggòu yǒuxiào jīhuó tǐnèi fùjiāogǎn shénjīng xìtǒng, cùshǐ jǐnbēng de xīnlǜ yǔ xuèyā píngwěn huíluò, dàilái shēndù de píngjìng yǔ fàngsōng.", "en": "In yoga and meditation, regulating breath connects body and mind. Slowing breathing and using deep diaphragmatic breaths activates parasympathetic systems, lowering heart rates and blood pressure for deep relaxation.", "es": "En el yoga y la meditación, acompasar la respiración une cuerpo y mente. Una respiración abdominal pausada activa el sistema parasimpático, serenando el pulso y la tensión para un sosiego hondo."}, {"id": "#2", "hanzi": "广袤繁茂的热带雨林被誉为“地球之肺”，全球数以百亿计的绿色植物通过光合作用日夜不停地进行着碳氧气体交换。大自然的每一次呼吸，不仅维系着大气层中氧气含量的动态平衡，更是守护所有生命延续的生命源泉。", "pinyin": "Guǎngmào fánmào de rèdài yǔlín bèi yùwéi 'Dìqiúzhīfèi', quánqiú shùyǐbǎiyìjì de lǜsè zhíwù tōngguò guānghé zuòyòng rìyè-bùtíng de jìnxíng zhe tàn-yǎng qìtǐ jiāohuàn. Dànzìrán de měi yí cì hūxī, bùjǐn wéixì zhe dàqìcéng zhōng yǎngqì hánliàng de dòngtài pínghéng, gèng shì shǒuhù suǒyǒu shēngmìng yánxù de shēngmìng yuánquán.", "en": "Rainforests are hailed as Earth's lungs, billions of green plants exchanging carbon and oxygen through photosynthesis day and night. Every breath of nature maintains oxygen balance, sustaining the fountain of life.", "es": "La selva amazónica es el pulmón de la Tierra; miles de millones de plantas fotosintetizan noche y día. Cada hálito de la naturaleza equilibra el oxígeno de la atmósfera custodiando la fuente misma de la vida."}]}, {"meanings_summary": {"en": "psychology; mentality; mindset; psychological", "es": "psicología; mentalidad; psique; psicológico"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The internal veins and rational principles (理) governing the human heart and mind (心) make up psychology (心理).", "composite_memory_hook_es": "Las vetas y principios lógicos (理) que rigen el corazón y la mente (心) componen la psicología (心理).", "cultural_and_cognitive_roots": "Song-Ming Neo-Confucian philosophy (心学与理学: Wang Yangming and Zhu Xi debates on 心 vs. 理); modern science fused them to translate Western psychology (心理学).", "tone_sandhi_and_pitch_modulation": "Level high tone followed by dipping third tone: 'xīn lǐ' (55-214). Maintain steady high pitch 55 on 'xīn', then dip down and rebound on 'lǐ'."}, "semantic_boundary_contrasts": {"core_nuance": "心理 encompasses the inner subjective emotional states, attitudes, and cognitive processes of individuals or groups.", "contrasts": [{"id": "1", "compared_word": "心理 vs. 生理", "pinyin": "shēnglǐ", "analysis": "生理 pertains to biological, anatomical bodily functions (hormones, digestion, heartbeat), while 心理 pertains to mental, cognitive, and emotional processes."}, {"id": "2", "compared_word": "心理 vs. 心态", "pinyin": "xīntài", "analysis": "心态 specifically designates psychological attitude or emotional outlook ('保持平稳心态'), while 心理 covers the entire academic discipline and mental structure."}, {"id": "3", "compared_word": "心理 vs. 思想", "pinyin": "sīxiǎng", "analysis": "思想 refers to political, philosophical, or ideological systems of belief ('哲学思想'), whereas 心理 refers to affective emotional states."}]}, "traps_and_cognates": {"look_alikes": [{"character": "必", "pinyin": "bì", "meaning_en": "must; surely", "distinction_note": "Has long slash stroke crossing through 心"}, {"character": "息", "pinyin": "xī", "meaning_en": "breath; rest", "distinction_note": "Has 自 atop 心"}, {"character": "埋", "pinyin": "mái", "meaning_en": "bury", "distinction_note": "Has earth radical 土 on left of 里 instead of jade 王 in 理"}, {"character": "野", "pinyin": "yě", "meaning_en": "wild; field", "distinction_note": "Has 里 on left of 予"}], "etymological_cognates": [{"character": "性", "pinyin": "xìng", "gloss_en": "human nature; character"}, {"character": "情", "pinyin": "qíng", "gloss_en": "emotion; sentiment"}, {"character": "念", "pinyin": "niàn", "gloss_en": "mindful thought; memory"}, {"character": "志", "pinyin": "zhì", "gloss_en": "ambition; intent of heart"}]}, "id": "20", "hanzi": "心理", "pinyin": "xīn lǐ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the mental and emotional states, cognitive processes, or subjective mindset of an individual or group", "definition_es": "conjunto de procesos anímicos, cognitivos y afectivos que configuran la mente de un individuo o colectivo", "example_phrase": "心理健康 (mental health)"}], "example_sentences": [{"id": "#1", "hanzi": "面对重重学业考核与升学压力，学校设立了专门的心理咨询辅导室帮助学生排解心理焦虑。", "pinyin": "Miànduì chóngchóng xuéyè kǎohé yǔ shēngxué yālì, xuéxiào shèlì le zhuānmén de xīnlǐ zīxún fǔdǎoshì bāngzhù xuésheng páijiě xīnlǐ jiāolǜ.", "en": "Facing mounting academic exams and admission pressures, the school established a dedicated psychological counseling room to help students dispel anxiety.", "es": "Ante la presión de los exámenes y el ingreso escolar, el colegio habilitó un gabinete de orientación psicológica para canalizar la ansiedad del alumnado."}, {"id": "#2", "hanzi": "资深谈判专家敏锐地洞察到了对方买家急于求成的焦躁心理，因势利导掌握了定价的主动权。", "pinyin": "Zīshēn tánpàn zhuānjiā mǐnruì de dòngchá dào le duìfāng mǎijiā jíyú-qiúchéng de jiāozào xīnlǐ, yīnshì-lìdǎo zhǎngwò le dìngjià de zhǔdòngquán.", "en": "The veteran negotiator keenly discerned the buyer's impatient psychology to close the deal, seizing the upper hand in pricing discussions.", "es": "El avezado negociador caló la impaciente psicología del comprador por cerrar el trato, tomando la iniciativa en las condiciones de precio."}], "collocations": [{"hanzi": "心理健康", "en": "mental health; psychological wellbeing"}, {"hanzi": "心理医生", "en": "psychiatrist; psychotherapist"}, {"hanzi": "心理压力", "en": "psychological stress/pressure"}, {"hanzi": "心理状态", "en": "psychological state / mindset"}, {"hanzi": "心理学", "en": "psychology (discipline)"}, {"hanzi": "心理准备", "en": "psychological readiness/preparation"}], "idioms": [{"hanzi": "心照不宣", "pinyin": "xīn zhào bù xuān", "meaning_en": "understand each other tacitly without a word spoken"}, {"hanzi": "心满意足", "pinyin": "xīn mǎn yì zú", "meaning_en": "fully satisfied and contented in heart"}, {"hanzi": "居安思危", "pinyin": "jū ān sī wēi", "meaning_en": "in peace prepare for danger; mental vigilance"}, {"hanzi": "忐忑不安", "pinyin": "tǎn tè bù ān", "meaning_en": "fidgety and restless; uneasy in mind"}], "character_decomposition": [{"character": "心", "pinyin": "xīn", "meaning_en": "heart; mind; center; core", "meaning_es": "corazón; mente; centro; núcleo", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "心 (anatomical heart with pericardium chambers)", "sound_component": "心 (xīn)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Oracle bone pictograph of the human heart, depicting the muscular chambers and aorta; the seat of thoughts and feelings in ancient epistemology.", "visual_mnemonic_story_en": "The human heart (心) beats with chambers pumping blood and cradling feelings.", "visual_mnemonic_story_es": "El corazón (心) con sus ventrículos bombea sangre cobijando pensamientos y emociones.", "tone_mnemonic_anchor": "55", "cangjie": "P", "traditional": ""}, {"character": "理", "pinyin": "lǐ", "meaning_en": "reason; logic; veins in jade; manage; principle", "meaning_es": "razón; lógica; vetas del jade; gestionar; principio", "radical": "王", "radical_meaning_en": "jade", "meaning_component": "王 (fine jade stone) + 里 (orderly village grid lines)", "sound_component": "里 (lǐ, village / phonetic)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Carving jade 王 along its natural internal grain and veins 里; signifies intrinsic principles, logic, reason, and orderly management.", "visual_mnemonic_story_en": "A master carves jade (王) following its natural inner vein lines (里) with logic and reason (理).", "visual_mnemonic_story_es": "El tallista pule el jade (王) siguiendo sus vetas naturales (里) con destreza y razón (理).", "tone_mnemonic_anchor": "214", "cangjie": "MGWG", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代竞争激烈的体育赛场上，顶尖运动员之间的技术差距往往微乎其微，最终决定胜负走向的关键往往在于心理素质的较量。面对逆境时能否顶住心理压力、保持沉着冷静，往往直接决定了冠军金牌的归属。", "pinyin": "Zài xiàndài jìngzhēng jīliè de tǐyù sàichǎng shàng, dǐngjiān yùndòngyuán zhījiān de jìshù chājù wǎngwǎng wēihūqíwēi, zuìzhōng juédìng shèngfù zǒuxiàng de guānjiàn wǎngwǎng zàiyú xīnlǐ sùzhì de jiàoliàng. Miànduì nìjìng shí néngfǒu dǐngzhù xīnlǐ yālì, bǎochí chénzhuó lěngjìng, wǎngwǎng zhíjiē juédìng le guànjūn jīnpái de guīshǔ.", "en": "In elite athletic competitions, technical gaps between champions are minuscule; victory is decided by psychological fortitude. Withstanding mental pressure in adversity and keeping cool determines gold medalists.", "es": "En la alta competición atlética, las diferencias técnicas son mínimas; el triunfo se decide en la solidez psicológica. Resistir la presión anímica en la adversidad con aplomo es lo que corona a los campeones."}, {"id": "#2", "hanzi": "关注青少年心理健康已成为全社会的共识。家庭与学校应当摒弃“唯成绩论”的片面观念，营造包容温润的成长氛围，引导孩子正确看待挫折与失败。当孩子遭遇心理困惑时，多倾听、多肯定，筑牢守护心灵的阳光港湾。", "pinyin": "Guānzhù qīng-shàonián xīnlǐ jiànkāng yǐ chéngwéi quán shèhuì de gòngshí. Jiātíng yǔ xuéxiào yīngdāng bǐngqì 'wéi chéngjì lùn' de piànmiàn guānniàn, yíngzào bāoróng wēnrùn de chéngzhǎng fēnwéi, yǐndǎo háizi zhèngquè kàndài cuòzhé yǔ shībài. Dāng háizi zāoyù xīnlǐ kùnhuò shí, duō qīngtīng, duō kěndìng, zhùláo shǒuhù xīnlíng de yángguāng gǎngwān.", "en": "Attending to adolescent mental health is a societal consensus. Families and schools should abandon grading-only biases, building nurturing environments. Listening and encouraging children facing dilemmas builds a haven for their souls.", "es": "Atender la salud mental de la juventud es un deber social unánime. Hogares y escuelas deben desterrar el culto exclusivo a las notas, acogiendo con empatía para que los jóvenes encajen tropiezos y crezcan con ilusión."}]}, {"meanings_summary": {"en": "flustered; panic-stricken; confused; agitated", "es": "nervioso; atolondrado; desconcertado; presa del pánico"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A heart thrown into wasteland panic (慌) stretched taut like a drawn bow (张) acts flustered (慌张).", "composite_memory_hook_es": "El corazón en páramo de pánico (慌) tenso como cuerda de arco (张) actúa atolondrado (慌张).", "cultural_and_cognitive_roots": "Folk psychological portrait: 慌 (internal mental confusion) paired with 张 (visible outward bodily agitation and frantic pacing).", "tone_sandhi_and_pitch_modulation": "Double level high first tones: 'huāng zhāng' (55-55). Hold level high pitch 55 across both syllables smoothly."}, "semantic_boundary_contrasts": {"core_nuance": "慌张 emphasizes visible behavioral disarray, hurried clumsiness, and loss of composure under sudden fright.", "contrasts": [{"id": "1", "compared_word": "慌张 vs. 紧张", "pinyin": "jǐnzhāng", "analysis": "紧张 describes normal physiological nervousness before exams or performances without losing control ('考试前紧张'), while 慌张 is visible flustered disarray."}, {"id": "2", "compared_word": "慌张 vs. 害怕", "pinyin": "hàipà", "analysis": "害怕 emphasizes subjective cowardice or dread of pain/danger ('害怕黑暗'), whereas 慌张 describes chaotic outward behavioral manner."}, {"id": "3", "compared_word": "慌张 vs. 匆忙", "pinyin": "cōngmáng", "analysis": "匆忙 focuses simply on being rushed for time ('匆忙赶路'), without the panic or flustered fright of 慌张."}]}, "traps_and_cognates": {"look_alikes": [{"character": "谎", "pinyin": "huǎng", "meaning_en": "lie; falsehood", "distinction_note": "Has speech radical 讠 on left instead of heart 忄 in 慌"}, {"character": "荒", "pinyin": "huāng", "meaning_en": "wasteland; famine", "distinction_note": "Has grass radical 艹 on top, lacking 忄"}, {"character": "涨", "pinyin": "zhǎng", "meaning_en": "rise; swell", "distinction_note": "Has water radical 氵 on left instead of bow 弓 in 张"}, {"character": "帐", "pinyin": "zhàng", "meaning_en": "tent; curtain", "distinction_note": "Has cloth radical 巾 on left of 长"}], "etymological_cognates": [{"character": "恐", "pinyin": "kǒng", "gloss_en": "fear in heart"}, {"character": "乱", "pinyin": "luàn", "gloss_en": "tangled silk disorder"}, {"character": "忙", "pinyin": "máng", "gloss_en": "busy heart; rushed"}, {"character": "躁", "pinyin": "zào", "gloss_en": "restless feet stamping"}]}, "id": "21", "hanzi": "慌张", "pinyin": "huāng zhāng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "flustered, hurried, agitated, and losing self-possession due to sudden panic or unexpected events", "definition_es": "inquieto, atolondrado y visiblemente turbado por una alarma o sorpresa repentina", "example_phrase": "神色慌张 (look flustered / panic-stricken in expression)"}], "example_sentences": [{"id": "#1", "hanzi": "看到巡逻民警迎面走来，小偷神色慌张地低下头，加快脚步试图溜走。", "pinyin": "Kàndào xúnluó mínjǐng yíngmiàn zǒulái, xiǎotōu shénsè huāngzhāng de dīxià tóu, jiākuài jiǎobù shìtú liūzǒu.", "en": "Seeing patrolling police officers approaching, the thief lowered his head with a flustered expression, quickening his steps to slip away.", "es": "Al ver aproximarse a la patrulla policial, el ratero bajó la cabeza con aire desconcertado apurando el paso para escaquearse."}, {"id": "#2", "hanzi": "遭遇突发火灾警报时千万不要慌张，应当用湿毛巾捂住口鼻、弯腰有序撤离。", "pinyin": "Zāoyù tūfā huǒzāi jǐngbào shí qiānwàn búyào huāngzhāng, yīngdāng yòng shī máojīn wǔzhù kǒu-bí, wānyāo yǒuxù chèlí.", "en": "Never panic when facing a sudden fire alarm; cover mouth and nose with a damp towel, bend down, and evacuate in an orderly manner.", "es": "Jamás cunda el pánico ante una alarma de incendio repentina; cúbranse boca y nariz con un paño húmedo y desalojen agachados y en orden."}], "collocations": [{"hanzi": "神色慌张", "en": "flustered expression; panicked look"}, {"hanzi": "慌张失措", "en": "flustered and at a loss what to do"}, {"hanzi": "不必慌张", "en": "no need to panic"}, {"hanzi": "举止慌张", "en": "agitated/flustered manners"}, {"hanzi": "十分慌张", "en": "extremely flustered"}, {"hanzi": "显得慌张", "en": "appear panicked / look flurried"}], "idioms": [{"hanzi": "惊慌失措", "pinyin": "jīng huāng shī cuò", "meaning_en": "panic-stricken and at a loss what to do; lose one's head"}, {"hanzi": "手忙脚乱", "pinyin": "shǒu máng jiǎo luàn", "meaning_en": "hands and feet in a fluster; frantic disorder"}, {"hanzi": "张皇失措", "pinyin": "zhāng huáng shī cuò", "meaning_en": "bewildered, terrified, and helpless in crisis"}, {"hanzi": "镇定自若", "pinyin": "zhèn dìng zì ruò", "meaning_en": "calm, composed, and completely in control of oneself"}], "character_decomposition": [{"character": "慌", "pinyin": "huāng", "meaning_en": "panicky; flurried; confused; nervous", "meaning_es": "inquieto; turbado; asustado; aturdido", "radical": "忄", "radical_meaning_en": "heart", "meaning_component": "忄 (distressed agitated heart) + 荒 (wasteland overgrown with weeds)", "sound_component": "荒 (huāng, wasteland / phonetic)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Heart radical 忄 combined with 荒 (wild desolate weed fields); feelings thrown into disarray like a wild overgrown wasteland.", "visual_mnemonic_story_en": "Emotions in the heart (忄) run wild like weeds in an unkempt wasteland (荒), sparking panic (慌).", "visual_mnemonic_story_es": "Las emociones del corazón (忄) se desbordan como maleza en páramo yermo (荒) desatando el pavor (慌).", "tone_mnemonic_anchor": "55", "cangjie": "PTYU", "traditional": ""}, {"character": "张", "pinyin": "zhāng", "meaning_en": "draw bow; stretch; spread; display", "meaning_es": "tensar arco; abrir; extender; desplegar", "radical": "弓", "radical_meaning_en": "bow", "meaning_component": "弓 (archery bow) + 长 (long / extended tension)", "sound_component": "长 (cháng/zhǎng, long / phonetic carrier)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "An archer drawing a bow 弓 to full length 长; represents stretching, tension, spreading out, or looking wide-eyed.", "visual_mnemonic_story_en": "Pulling an archer's bow (弓) taut to its longest stretch (长) strains tension (张).", "visual_mnemonic_story_es": "Tensar la cuerda del arco (弓) a su máxima longitud (长) refleja tirantez y agitación (张).", "tone_mnemonic_anchor": "55", "cangjie": "NPO", "traditional": "張"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代空难与火灾逃生演练中，安全专家反复强调“遇险不慌张”的核心生存法则。当灾难降临时，盲目慌张奔逃只会导致致命的踩踏事故，唯有沉着冷静、服从指挥引导，才能在黄金时间内安全疏散。", "pinyin": "Zài xiàndài kōngnàn yǔ huǒzāi táoshēng yǎnliàn zhōng, ānquán zhuānjiā fǎnfù qiángdiào 'yùxiǎn bù huāngzhāng' de héxīn shēngcún fǎzé. Dāng zāinàn jiànglín shí, mángmù huāngzhāng bēntáo zhǐhuì dǎozhì zhìmìng de cǎità shìgù, wéiyǒu chénzhuó-lěngjìng, fúcóng zhǐhuī yǐndǎo, cáinéng zài huángjīn shíjiān nèi ānquán shūsàn.", "en": "In fire and emergency drills, experts stress the rule of avoiding panic. When disaster strikes, blind panic leads to fatal stampedes; remaining calm and following guidance ensures safe evacuation within golden minutes.", "es": "En simulacros de evacuación, expertos recalcan la regla de oro: mantener la calma ante el peligro. Huir despavoridos provoca avalanchas letales; solo la serenidad y la disciplina salvan vidas en minutos clave."}, {"id": "#2", "hanzi": "当清晨闹钟骤然大作时，深度睡眠中的人体交感神经被强行激活，常常伴随一阵莫名的心慌意乱与神色慌张。这种突发性惊醒破坏了大脑从浅睡眠自然唤醒的平稳节律，长期以往会使人形成神经质的早起焦虑症。", "pinyin": "Dāng qīngchén nàozhōng zhòurán dàzuò shí, shēndù shuìmián zhōng de réntǐ jiāogǎn shénjīng bèi qiángxíng jīhuó, chángcháng bànsuí yí zhèn mòmíng de xīnhuāng-yìluàn yǔ shénsè huāngzhāng. Zhè zhǒng tūfāxìng jīngxǐng pòhuài le dànǎo cóng qiǎn shuìmián zìrán huànxǐng de píngwěn jiélǜ, chángqī yǐwǎng huì shǐ rén xíngchéng shénjīngzhì de zǎoqǐ jiāolǜzhèng.", "en": "When alarms blare, sympathetic nerves in deep sleepers activate abruptly, accompanied by heart palpitations and flustered panic. This sudden jolt disrupts smooth natural awakening, inducing chronic morning anxiety.", "es": "Al rugir el despertador, el sistema simpático se activa de golpe provocando palpitaciones y agitación ansiosa. Esta sacudida quiebra el despertar apacible desde el sueño ligero, induciendo una neurosis matinal crónica."}]}, {"meanings_summary": {"en": "emotion; mood; sentiment; morale", "es": "emoción; estado de ánimo; humor; temple"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Heartfelt affections (情) tangled like unraveled silk threads (绪) make up human emotions and moods (情绪).", "composite_memory_hook_es": "Afectos del corazón (情) deshilvanados como hebras de seda (绪) componen el estado anímico (情绪).", "cultural_and_cognitive_roots": "Literary psychological metaphor (千头万绪: thousands of tangled emotional thread-ends); silk reeling mirrors the delicate sorting of complex psychological states.", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'qíng xù' (35-51). Rise smoothly on 'qíng', then descend decisively on 'xù'."}, "semantic_boundary_contrasts": {"core_nuance": "情绪 refers to dynamic, subjective psychological moods and emotional reactions.", "contrasts": [{"id": "1", "compared_word": "情绪 vs. 情感", "pinyin": "qínggǎn", "analysis": "情感 refers to deep, enduring, and stable moral or interpersonal sentiments (patriotic affection, love of family), while 情绪 refers to transient moods (anger, sadness, joy)."}, {"id": "2", "compared_word": "情绪 vs. 心情", "pinyin": "xīnqíng", "analysis": "心情 is colloquial and refers to personal daily good/bad moods ('心情愉快'), while 情绪 can describe collective morale of crowds ('群众情绪稳定')."}, {"id": "3", "compared_word": "情绪 vs. 脾气", "pinyin": "píqi", "analysis": "脾气 refers to innate human temperament or anger tantrums ('发脾气'), distinct from scientific emotional states."}]}, "traps_and_cognates": {"look_alikes": [{"character": "晴", "pinyin": "qíng", "meaning_en": "sunny; clear", "distinction_note": "Has sun radical 日 on left of 青 instead of heart 忄 in 情"}, {"character": "请", "pinyin": "qǐng", "meaning_en": "please; invite", "distinction_note": "Has speech radical 讠 on left of 青"}, {"character": "绩", "pinyin": "jì", "meaning_en": "merit; achievement", "distinction_note": "Has 责 on right of 纟 instead of 者 in 绪"}, {"character": "续", "pinyin": "xù", "meaning_en": "continue", "distinction_note": "Has 卖 on right of 纟"}], "etymological_cognates": [{"character": "感", "pinyin": "gǎn", "gloss_en": "feel; moved by emotion"}, {"character": "意", "pinyin": "yì", "gloss_en": "inner voice of heart; intent"}, {"character": "心", "pinyin": "xīn", "gloss_en": "seat of feelings; heart"}, {"character": "志", "pinyin": "zhì", "gloss_en": "willpower of mind"}]}, "id": "22", "hanzi": "情绪", "pinyin": "qíng xù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a conscious mental reaction (anger, joy, grief, fear) subjectively experienced and accompanied by physiological changes", "definition_es": "reacción psicofisiológica que refleja el estado de ánimo (alegría, cólera, pena, desánimo)", "example_phrase": "控制情绪 (control one's emotions)"}], "example_sentences": [{"id": "#1", "hanzi": "成年人最重要的一项修养，就是在遇到挑衅或不顺心的事情时能够理智地管理好自己的负面情绪。", "pinyin": "Chéngniánrén zuì zhòngyào de yí xiàng xiūyǎng, jiùshì zài yùdào tiǎoxìn huò búshùnxīn de shìqing shí nénggòu lǐzhì de guǎnlǐ hǎo zìjǐ de fùmiàn qíngxù.", "en": "An adult's most important cultivation is managing negative emotions rationally when facing provocation or setbacks.", "es": "El rasgo primordial de madurez es saber gobernar las emociones negativas con raciocinio ante afrentas o contrariedades."}, {"id": "#2", "hanzi": "连日阴雨绵绵、不见天日，灰暗低沉的天气容易导致部分敏感体质的人产生烦躁压抑的消极情绪。", "pinyin": "Liánrì yīnyǔ miánmián, bú jiàn tiānrì, huī'àn dīchén de tiānqì róngyì dǎozhì bùfen mǐngǎn tǐzhì de rén chǎnshēng fánzào yāyì de xiāojí qíngxù.", "en": "Successive days of continuous overcast rain and lack of sunshine easily cause sensitive people to develop irritable, depressed moods.", "es": "Días seguidos de llovizna plomiza y falta de sol inducen fácilmente desánimo, fastidio y melancolía en personas sensibles."}], "collocations": [{"hanzi": "稳定情绪", "en": "stabilize emotions / calm down"}, {"hanzi": "负面情绪", "en": "negative emotions"}, {"hanzi": "情绪低落", "en": "depressed mood / low spirits"}, {"hanzi": "情绪激动", "en": "emotionally agitated / excited"}, {"hanzi": "控制情绪", "en": "control one's temper/emotions"}, {"hanzi": "情绪波动", "en": "mood swings / emotional fluctuations"}], "idioms": [{"hanzi": "喜怒无常", "pinyin": "xǐ nù wú cháng", "meaning_en": "capricious and temperamental; unpredictable mood swings"}, {"hanzi": "喜形于色", "pinyin": "xǐ xíng yú sè", "meaning_en": "joy beaming on one's face; visibly joyful"}, {"hanzi": "心平气和", "pinyin": "xīn píng qì hé", "meaning_en": "calm and even-tempered; placid in mind and breath"}, {"hanzi": "意气风发", "pinyin": "yì qì fēng fā", "meaning_en": "in high and enthusiastic spirits; daring vigor"}], "character_decomposition": [{"character": "情", "pinyin": "qíng", "meaning_en": "feeling; emotion; sentiment; passion; situation", "meaning_es": "sentimiento; afecto; emoción; situación", "radical": "忄", "radical_meaning_en": "heart", "meaning_component": "忄 (inner heart feelings) + 青 (pure green / budding life)", "sound_component": "青 (qīng, green/pure / phonetic)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Heart radical 忄 combined with 青 (pure youthful vigor); feelings and emotional affections welling up from within the human soul.", "visual_mnemonic_story_en": "Feelings in the human heart (忄) bloom fresh and genuine like spring greenery (青), creating emotion (情).", "visual_mnemonic_story_es": "Los afectos del corazón (忄) brotan con la lozanía de la primavera verde (青) expresando la emoción (情).", "tone_mnemonic_anchor": "35", "cangjie": "PQMB", "traditional": ""}, {"character": "绪", "pinyin": "xù", "meaning_en": "thread end; beginning; mental state; clue", "meaning_es": "cabo de hilo; principio; hilo mental; pista", "radical": "纟", "radical_meaning_en": "silk", "meaning_component": "纟 (skein of silk thread) + 者 (person sorting fibers)", "sound_component": "者 (zhě, person / phonetic origin)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Silk radical 纟 paired with 者; pulling the initial lead thread end out of a tangled cocoon to unravel order, extended to mental strands of mood.", "visual_mnemonic_story_en": "A hand pulls the lead thread (纟) from a silk cocoon (者), sorting tangled emotional strands (绪).", "visual_mnemonic_story_es": "Una mano desentraña el cabo (纟) de un capullo de seda (者) ordenando la maraña de afectos (绪).", "tone_mnemonic_anchor": "51", "cangjie": "VMJKA", "traditional": "緒"}], "extended_reading_passages": [{"id": "#1", "hanzi": "现代心理学研究发现，情绪并非理性思考的对立面，而是人类漫长演化历程中形成的高效生存预警机制。接纳自身情绪的存在，学会识别恐惧、愤怒或悲伤背后的心理诉求，是建立强大心理复原力不可或缺的第一步。", "pinyin": "Xiàndài xīnlǐxué yánjiū fāxiàn, qíngxù bìngfēi lǐxìng sīkǎo de duìlìmiàn, érshì rénlèi màncháng yǎnhuà lìchéng zhōng xíngchéng de gāoxiào shēngcún yùjǐng jīzhì. Jiēnà zìshēn qíngxù de cúnzài, xuéhuì shíbié kǒngjù, fènnù huò bēishāng bèihòu de xīnlǐ sùqiú, shì jiànlì qiángdà xīnlǐ fùyuánlì bùkě-huòquē de dì-yī bù.", "en": "Psychology shows emotions are not foes of reason, but efficient survival alert mechanisms evolved over eons. Accepting emotions and decoding the needs behind fear or anger is the first step toward building resilience.", "es": "La psicología moderna demuestra que la emoción no riñe con la razón, sino que es una alerta evolutiva de supervivencia. Asumir los afectos y descifrar el temor o la ira es clave para forjar resiliencia."}, {"id": "#2", "hanzi": "在团队管理与团队协作中，领导者的情绪稳定度直接决定了整个团队的凝聚力与战斗力。面对突如其来的危机考验，主心骨若能从容镇定、临危不乱，便能有效抚平下属的恐慌情绪，带领大家迎难而上化解险情。", "pinyin": "Zài tuánduì guǎnlǐ yǔ tuánduì xiézuò zhōng, lǐngdǎozhě de qíngxù wěndìngdù zhíjiē juédìng le zhěng gè tuánduì de níngjùlì yǔ zhàndòulì. Miànduì tūrúqílái de wēijī kǎoyàn, zhǔxīngǔ ruò néng cóngróng-zhèndìng, línwēi-búluàn, biàn néng yǒuxiào fǔpíng xiàshǔ de kǒnghuāng qíngxù, dàilǐng dàjiā yíngnán'érshàng huàjiě xiǎnqíng.", "en": "In leadership, emotional stability determines team cohesion and fighting power. When facing crises, an unshakeable leader calms subordinates' panic, guiding everyone to confront difficulties and defuse peril.", "es": "En la dirección de equipos, el temple anímico del líder apuntala la cohesión colectiva. Ante las tempestades, un guía sereno sosiega el pánico general liderando con firmeza la superación del trance."}]}, {"meanings_summary": {"en": "downcast; depressed; low (spirits/morale); slumped", "es": "decaído; abatido; deprimido; bajo (ánimo, moral)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Bowing low (低) like withered autumn leaves falling to earth (落) portrays downcast spirits (低落).", "composite_memory_hook_es": "Inclinarse bajo (低) como hojas de otoño cayendo a tierra (落) retrata el abatimiento (低落).", "cultural_and_cognitive_roots": "Spatial elevation metaphor (Lakoff & Johnson: happy is up, sad is down); dropping down from high vitality into a despondent trough.", "tone_sandhi_and_pitch_modulation": "Level high tone followed by falling fourth tone: 'dī luò' (55-51). Hold high pitch 55 on 'dī', then plunge down sharply on 'luò'."}, "semantic_boundary_contrasts": {"core_nuance": "低落 specifically modifies psychological moods or collective morale sinking into a disheartened trough.", "contrasts": [{"id": "1", "compared_word": "低落 vs. 沮丧", "pinyin": "jǔsàng", "analysis": "沮丧 emphasizes acute disappointment, frustration, and wounded self-esteem following a setback, while 低落 is quiet, passive emotional flatness."}, {"id": "2", "compared_word": "低落 vs. 低沉", "pinyin": "dīchén", "analysis": "低沉 modifies acoustic voice pitch (deep, muffled voice: '声音低沉') or dark gloomy weather, while 低落 modifies mood and morale."}, {"id": "3", "compared_word": "低落 vs. 悲伤", "pinyin": "bēishāng", "analysis": "悲伤 refers to sharp sorrow, weeping, and grief over loss, while 低落 is low energy and apathy."}]}, "traps_and_cognates": {"look_alikes": [{"character": "底", "pinyin": "dǐ", "meaning_en": "bottom; foundation", "distinction_note": "Has shelter radical 广 enclosing 氐 instead of person 亻 in 低"}, {"character": "抵", "pinyin": "dǐ", "meaning_en": "resist;抵押 mortgage", "distinction_note": "Has hand radical 扌 on left of 氐"}, {"character": "满", "pinyin": "mǎn", "meaning_en": "full", "distinction_note": "Has water radical 氵 on left of 艹 and 两"}, {"character": "暮", "pinyin": "mù", "meaning_en": "dusk", "distinction_note": "Has 日 underneath 艹 and 大"}], "etymological_cognates": [{"character": "沉", "pinyin": "chén", "gloss_en": "sink into water deep"}, {"character": "降", "pinyin": "jiàng", "gloss_en": "descend from steep hill"}, {"character": "下", "pinyin": "xià", "gloss_en": "below; downwards"}, {"character": "垂", "pinyin": "chuí", "gloss_en": "droop down heavy"}]}, "id": "23", "hanzi": "低落", "pinyin": "dī luò", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "low, depressed, slumped, or sinking (of mood, morale, spirits, or tide)", "definition_es": "decaído, abatido o en declive (dicho del ánimo, moral o nivel de las aguas)", "example_phrase": "情绪低落 (downcast in mood)"}], "example_sentences": [{"id": "#1", "hanzi": "这次全国选拔赛痛失冠军后，他连续好几天情绪低落，一个人躲在房间里闭门不出。", "pinyin": "Zhè cì quánguó xuǎnbásài tòngshī guànjūn hòu, tā liánxù hǎojǐ tiān qíngxù dīluò, yí ge rén duǒ zài fángjiān lǐ bìmén-bùchū.", "en": "After painfully missing the championship in this national trial, he remained in low spirits for days, hiding alone behind closed doors.", "es": "Tras perder el campeonato nacional por la mínima, anduvo abatido varios días encerrado a solas en su cuarto sin ver a nadie."}, {"id": "#2", "hanzi": "部队遭遇强敌阻击受挫，指挥官发表了慷慨激昂的动员讲话，彻底扭转了士气低落的被动局面。", "pinyin": "Bùduì zāoyù qiángdí zǔjī shòucuò, zhǐhuīguān fābiǎo le kāngkǎi-jī'áng de dòngyuán jiǎnghuà, chèdǐ niǔzhuǎn le shìqì dīluò de bèidòng júmiàn.", "en": "Suffering setbacks against strong enemy ambushes, the commander delivered an impassioned rousing speech, reversing the low morale.", "es": "Ante el repliegue por el fuego enemigo, la vibrante arenga del comandante levantó la alicaída moral de la tropa trocando el rumbo del combate."}], "collocations": [{"hanzi": "情绪低落", "en": "depressed mood / low spirits"}, {"hanzi": "士气低落", "en": "low morale"}, {"hanzi": "神情低落", "en": "downcast expression"}, {"hanzi": "情绪非常低落", "en": "extremely despondent"}, {"hanzi": "走出低落", "en": "step out of depression/slump"}, {"hanzi": "潮水低落", "en": "ebb tide / low water level"}], "idioms": [{"hanzi": "垂头丧气", "pinyin": "chuí tóu sàng qì", "meaning_en": "hang one's head in dejection; crestfallen"}, {"hanzi": "闷闷不乐", "pinyin": "mèn mèn bú lè", "meaning_en": "gloomy and sullen; out of sorts"}, {"hanzi": "灰心丧气", "pinyin": "huī xīn sàng qì", "meaning_en": "lose heart and despondent; disheartened"}, {"hanzi": "振作精神", "pinyin": "zhèn zuò jīng shén", "meaning_en": "pull oneself together; summon up one's spirits"}], "character_decomposition": [{"character": "低", "pinyin": "dī", "meaning_en": "low; beneath; hang down; inferior", "meaning_es": "bajo; inferior; agachar; descender", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person bowing) + 氐 (bottom / foundation)", "sound_component": "氐 (dǐ, base / phonetic)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 bowing low down to the ground or foundation 氐; signifies low height, drooping head, or modest depth.", "visual_mnemonic_story_en": "A standing person (亻) bows down low to the soil baseline (氐), hanging the head (低).", "visual_mnemonic_story_es": "Una persona (亻) agacha la cabeza humilde hacia la base del suelo (氐) inclinándose baja (低).", "tone_mnemonic_anchor": "55", "cangjie": "OHYPM", "traditional": ""}, {"character": "落", "pinyin": "luò", "meaning_en": "fall; drop; descend; decline; settlement", "meaning_es": "caer; descender; declinar; aldea", "radical": "艹", "radical_meaning_en": "grass / plant", "meaning_component": "艹 (leaves/foliage) + 洛 (water swirling down)", "sound_component": "洛 (luò, water river / phonetic)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Autumn leaves 艹 falling drifting down upon swirling waters 洛; signifies descending, falling, or dropping low.", "visual_mnemonic_story_en": "Withered autumn leaves (艹) swirl downward on flowing river water (洛), falling low (落).", "visual_mnemonic_story_es": "Hojas marchitas de otoño (艹) flotan descendiendo por el agua del río (洛), cayendo al suelo (落).", "tone_mnemonic_anchor": "51", "cangjie": "TEHR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "人生的旅途中总会经历潮起潮落，遭遇挫折时情绪低落是极其正常的生理应激反应。关键在于不要长期沉溺于自我怀疑的消极泥潭中，应当多与良师益友交流倾诉，在温暖关爱中重燃对美好生活的信心与热爱。", "pinyin": "Rénshēng de lǚtú zhōng zǒng huì jīnglì cháoqǐ-cháoluò, zāoyù cuòzhé shí qíngxù dīluò shì jíqí zhèngcháng de shēnglǐ yìngjī fǎnyìng. Guānjiàn zàiyú búyào chángqī chénnì yú zìwǒ huáiyí de xiāojí nítán zhōng, yīngdāng duō yǔ liángshī-yìyǒu jiāoliú qīngsù, zài wēnnuǎn guān'ài zhōng chóngrán duì měihǎo shēnghuó de xìnxīn yǔ rè'ài.", "en": "In life's journey, tides ebb and flow; low moods after setbacks are normal stress reactions. The key is avoiding prolonged self-doubt, confiding in mentors and friends to rekindle confidence and love for life.", "es": "La vida conoce pleamares y bajamares; decaerse ante reveses es una respuesta humana natural. Lo crucial es no encallarse en la apatía, desahogándose con leales amigos para avivar la confianza en el porvenir."}, {"id": "#2", "hanzi": "医学临床调查显示，慢性失眠患者由于夜间缺乏深度脑部休息，白天更容易陷入情绪低落与注意力涣散的恶性循环。保证规律作息、适当接受日光照射，能够有效促进大脑分泌多巴胺与血清素，驱散心灵阴霾。", "pinyin": "Yīxué línchuáng diàochá xiǎnshì, mànxìng shīmián huànzhě yóuyú yèjiān quēfá shēndù nǎobù xiūxi, báitiān gèng róngyì xiànrù qíngxù dīluò yǔ zhùyìlì huànsàn de èxìng xúnhuán. Bǎozhèng guīlǜ zuòxī, shìdàng jiēshòu rìguāng zhàoshè, nénggòu yǒuxiào cùjìn dànǎo fēnmì duōbā'àn yǔ xuèqīngsù, qūsàn xīnlíng yīnmái.", "en": "Clinical surveys show chronic insomniacs, lacking deep brain rest at night, easily fall into cycles of low spirits and distraction. Maintaining regular routines and soaking in sunlight stimulates dopamine to dispel gloom.", "es": "Estudios clínicos revelan que el insomnio crónico aboca de día a un círculo vicioso de desánimo y dispersión. Guardar horarios regulares y tomar el sol estimula la serotonina, disipando la bruma anímica."}]}, {"meanings_summary": {"en": "memory; recollection; to memorize; to remember", "es": "memoria; recuerdo; acordarse; memorizar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Notes recorded in words (记) that uncurl feelings in the heart (忆) form our memories (记忆).", "composite_memory_hook_es": "Apuntes transcritos en palabras (记) que despiertan el eco del corazón (忆) forman la memoria (记忆).", "cultural_and_cognitive_roots": "Epistemological pairing: 记 (external recorded inscription) + 忆 (internal affective recall in the heart); cognitive retaining and retrieving.", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'jì yì' (51-51). Descend sharply on 'jì', then land firmly with equal force on 'yì'."}, "semantic_boundary_contrasts": {"core_nuance": "记忆 encompasses both the biological cognitive storage faculty (memory capacity) and individual recollections of past events.", "contrasts": [{"id": "1", "compared_word": "记忆 vs. 回忆", "pinyin": "huíyì", "analysis": "回忆 is an active dynamic verb meaning 'to recall / reminisce about past events' ('回忆童年往事'), while 记忆 is the noun faculty ('记忆力') or content of memory."}, {"id": "2", "compared_word": "记忆 vs. 纪念", "pinyin": "jìniàn", "analysis": "纪念 involves public honoring or keeping souvenirs of historical legacies ('人民英雄纪念碑'), while 记忆 is psychological storage."}, {"id": "3", "compared_word": "记忆 vs. 记录", "pinyin": "jìlù", "analysis": "记录 refers to written notes, recorded logs, or athletic sports scores ('打破世界纪录'), not neural cognitive storage."}]}, "traps_and_cognates": {"look_alikes": [{"character": "纪", "pinyin": "jì", "meaning_en": "era; record", "distinction_note": "Has silk radical 纟 on left of 己 instead of speech 讠 in 记"}, {"character": "订", "pinyin": "dìng", "meaning_en": "book; subscribe", "distinction_note": "Has 丁 on right of 讠"}, {"character": "乞", "pinyin": "qǐ", "meaning_en": "beg", "distinction_note": "Has upper horizontal stroke, unlike 乙"}, {"character": "忙", "pinyin": "máng", "meaning_en": "busy", "distinction_note": "Has 亡 on right of 忄 instead of 乙 in 忆"}], "etymological_cognates": [{"character": "念", "pinyin": "niàn", "gloss_en": "think of; mindful thought"}, {"character": "怀", "pinyin": "huái", "gloss_en": "bosom; cherish memory"}, {"character": "思", "pinyin": "sī", "gloss_en": "ponder deeply; yearn"}, {"character": "想", "pinyin": "xiǎng", "gloss_en": "imagine; remember tree"}]}, "id": "24", "hanzi": "记忆", "pinyin": "jì yì", "level": "HSK 5", "part_of_speech": "Noun / Verb", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the cognitive faculty of encoding, retaining, and recalling past experiences, information, or skills", "definition_es": "facultad cognitiva de retener y recordar vivencias o nociones pasadas; recuerdo", "example_phrase": "记忆力很强 (have a strong memory)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to commit to memory, memorize, or keep consciously in mind", "definition_es": "memorizar, retener o fijar conocimientos en la mente", "example_phrase": "记忆生词 (memorize new vocabulary)"}], "example_sentences": [{"id": "#1", "hanzi": "童年在外婆家门前那条清澈溪流边捉螃蟹的快乐时光，是他脑海中永不褪色的美好记忆。", "pinyin": "Tóngnián zài wàipó jiā ménqián nà tiáo qīngchè xīliú biān zhuō pángxiè de kuàilè shíguāng, shì tā nǎohǎi zhōng yǒngbútùisè de měihǎo jìyì.", "en": "Childhood happy hours catching crabs beside the clear brook before maternal grandmother's house are timeless memories that never fade in his mind.", "es": "Las risas de infancia atrapando cangrejos en el arroyo límpido frente a casa de la abuela son recuerdos imborrables en su memoria."}, {"id": "#2", "hanzi": "神经科学研究表明，高质量的深度睡眠对于大脑巩固日间所学知识与形成长期记忆至关重要。", "pinyin": "Shénjīng kēxué yánjiū biǎomíng, gāozhìliàng de shēndù shuìmián duìyú dànǎo gǒnggù rìjiān suǒ xué zhīshi yǔ xíngchéng chángqī jìyì zhìguān-zhòngyào.", "en": "Neuroscience indicates that high-quality deep sleep is crucial for the brain to consolidate daytime knowledge and form long-term memories.", "es": "La neurociencia constata que el sueño profundo de calidad es crucial para que el cerebro fije lo aprendido y consolide la memoria duradera."}], "collocations": [{"hanzi": "记忆力", "en": "memory capacity; power of recollection"}, {"hanzi": "童年记忆", "en": "childhood memories"}, {"hanzi": "恢复记忆", "en": "recover memory"}, {"hanzi": "长期记忆", "en": "long-term memory"}, {"hanzi": "失去记忆", "en": "lose memory / amnesia"}, {"hanzi": "唤醒记忆", "en": "awaken/evoke memories"}], "idioms": [{"hanzi": "记忆犹新", "pinyin": "jì yì yóu xīn", "meaning_en": "remain fresh in one's memory; remember as if yesterday"}, {"hanzi": "难以忘怀", "pinyin": "nán yǐ wàng huái", "meaning_en": "hard to forget; cherished unforgettable memory"}, {"hanzi": "过目不忘", "pinyin": "guò mù bù wàng", "meaning_en": "photographic memory; never forget what has once been seen"}, {"hanzi": "铭肌镂骨", "pinyin": "míng jī lòu gǔ", "meaning_en": "engraved on flesh and bone; indelible deep gratitude"}], "character_decomposition": [{"character": "记", "pinyin": "jì", "meaning_en": "record; remember; chronicle; mark", "meaning_es": "anotar; recordar; crónica; marca", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken words recorded) + 己 (self / boundary marker)", "sound_component": "己 (jǐ / phonetic)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken words 讠 committed to personal awareness 己 on bamboo slips; signifies recording, noting down, or remembering.", "visual_mnemonic_story_en": "Words (讠) are noted down carefully for oneself (己) so as to remember (记).", "visual_mnemonic_story_es": "Las palabras (讠) se anotan para uno mismo (己) a fin de recordarlas bien (记).", "tone_mnemonic_anchor": "51", "cangjie": "IVSU", "traditional": "記"}, {"character": "忆", "pinyin": "yì", "meaning_en": "remember; recall; memory", "meaning_es": "recordar; evocar; memoria", "radical": "忄", "radical_meaning_en": "heart", "meaning_component": "忄 (inner heart sentiment) + 乙 (twisted sprouting sprout)", "sound_component": "乙 (yǐ / phonetic origin)", "stroke_count": "4", "composition_type": "左右结构", "etymology_and_mnemonic": "Heart radical 忄 storing uncurling thoughts and recollections 乙; represents reflecting back upon past events in the heart.", "visual_mnemonic_story_en": "The heart (忄) traces back through winding past experiences (乙) to recall memories (忆).", "visual_mnemonic_story_es": "El corazón (忄) desanda meandros del pasado (乙) evocando tiernos recuerdos (忆).", "tone_mnemonic_anchor": "51", "cangjie": "PN", "traditional": "憶"}], "extended_reading_passages": [{"id": "#1", "hanzi": "漫步在故乡斑驳青石板铺成的小巷深处，古老民居院落里飘散出熟悉的饭菜香气，总能瞬间激活沉睡在脑海深处的童年记忆。时光虽已匆匆流逝数十载，但那份浸润着亲情与乡愁的温馨回忆，却历久弥新、清晰如昨。", "pinyin": "Mànbù zài gùxiāng bānbó qīngshíbǎn pūchéng de xiǎoxiàng shēnchù, gǔlǎo mínjū yuànluò lǐ piāosàn chū shúxī de fàncài xiāngqì, zǒng néng shùnjiān jīhuó chénsù zài nǎohǎi shēnchù de tóngnián jìyì. Shíguāng suī yǐ cōngcōng liúshì shùshí zǎi, dàn nà fèn jìnrùn zhe qīnqíng yǔ xiāngchóu de wēnxīn huíyì, què lìjiǔ-míxīn, qīngxī rú zuó.", "en": "Strolling deep in old paved alleyways of home, aromas from ancient courtyards instantly awaken dormant childhood memories. Though decades passed, warm recollections soaked in family love remain fresh as yesterday.", "es": "Pasear por callejuelas empedradas de la aldea natal oliendo guisos caseros revive recuerdos de infancia adormecidos. Aunque pasen decenios, esa memoria teñida de cariño y nostalgia sigue viva como ayer."}, {"id": "#2", "hanzi": "数字化时代，海量外部智能设备在极大拓展人类信息储存边界的同时，也在不知不觉中削弱了人们的本能记忆能力。面对电话号码与日常行程安排，现代人越来越依赖手机备忘录，自主大脑记忆训练显得愈发重要。", "pinyin": "Shùzìhuà shídài, hǎiliàng wàibù zhìnéng shèbèi zài jídà tuòzhǎn rénlèi xìnxī chǔcún biānjiè de tóngshí, yě zài bùzhī-bùjué zhōng xuēruò le rénmen de běnnéng jìyì nénglì. Miànduì diànhuà hàomǎ yǔ rìcháng xíngchéng ānpái, xiàndàirén yuèláiyuè yīlài shǒujī bèiwànglù, zìzhǔ dànǎo jìyì xùnliàn xiǎnde yùfā zhòngyào.", "en": "In the digital age, smart devices expand information storage boundaries yet subtly weaken innate memory. Relying on phone memos for contacts and agendas, autonomous brain memory exercise is ever more vital.", "es": "En la era digital, la memoria externa de los dispositivos móviles expande datos pero merma la retentiva natural. Confiando teléfonos y citas a blocs digitales, ejercitar la propia memoria cerebral se torna indispensable."}]}, {"meanings_summary": {"en": "to calculate; to compute; to reckon; calculation", "es": "calcular; computar; contar; cálculo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Tallying numbers to ten (计) with bamboo counting rods (算) executes mathematical calculation (计算).", "composite_memory_hook_es": "Sumar cifras de diez en diez (计) con varillas de bambú en el ábaco (算) ejecuta el cálculo (计算).", "cultural_and_cognitive_roots": "Ancient Chinese mathematics: counting rods (算筹) and the suanpan abacus (算盘); formed the computational basis for the Nine Chapters on Mathematical Art (九章算术).", "tone_sandhi_and_pitch_modulation": "Double falling fourth tones: 'jì suàn' (51-51). Descend sharply on 'jì', then land with a firm snap on 'suàn'."}, "semantic_boundary_contrasts": {"core_nuance": "计算 focuses on rigorous mathematical, algorithmic, or numerical computation of figures.", "contrasts": [{"id": "1", "compared_word": "计算 vs. 估算", "pinyin": "gūsuàn", "analysis": "估算 refers to rough approximation or guesswork without precise formulas, while 计算 requires exact arithmetic or algorithmic deduction."}, {"id": "2", "compared_word": "计算 vs. 运算", "pinyin": "yùnsuàn", "analysis": "运算 specifically designates the mathematical operational process (+, -, ×, ÷ or boolean logic), while 计算 is the broader determination of quantities."}, {"id": "3", "compared_word": "计算 vs. 打算", "pinyin": "dǎsuàn", "analysis": "打算 is a common colloquial verb meaning 'to plan / intend to do something' ('我打算去旅游'), not mathematical calculation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "订", "pinyin": "dìng", "meaning_en": "book; agree", "distinction_note": "Has 丁 on right of 讠 instead of 十 in 计"}, {"character": "讨", "pinyin": "tǎo", "meaning_en": "discuss; demand", "distinction_note": "Has 寸 on right of 讠"}, {"character": "鼻", "pinyin": "bí", "meaning_en": "nose", "distinction_note": "Has 自 on top of 畀 instead of bamboo 竹 in 算"}, {"character": "笨", "pinyin": "bèn", "meaning_en": "clumsy", "distinction_note": "Has 本 underneath 竹"}], "etymological_cognates": [{"character": "数", "pinyin": "shǔ", "gloss_en": "count; tally grain"}, {"character": "核", "pinyin": "hé", "gloss_en": "audit core numbers; verify"}, {"character": "量", "pinyin": "liàng", "gloss_en": "measure grain bucket"}, {"character": "估", "pinyin": "gū", "gloss_en": "estimate; appraise ancient value"}]}, "id": "25", "hanzi": "计算", "pinyin": "jì suàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to determine mathematically through numerical operations, formulas, or algorithms", "definition_es": "determinar matemáticamente mediante operaciones numéricas, fórmulas o algoritmos", "example_phrase": "计算成本 / 计算机 (calculate costs / computer)"}], "example_sentences": [{"id": "#1", "hanzi": "航天测控中心的超级计算机仅用数秒时间，便精确计算出了飞船重返大气层的最佳轨道参数。", "pinyin": "Hángtiān cèkòng zhōngxīn de chāojí jìsuànjī jǐn yòng shù miǎo shíjiān, biàn jīngquè jìsuàn chū le fēichuán chóngfǎn dàqìcéng de zuìjiā guǐdào cānshù.", "en": "In mere seconds, the aerospace control center's supercomputer precisely calculated optimal orbital parameters for the spacecraft's reentry.", "es": "En escasos segundos, el superordenador del centro aeroespacial calculó con exactitud los parámetros orbitales para la reentrada de la nave."}, {"id": "#2", "hanzi": "在做出这项重大商业投资决定之前，财务分析师必须严谨计算潜在的投资回报率与市场风险。", "pinyin": "Zài zuòchū zhè xiàng zhòngdà shāngyè tóuzī juédìng zhīqián, cáiwù fēnxīshī bìxū yánjǐn jìsuàn qiánzài de tóuzī huíbàolǜ yǔ shìchǎng fēngxiǎn.", "en": "Before making this major commercial investment decision, financial analysts must rigorously calculate potential return rates and market risks.", "es": "Antes de acometer esta inversión mercantil de calado, los analistas financieros deben calcular con rigor la rentabilidad y el riesgo de mercado."}], "collocations": [{"hanzi": "计算机", "en": "computer"}, {"hanzi": "精确计算", "en": "calculate precisely / exact computation"}, {"hanzi": "计算成本", "en": "calculate costs"}, {"hanzi": "云计算", "en": "cloud computing"}, {"hanzi": "计算能力", "en": "computing power / computational capability"}, {"hanzi": "计算结果", "en": "calculation result"}], "idioms": [{"hanzi": "精打细算", "pinyin": "jīng dǎ xì suàn", "meaning_en": "careful calculation and strict budgeting; meticulous planning"}, {"hanzi": "神机妙算", "pinyin": "shén jī miào suàn", "meaning_en": "miraculous calculation and ingenious reckoning; prescient planning"}, {"hanzi": "算无遗策", "pinyin": "suàn wú yí cè", "meaning_en": "never fail in one's calculations; plans foolproof"}, {"hanzi": "失算", "pinyin": "shī suàn", "meaning_en": "miscalculate; misjudge"}], "character_decomposition": [{"character": "计", "pinyin": "jì", "meaning_en": "count; calculate; plan; meter", "meaning_es": "contar; calcular; plan; medidor", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken numbers counted) + 十 (ten / base-10 completeness)", "sound_component": "计 (jì)", "stroke_count": "4", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken words 讠 counting numbers up to ten 十 in the decimal system; signifies counting, tallying, calculating, and planning.", "visual_mnemonic_story_en": "A clerk speaks numbers (讠) counting neatly up to ten (十) to reckon accounts (计).", "visual_mnemonic_story_es": "Un contable recita números (讠) sumando hasta diez (十) para cuadrar cuentas (计).", "tone_mnemonic_anchor": "51", "cangjie": "IVJ", "traditional": "計"}, {"character": "算", "pinyin": "suàn", "meaning_en": "calculate; reckon; count; plan; consider", "meaning_es": "calcular; contar; planear; considerar", "radical": "竹", "radical_meaning_en": "bamboo", "meaning_component": "竹 (bamboo counting rods) + 具/廾 (hands holding rods)", "sound_component": "算 (suàn)", "stroke_count": "14", "composition_type": "上下结构", "etymology_and_mnemonic": "Two hands 廾 manipulating bamboo counting rods 竹 atop an abacus frame; denotes arithmetic calculation and mathematical reckoning.", "visual_mnemonic_story_en": "Two hands (廾) manipulate bamboo counting sticks (竹) across an abacus frame to calculate (算).", "visual_mnemonic_story_es": "Dos manos (廾) mueven varillas de bambú (竹) sobre el tablero del ábaco para calcular (算).", "tone_mnemonic_anchor": "51", "cangjie": "HBUD", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代数学家祖冲之凭借惊人的坚韧毅力，利用数千根简陋的竹制算筹在地上日夜演算，在世界上首次将圆周率精细计算到小数点后第七位。这项领先世界近千年的卓越数学计算成就，在人类科技史上铸就了永恒丰碑。", "pinyin": "Zhōngguó gǔdài shùxuéjiā Zǔ Chōngzhī píngjiè jīngrén de jiānrèn yìlì, lìyòng shùqiān gēn jiǎnlòu de zhúzhì suànchóu zài dìshang rìyè yǎnsuàn, zài shìjiè shàng shǒucì jiāng yuánzhōulǜ jīngxì jìsuàn dào xiǎoshùdiǎn hòu dì-qī wèi. Zhè xiàng lǐngxiān shìjiè jìn qiān nián de zhuóyuè shùxué jìsuàn chéngjiù, zài rénlèi kējì shǐ shàng zhùjiù le yǒnghéng fēngbēi.", "en": "Ancient mathematician Zu Chongzhi, calculating with thousands of bamboo rods, first determined Pi to seven decimal places. Leading the world for nearly a millennium, this outstanding calculation remains a monument in science.", "es": "El matemático antiguo Zu Chongzhi, con miles de varillas de bambú, calculó por primera vez el número Pi hasta siete decimales. Su proeza computacional, adelantada casi un milenio al mundo, es un hito de la ciencia."}, {"id": "#2", "hanzi": "在人工智能与量子计算浪潮席卷全球的今天，强大的算力已成为衡量国家综合科研实力的战略支柱。量子计算机凭借颠覆性的量子叠加与纠缠特性，展现出指数级飞跃的计算速度，将彻底重塑药物研发与气象预测格局。", "pinyin": "Zài réngōng zhìnéng yǔ liàngzǐ jìsuàn làngcháo xíjuǎn quánqiú de jīntiān, qiángdà de suànlì yǐ chéngwéi héngliáng guójiā zōnghé kēyán shílì de zhànlüè zhīzhù. Liàngzǐ jìsuànjī píngjiè diānfùxìng de liàngzǐ diéjiā yǔ jiūchán tèxìng, zhǎnxiàn chū zhǐshùjí fēiyuè de jìsuàn sùdù, jiāng chèdǐ chóngsù yàowù yánfā yǔ qìxiàng yùcè géjú.", "en": "In the era of AI and quantum computing, computational power is a strategic pillar of national science strength. Harnessing quantum superposition, quantum computers show exponential leap in speeds, reshaping drug discovery.", "es": "En la era de la inteligencia artificial y la computación cuántica, la potencia de cálculo es pilar estratégico nacional. Con el entrelazamiento cuántico, los nuevos ordenadores multiplican su velocidad transformando la ciencia médica."}]}, {"meanings_summary": {"en": "quite; considerably; equivalent to; to match; to balance", "es": "bastante; considerablemente; equivalente a; equiparable; equivaler"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Mutual inspection (相) reveals equal balanced value (当), meaning 'equivalent to' or 'quite' (相当).", "composite_memory_hook_es": "La mirada mutua (相) comprueba un peso equilibrado (当) significando equivalente o bastante (相当).", "cultural_and_cognitive_roots": "Metrology and barter trade: balancing equal goods on scale pans (相当: counterpart equivalence), which generalized adverbially to indicate considerable degree.", "tone_sandhi_and_pitch_modulation": "Double level high first tones: 'xiāng dāng' (55-55). Hold level high pitch 55 steadily across both syllables."}, "semantic_boundary_contrasts": {"core_nuance": "相当 functions adverbially expressing a notable degree ('quite / rather') or verbally expressing equivalence ('equal to').", "contrasts": [{"id": "1", "compared_word": "相当 vs. 挺", "pinyin": "tǐng", "analysis": "挺 is colloquial spoken Chinese ('挺好的'), while 相当 has higher formality suitable for written reports and analytical essays ('相当成功')."}, {"id": "2", "compared_word": "相当 vs. 非常", "pinyin": "fēicháng", "analysis": "非常 expresses an absolute superlative degree ('极度 / very'), while 相当 expresses a moderate to high degree ('quite / considerably')."}, {"id": "3", "compared_word": "相当 vs. 等于", "pinyin": "děngyú", "analysis": "等于 is an exact mathematical equals sign (1+1=2), whereas 相当于 means equivalent in weight, value, or metaphoric significance."}]}, "traps_and_cognates": {"look_alikes": [{"character": "想", "pinyin": "xiǎng", "meaning_en": "think", "distinction_note": "Has heart radical 心 underneath 相"}, {"character": "箱", "pinyin": "xiāng", "meaning_en": "chest; trunk", "distinction_note": "Has bamboo radical 竹 atop 相"}, {"character": "党", "pinyin": "dǎng", "meaning_en": "party; clan", "distinction_note": "Has 儿 at bottom instead of 彐 in 当"}, {"character": "光", "pinyin": "guāng", "meaning_en": "light", "distinction_note": "Has 儿 underneath ⺌"}], "etymological_cognates": [{"character": "等", "pinyin": "děng", "gloss_en": "equal bamboo slips"}, {"character": "均", "pinyin": "jūn", "gloss_en": "potter wheel balance; equal"}, {"character": "齐", "pinyin": "qí", "gloss_en": "ears of grain level"}, {"character": "匹", "pinyin": "pǐ", "gloss_en": "equal match; bolt of cloth"}]}, "id": "26", "hanzi": "相当", "pinyin": "xiāng dāng", "level": "HSK 5", "part_of_speech": "Adverb / Verb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "to a considerable degree; quite; fairly; pretty", "definition_es": "en grado notable; bastante; considerablemente", "example_phrase": "相当不错 (pretty good / quite impressive)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to be equal to, equivalent to, or balanced with in proportion or value", "definition_es": "equivaler, corresponder o igualarse en valor o proporción con otra cosa", "example_phrase": "与去年持平或相当 (be equivalent to last year)"}], "example_sentences": [{"id": "#1", "hanzi": "经过长达一年的严格系统训练，这位年轻选手的专业竞技水平已经相当出色了。", "pinyin": "Jīngguò chángdá yì nián de yángé xìtǒng xùnliàn, zhè wèi niánqīng xuǎnshǒu de zhuānyè jìngjì shuǐpíng yǐjīng xiāngdāng chūsè le.", "en": "After a year of rigorous systematic training, this young athlete's professional competitive level is already quite remarkable.", "es": "Tras un año de riguroso entrenamiento sistemático, el nivel competitivo de este joven deportista es ya bastante sobresaliente."}, {"id": "#2", "hanzi": "这处新发现的特大型盐湖锂矿储量极其丰富，其总经济价值相当于一座大型金矿。", "pinyin": "Zhè chù xīnfāxiàn de tàdàxíng yánhú lǐkuàng chǔliàng jíqí fēngfù, qí zǒng jīngjì jiàzhí xiāngdāng yú yí zuò dàxíng jīnkuàng.", "en": "This newly discovered mega salt-lake lithium reserve is rich, its economic value equivalent to that of a major gold mine.", "es": "Las reservas de este megayacimiento de litio en salar son riquísimas, equivaliendo su valor total al de una gran mina de oro."}], "collocations": [{"hanzi": "相当不错", "en": "pretty good; quite nice"}, {"hanzi": "相当于", "en": "equivalent to; equal to"}, {"hanzi": "势均力敌相当", "en": "evenly matched in balance"}, {"hanzi": "相当严重", "en": "quite serious; considerably severe"}, {"hanzi": "旗鼓相当", "en": "well-matched; equal in strength"}, {"hanzi": "水平相当", "en": "on an equal level"}], "idioms": [{"hanzi": "旗鼓相当", "pinyin": "qí gǔ xiāng dāng", "meaning_en": "banners and drums well-matched; equal in force and prowess"}, {"hanzi": "势均力敌", "pinyin": "shì jūn lì dí", "meaning_en": "evenly matched in power and influence"}, {"hanzi": "半斤八两", "pinyin": "bàn jīn bā liǎng", "meaning_en": "six of one and half a dozen of the other; much of a muchness"}, {"hanzi": "相差无几", "pinyin": "xiāng chà wú jǐ", "meaning_en": "almost identical; differing by very little"}], "character_decomposition": [{"character": "相", "pinyin": "xiāng", "meaning_en": "each other; mutually; reciprocal", "meaning_es": "mutuamente; el uno al otro; recíproco", "radical": "木", "radical_meaning_en": "wood / tree", "meaning_component": "木 (tree) + 目 (observing eye gazing at tree)", "sound_component": "相 (xiāng)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "An eye 目 scrutinizing timber 木 up close; denotes inspecting, mutual gazing, and reciprocal relations.", "visual_mnemonic_story_en": "An eye (目) inspects a tree (木) face to face, engaging in mutual appraisal (相).", "visual_mnemonic_story_es": "Un ojo atento (目) contempla un árbol (木) frente a frente en mutuo examen recíproco (相).", "tone_mnemonic_anchor": "55", "cangjie": "DOU", "traditional": ""}, {"character": "当", "pinyin": "dāng", "meaning_en": "bear; serve as; equal; match; when", "meaning_es": "asumir; ejercer de; igualar; corresponder", "radical": "⺌", "radical_meaning_en": "small / top", "meaning_component": "尚 (high / value) + 田 (fertile land value)", "sound_component": "当 (dāng)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Equal value of agricultural land 田 matched in valuation 尚; signifies balancing, matching, serving as, or corresponding to.", "visual_mnemonic_story_en": "Fields (田) balanced evenly on scales correspond in equal value (当).", "visual_mnemonic_story_es": "Campos de cultivo (田) pesados en la balanza igualan su valor recíproco (当).", "tone_mnemonic_anchor": "55", "cangjie": "FSM", "traditional": "當"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在古代丝绸之路的黄金贸易时代，一匹做工极为精细奢华的中国蜀锦，在罗马帝国市场上能换取等重的纯金，其昂贵程度相当于普通贵族一整座豪华庄园的价值，见证了东西方文明交融的繁荣传奇。", "pinyin": "Zài gǔdài Sīchóuzhīlù de huángjīn màoyì shídài, yì pǐ zuògōng jíwéi jīngxì shēhuá de Zhōngguó shǔjǐn, zài Luómǎ Dìguó shìchǎng shàng néng huànqǔ děngzhòng de chúnjīn, qí ángguì chéngdù xiāngdāng yú pǔtōng guìzú yì zhěng zuò háohuá zhuāngyuán de jiàzhí, jiànzhèng le dōng-xīfāng wénmíng jiāoróng de fánróng chuánqí.", "en": "In the golden age of the Silk Road, a bolt of exquisite Chinese Shu brocade could trade for its weight in pure gold in Rome, its value equivalent to an entire noble estate, witnessing East-West exchange.", "es": "En la era dorada de la Ruta de la Seda, una pieza de fino brocado de Shu se trocaba en Roma por su peso en oro puro, equivaliendo a una villa aristocrática entera en el floreciente comercio euroasiático."}, {"id": "#2", "hanzi": "科研人员在南极冰川钻取的这根深海冰芯样品具有相当高的学术研究价值。通过分析封存在微小冰层气泡中的古大气成分，科学家能够精确还原距今数十万年前地球气候冷暖交替的历史全貌，为预测全球变暖提供依据。", "pinyin": "Kēyán rényuán zài Nánjí bīngchuān zuānqǔ de zhè gēn shēnhǎi bīngxīn yàngpǐn jùyǒu xiāngdāng gāo de xuéshù yánjiū jiàzhí. Tōngguò fēnxī fēngcún zài wēixiǎo bīngcéng qìpào zhōng de gǔdàqì chéngfèn, kēxuéjiā nénggòu jīngquè huányuán jùjīn shùshíwàn nián qián Dìqiú qìhòu lěngnuǎn jiāotì de lìshǐ quánmào, wèi yùcè quánqiú biànnuǎn tígōng yījù.", "en": "The ice core drilled in Antarctica holds considerably high research value. By analyzing ancient atmospheric bubbles sealed in ice layers, scientists reconstruct climate cycles from millennia ago to model global warming.", "es": "El testigo de hielo extraído en la Antártida reviste un valor científico considerable. Analizando burbujas de aire fósil, los climatólogos reconstruyen épocas glaciares milenarias para pronosticar el calentamiento global."}]}, {"meanings_summary": {"en": "to continue; to persist; to last; continuous; sustained", "es": "continuar; durar; prolongarse; persistir; sostenido"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Holding firmly in hand (持) and splicing continuous threads (续) maintains sustained duration (持续).", "composite_memory_hook_es": "Sostener firme en la mano (持) y empalmar hebras sin fin (续) mantiene la continuidad (持续).", "cultural_and_cognitive_roots": "Textile weaving metaphor: splicing silk filament ends (续丝) to maintain ceaseless cloth production; applied modernly to ecological sustainability (可持续发展).", "tone_sandhi_and_pitch_modulation": "Rising second tone followed by falling fourth tone: 'chí xù' (35-51). Rise smoothly on 'chí', then descend firmly on 'xù'."}, "semantic_boundary_contrasts": {"core_nuance": "持续 emphasizes unbroken, sustained temporal progression or economic stability across an uninterrupted duration.", "contrasts": [{"id": "1", "compared_word": "持续 vs. 继续", "pinyin": "jìxù", "analysis": "继续 focuses on resuming an action after an interruption or progressing to the next step ('休息后继续干'), while 持续 means uninterrupted sustaining over a time span ('持续高温三周')."}, {"id": "2", "compared_word": "持续 vs. 连续", "pinyin": "liánxù", "analysis": "连续 emphasizes discrete instances repeated one after another without gap ('连续打了五个电话'), while 持续 modifies continuous ongoing states."}, {"id": "3", "compared_word": "持续 vs. 保持", "pinyin": "bǎochí", "analysis": "保持 is a transitive verb meaning to maintain a state or record ('保持整洁'), while 持续 emphasizes the natural duration itself."}]}, "traps_and_cognates": {"look_alikes": [{"character": "特", "pinyin": "tè", "meaning_en": "special", "distinction_note": "Has cow radical 牜 on left of 寺 instead of hand 扌 in 持"}, {"character": "待", "pinyin": "dài", "meaning_en": "wait; treat", "distinction_note": "Has step radical 彳 on left of 寺"}, {"character": "读", "pinyin": "dú", "meaning_en": "read", "distinction_note": "Has speech radical 讠 on left of 卖 instead of silk 纟 in 续"}, {"character": "渎", "pinyin": "dú", "meaning_en": "ditch; blaspheme", "distinction_note": "Has water radical 氵 on left"}], "etymological_cognates": [{"character": "继", "pinyin": "jì", "gloss_en": "inherit; join silk fibers"}, {"character": "连", "pinyin": "lián", "gloss_en": "chariots connected in line"}, {"character": "久", "pinyin": "jiǔ", "gloss_en": "long duration of time"}, {"character": "恒", "pinyin": "héng", "gloss_en": "constant moon; persistent"}]}, "id": "27", "hanzi": "持续", "pinyin": "chí xù", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to extend without interruption or cessation over a period of time; to sustain", "definition_es": "mantenerse, prolongarse o proseguir sin interrupción en el tiempo; perdurar", "example_phrase": "持续发展 (sustainable development)"}], "example_sentences": [{"id": "#1", "hanzi": "连日来南方地区持续出现高温酷暑天气，多地最高气温突破了历史观测极值。", "pinyin": "Liánrì lái nánfāng dìqū chíxù chūxiàn gāowēn kùshǔ tiānqì, duō dì zuìgāo qìwēn tūpò le lìshǐ guāncè jízhí.", "en": "Over recent days, southern regions have experienced continuous scorching heat, with record temperatures shattered in multiple locations.", "es": "En los últimos días el sur del país ha padecido una persistente ola de calor tórrido, batiéndose récords históricos de temperatura en varias provincias."}, {"id": "#2", "hanzi": "只有坚持走绿色低碳的可持续发展道路，才能为子孙后代留下天蓝地绿水清的美丽家园。", "pinyin": "Zhǐyào jiānchí zǒu lǜsè dītàn de kěchíxù fāzhǎn dàolù, cáinéng wèi zǐsūn-hòudài liúxià tiānlán-dìlǜ-shuǐqīng de měilì jiāyuán.", "en": "Only by adhering to green, low-carbon sustainable development can we bequeath a homeland with blue skies, green earth, and clear waters to posterity.", "es": "Solo perseverando en una senda ecológica de desarrollo sostenible legaremos a las generaciones venideras un hogar de cielos limpios y aguas diáfanas."}], "collocations": [{"hanzi": "持续发展", "en": "sustainable development"}, {"hanzi": "可持续", "en": "sustainable"}, {"hanzi": "持续增长", "en": "sustained growth"}, {"hanzi": "持续时间", "en": "duration; duration time"}, {"hanzi": "持续进行", "en": "continue ongoing"}, {"hanzi": "持续高温", "en": "persistent high temperatures"}], "idioms": [{"hanzi": "持之以恒", "pinyin": "chí zhī yǐ héng", "meaning_en": "persevere relentlessly; persist constantly with constancy"}, {"hanzi": "连绵不断", "pinyin": "lián mián bú duàn", "meaning_en": "continuous without break; unbroken stretch"}, {"hanzi": "经久不衰", "pinyin": "jīng jiǔ bù shuāi", "meaning_en": "endure long without declining; unfailing vigor"}, {"hanzi": "源源不断", "pinyin": "yuán yuán bú duàn", "meaning_en": "steady and continuous flow like a spring"}], "character_decomposition": [{"character": "持", "pinyin": "chí", "meaning_en": "hold; grasp; support; maintain; persist", "meaning_es": "sostener; agarrar; mantener; perseverar", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hand holding firmly) + 寺 (temple court / measure rule)", "sound_component": "寺 (sì, temple / phonetic origin)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "A hand 扌 upholding temple law and justice 寺; signifies firmly grasping, holding, maintaining, and supporting.", "visual_mnemonic_story_en": "A steady hand (扌) holds firm to temple principles (寺), upholding constancy (持).", "visual_mnemonic_story_es": "Una mano firme (扌) sostiene las leyes del templo (寺) perseverando sin desmayo (持).", "tone_mnemonic_anchor": "35", "cangjie": "QGDI", "traditional": ""}, {"character": "续", "pinyin": "xù", "meaning_en": "continue; join; extend; succession", "meaning_es": "continuar; empalmar; enlazar; suceder", "radical": "纟", "radical_meaning_en": "silk", "meaning_component": "纟 (silk thread) + 卖 (sell / continuous exchange)", "sound_component": "卖 (mài / phonetic)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Tying new silk thread ends 纟 onto depleted skeins to keep weaving continuously; represents joining, continuing, and prolonging.", "visual_mnemonic_story_en": "A weaver splices new silk strands (纟) into the loom (卖) to continue uninterrupted (续).", "visual_mnemonic_story_es": "El tejedor empalma nuevas hebras de seda (纟) en el telar (卖) para hilar sin corte (续).", "tone_mnemonic_anchor": "51", "cangjie": "VMJDC", "traditional": "續"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国作为全球第二大经济体，近年来坚定不移践行新发展理念，大力推动经济社会绿色低碳转型。通过持续加大风电、光伏等清洁能源投资布局，不仅实现了能源结构的优化升级，更为全球应对气候变化注入了强大的可持续动能。", "pinyin": "Zhōngguó zuòwéi quánqiú dì-èr dà jīngjìtǐ, jìnniánlái jiāndìng-bùyí jiànxíng xīn fāzhǎn lǐniàn, dàlì tuīdòng jīngjì shèhuì lǜsè dītàn zhuǎnxíng. Tōngguò chíxù jiàdà fēngdiàn, guāngfú děng qīngjié néngyuán tóuzī bùjú, bùjǐn shíxiàn le néngyuán jiégòu de yōuhuà shēngjí, gèng wèi quánqiú yìngduì qìhòu biànhuà zhùrù le qiángdà de kěchíxù dòngnéng.", "en": "As the world's second-largest economy, China embraces green low-carbon transformation. Through sustained investment in wind and solar power, it upgrades its energy mix, injecting sustainable momentum into global climate efforts.", "es": "Como segunda economía mundial, China impulsa la transición verde descarbonizada. Invirtiendo de forma continuada en eólica y fotovoltaica, optimiza su matriz energética aportando un dinamismo sostenible a la lucha climática."}, {"id": "#2", "hanzi": "求知钻研的道路漫长曲折，没有任何捷径可走。要想在学术研究中有所建树，不仅需要敏锐的学术眼光，更依赖于十年如一日持续深耕的专注毅力。唯有耐得住寂寞、持之以恒攻关，才能在厚积薄发中迎来璀璨突破。", "pinyin": "Qiúzhī zuānyán de dàolù màncháng qūzhé, méiyǒu rènhé jiéjìng kě zǒu. Yàoxiǎng zài xuéshù yánjiū zhōng yǒu suǒ jiànshù, bùjǐn xūyào mǐnruì de xuéshù yǎnguāng, gèng yīlài yú shí nián rú yí rì chíxù shēngēng de zhuānzhù yìlì. Wéiyǒu nàidézhu jìmò, chízhīyǐhéng gōngguān, cáinéng zài hòujī-bófā zhōng yínglái cuǐcàn tūpò.", "en": "The path of scholarship is winding with no shortcuts. Success demands academic insight and sustained dedication over decades. Enduring solitude and persevering brings breakthroughs through deep accumulated wisdom.", "es": "La senda del saber no admite atajos. Triunfar en la investigación exige sagacidad y un esfuerzo sostenido año tras año. Quien persevera con paciencia y rigor corona hallazgos fecundos."}]}, {"meanings_summary": {"en": "several; a few; number; figure", "es": "varios; unos cuantos; número; cifra"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Tapping a rod (攵) across grain tallies (娄) reckons several quantities (shù, 数).", "composite_memory_hook_es": "Contar grano con una vara (攵) sobre montones (娄) suma varios días o números (shù, 数).", "cultural_and_cognitive_roots": "Polyphonic root: verbal shǔ (action of counting: 数数), nominal shù (number: 数字), and indefinite numeral shù (several/a few: 数天, 数载).", "tone_sandhi_and_pitch_modulation": "Falling fourth tone when functioning as numeral or noun: 'shù' (51). Drop sharply from pitch 5 to 1."}, "semantic_boundary_contrasts": {"core_nuance": "数 (shù) is a literary and formal indefinite numeral prefix meaning 'several / a few' (数天, 数载).", "contrasts": [{"id": "1", "compared_word": "数 vs. 几", "pinyin": "jǐ", "analysis": "几 is the standard colloquial spoken word for 'a few / several' ('几天', '几个人'), while 数 is literary, written, and dignified ('数日', '数载')."}, {"id": "2", "compared_word": "数 vs. 许多", "pinyin": "xǔduō", "analysis": "许多 indicates an abundant large quantity ('many / a lot of'), while 数 indicates an indefinite modest quantity ('several')."}, {"id": "3", "compared_word": "数 vs. 若干", "pinyin": "ruògān", "analysis": "若干 is an official bureaucratic administrative pronoun meaning 'a certain number of' ('若干规定'), while 数 directly quantifies time and items."}]}, "traps_and_cognates": {"look_alikes": [{"character": "楼", "pinyin": "lóu", "meaning_en": "building; floor", "distinction_note": "Has wood radical 木 on left instead of 娄 and 攵"}, {"character": "搂", "pinyin": "lǒu", "meaning_en": "hug; embrace", "distinction_note": "Has hand radical 扌 on left of 娄"}, {"character": "救", "pinyin": "jiù", "meaning_en": "rescue; save", "distinction_note": "Has 求 on left of 攵 instead of 娄 in 数"}, {"character": "敏", "pinyin": "mǐn", "meaning_en": "agile; sensitive", "distinction_note": "Has 每 on left of 攵"}], "etymological_cognates": [{"character": "几", "pinyin": "jǐ", "gloss_en": "how many; a few"}, {"character": "各", "pinyin": "gè", "gloss_en": "each; various"}, {"character": "量", "pinyin": "liàng", "gloss_en": "measure; quantity"}, {"character": "度", "pinyin": "dù", "gloss_en": "degree; rule measure"}]}, "id": "28", "hanzi": "数", "pinyin": "shù", "level": "HSK 5", "part_of_speech": "Numeral", "senses": [{"sense_number": "1", "part_of_speech": "Numeral", "register": "Standard", "definition_en": "several; a few (indicating an unspecified small quantity, usually greater than two)", "definition_es": "varios; unos cuantos (indica cantidad reducida indeterminada superior a dos)", "example_phrase": "数天 / 数年 (several days / several years)"}], "example_sentences": [{"id": "#1", "hanzi": "这位老科学家在偏僻的大西北戈壁滩默默坚守数十载，为国家核工业发展奉献了青春。", "pinyin": "Zhè wèi lǎo kēxuéjiā zài piānpì de dàxīběi Gēbìtān mòmò jiānshǒu shùshí zǎi, wèi guójiā hégōngyè fāzhǎn fèngxiàn le qīngchūn.", "en": "This veteran scientist quietly persevered for several decades on the remote Gobi desert, dedicating his youth to the nation's nuclear industry.", "es": "Este veterano científico perseveró silencioso durante varias décadas en el remoto desierto de Gobi, consagrando su juventud a la energía nuclear patricia."}, {"id": "#2", "hanzi": "长途跋涉了数天之后，科考队终于穿过茫茫原始密林，抵达了神秘的高原冰川源头。", "pinyin": "Chángtú báshè le shù tiān zhīhòu, kěkǎoduì zhōngyú chuānguò mángmáng yuánshǐ mìlín, dǐdá le shénmì de gāoyuán bīngchuān yuántóu.", "en": "After trekking for several days, the scientific expedition finally traversed dense virgin forests, arriving at the mysterious glacier source.", "es": "Tras varios días de penosa marcha, la expedición cruzó la espesura virgen arribando al misterioso nacimiento del glaciar de alta meseta."}], "collocations": [{"hanzi": "数天", "en": "several days"}, {"hanzi": "数年", "en": "several years"}, {"hanzi": "数十个", "en": "several dozen"}, {"hanzi": "数以万计", "en": "tens of thousands; numbered in tens of thousands"}, {"hanzi": "数月", "en": "several months"}, {"hanzi": "数倍", "en": "several times / several-fold"}], "idioms": [{"hanzi": "数以万计", "pinyin": "shù yǐ wàn jì", "meaning_en": "numbered in the tens of thousands; myriad"}, {"hanzi": "寥寥无几", "pinyin": "liáo liáo wú jǐ", "meaning_en": "very few; sparse and countable on fingers"}, {"hanzi": "不可胜数", "pinyin": "bù kě shèng shǔ", "meaning_en": "too numerous to count; countless"}, {"hanzi": "屈指可数", "pinyin": "qū zhǐ kě shǔ", "meaning_en": "can be counted on the fingers; very few in number"}], "character_decomposition": [{"character": "数", "pinyin": "shù", "meaning_en": "number; several; count; fate", "meaning_es": "número; varios; contar; destino", "radical": "攵", "radical_meaning_en": "tap / action", "meaning_component": "娄 (woman with hair tied / tallying grain) + 攵 (tapping rod counting)", "sound_component": "娄 (lóu / phonetic origin)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "A woman 娄 holding a counting rod 攵 tapping and reckoning grain tallies; signifies counting (shǔ) or mathematical quantity and indefinite numbers (shù).", "visual_mnemonic_story_en": "A hand taps a counting rod (攵) across organized sacks of grain (娄) to reckon several numbers (数).", "visual_mnemonic_story_es": "Una mano maneja la vara de conteo (攵) sobre sacos de grano (娄) para contar varios números (数).", "tone_mnemonic_anchor": "51", "cangjie": "FDOK", "traditional": "數"}], "extended_reading_passages": [{"id": "#1", "hanzi": "漫长数载的光阴弹指一挥间，当年偏僻荒凉的南海小渔村，在改革开放的浩荡春风中化作了高楼林立、充满创新活力的现代化国际大都市。数以万计怀揣梦想的奋斗者汇聚于此，谱写出震撼人心的时代奇迹。", "pinyin": "Màncháng shù zǎi de guāngyīn tánzhǐ-yīhuī jiān, dāngnián piānpì huāngliáng de Nánhǎi xiǎoyúcūn, zài gǎigé-kāifàng de hàodàng chūnfēng zhōng huàzuò le gāolóu-línlì, chōngmǎn chuàngxīn huólì de xiàndàihuà guójì dàdūshì. Shùyǐwànjì huáichuāi mèngxiǎng de fèndǒuzhě huìjù yúcǐ, pǔxiě chū zhènhàn-rénxīn de shídài qíjì.", "en": "In several years, a once-barren fishing hamlet transformed into a towering modern metropolis under reform winds. Tens of thousands of dreamers gathered here, composing a moving miracle of the era.", "es": "En unos cuantos decenios, una modesta aldea pesquera se convirtió en una deslumbrante metrópoli cosmopolita. Decenas de miles de soñadores forjaron aquí un milagro contemporáneo sin parangón."}, {"id": "#2", "hanzi": "面对突如其来的全球供应链断裂危机，企业研发团队在数月时间内夜以继日连续攻关。他们试验了数百种替代原材料与数十套算法架构，终于彻底突破卡脖子技术瓶颈，确保了关键设备生产线的平稳运转。", "pinyin": "Miànduì tūrúqílái de quánqiú gōngyìngliàn duànliè wēijī, qǐyè yánfā tuánduì zài shù yuè shíjiān nèi yèyǐjìrì liánxù gōngjiān. Tāmen shìyàn le shùbǎi zhǒng tìdài yuáncáiliào yǔ shùshí tào suànfǎ jiàgòu, zhōngyú chèdǐ tūpò qiǎbózi jìshù píngjǐng, quèbǎo le guānjiàn shèbèi shēngchǎnxiàn de píngwěn yùnzhuǎn.", "en": "Facing global supply chain disruptions, the R&D team worked day and night over several months. Testing hundreds of materials and dozens of algorithms, they broke technological bottlenecks to secure production.", "es": "Ante la rotura de suministros mundiales, ingenieros investigaron día y noche durante varios meses. Ensayando cientos de materiales y decenas de algoritmos, vencieron el cuello de botella garantizando la producción."}]}, {"meanings_summary": {"en": "to lead to; to cause; to bring about; to result in", "es": "conducir a; provocar; causar; desembocar en; originar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Guiding a course (导) until it hits the final destination (致) leads to an adverse outcome (导致).", "composite_memory_hook_es": "Canalizar los hechos (导) hasta que dan en el blanco final (致) provoca o acarrea un resultado (导致).", "cultural_and_cognitive_roots": "Causal grammar constraint: 导 (channeling trajectory) + 致 (final arrival); in modern syntax, strictly polarizes toward adverse or undesirable results.", "tone_sandhi_and_pitch_modulation": "Dipping third tone followed by falling fourth tone: 'dǎo zhì' (214-51). Dip down on 'dǎo', then strike down firmly on 'zhì'."}, "semantic_boundary_contrasts": {"core_nuance": "导致 strictly introduces negative, unwanted, or harmful consequences (diseases, accidents, failures, losses).", "contrasts": [{"id": "1", "compared_word": "导致 vs. 引起", "pinyin": "yǐnqǐ", "analysis": "引起 can introduce positive, neutral, or negative reactions ('引起关注', '引起共鸣'), while 导致 is almost exclusively negative ('导致破产')."}, {"id": "2", "compared_word": "导致 vs. 造成", "pinyin": "zàochéng", "analysis": "造成 emphasizes creating a tangible adverse state or loss ('造成经济损失', '造成人员伤亡'), largely interchangeable with 导致."}, {"id": "3", "compared_word": "导致 vs. 致使", "pinyin": "zhìshǐ", "analysis": "致使 is more literary and formal, common in legal verdicts and forensic police accident reports, while 导致 is standard in all prose."}]}, "traps_and_cognates": {"look_alikes": [{"character": "寻", "pinyin": "xún", "meaning_en": "seek", "distinction_note": "Has 彐 on top of 寸 instead of 巳 in 导"}, {"character": "异", "pinyin": "yì", "meaning_en": "different", "distinction_note": "Has 廾 underneath 巳"}, {"character": "到", "pinyin": "dào", "meaning_en": "arrive", "distinction_note": "Has knife radical 刂 on right of 至 instead of 攵 in 致"}, {"character": "敌", "pinyin": "dí", "meaning_en": "enemy", "distinction_note": "Has 舌 on left of 攵 instead of 至"}], "etymological_cognates": [{"character": "引", "pinyin": "yǐn", "gloss_en": "draw bow; trigger"}, {"character": "起", "pinyin": "qǐ", "gloss_en": "rise; originate"}, {"character": "成", "pinyin": "chéng", "gloss_en": "become; result in"}, {"character": "致", "pinyin": "zhì", "gloss_en": "reach terminal result"}]}, "id": "29", "hanzi": "导致", "pinyin": "dǎo zhì", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cause, bring about, or result in (almost exclusively introducing negative, undesirable, or adverse outcomes)", "definition_es": "provocar, acarrear o desembocar en (casi siempre introduciendo consecuencias adversas o desfavorables)", "example_phrase": "导致严重后果 (lead to serious consequences)"}], "example_sentences": [{"id": "#1", "hanzi": "由于施工人员严重违反安全操作规程，最终导致了这起性质恶劣的特大火灾事故。", "pinyin": "Yóuyú shīgōng rényuán yánzhòng wéifǎn ānquán cāozuò guīchéng, zuìzhōng dǎozhì le zhè qǐ xìngzhì èliè de tàdà huǒzāi shìgù.", "en": "Because construction workers seriously violated safety regulations, it ultimately led to this egregious major fire disaster.", "es": "Por infringir gravemente los protocolos de seguridad los operarios, se produjo este terrible siniestro con consecuencias devastadoras."}, {"id": "#2", "hanzi": "长期处于严重睡眠不足与高压紧绷状态，容易导致人体自主神经功能紊乱与记忆力衰退。", "pinyin": "Chángqī chǔyú yánzhòng shuìmián bùzú yǔ gāoyā jǐnbēng zhuàngtài, róngyì dǎozhì réntǐ zìzhǔ shénjīng gōngnéng wěnluàn yǔ jìyìlì shuāituì.", "en": "Prolonged severe sleep deprivation and high-stress tension easily lead to autonomic nervous system dysfunction and memory decline.", "es": "La falta crónica de descanso y el estrés continuo conducen al desajuste del sistema nervioso autónomo y al deterioro de la memoria."}], "collocations": [{"hanzi": "导致失败", "en": "lead to failure"}, {"hanzi": "导致严重后果", "en": "result in serious consequences"}, {"hanzi": "导致事故", "en": "cause an accident"}, {"hanzi": "直接导致", "en": "directly lead to"}, {"hanzi": "可能导致", "en": "may lead to; potentially cause"}, {"hanzi": "导致疾病", "en": "cause illness/disease"}], "idioms": [{"hanzi": "自食其果", "pinyin": "zì shí qí guǒ", "meaning_en": "reap what one has sown; eat the bitter fruit of one's own making"}, {"hanzi": "玩火自焚", "pinyin": "wán huǒ zì fén", "meaning_en": "play with fire and burn oneself; court disaster"}, {"hanzi": "前因后果", "pinyin": "qián yīn hòu guǒ", "meaning_en": "antecedents and consequences; causes and effects"}, {"hanzi": "因小失大", "pinyin": "yīn xiǎo shī dà", "meaning_en": "lose big because of petty greed; penny wise pound foolish"}], "character_decomposition": [{"character": "导", "pinyin": "dǎo", "meaning_en": "lead; guide; conduct; direct", "meaning_es": "guiar; conducir; canalizar; dirigir", "radical": "寸", "radical_meaning_en": "inch / hand measure", "meaning_component": "巳 (offspring / river channel) + 寸 (hand guiding way)", "sound_component": "道 (dào, path / phonetic origin)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "A hand 寸 pointing out the path 道; guiding movement along a channel, leading to a consequence.", "visual_mnemonic_story_en": "A hand (寸) points the channel ahead, leading (导) events toward their result.", "visual_mnemonic_story_es": "Una mano (寸) canaliza la ruta orientando (导) los hechos hacia su desenlace.", "tone_mnemonic_anchor": "214", "cangjie": "RDI", "traditional": "導"}, {"character": "致", "pinyin": "zhì", "meaning_en": "send; deliver; arrive; cause; delicate", "meaning_es": "entregar; llegar; provocar; delicado; causar", "radical": "至", "radical_meaning_en": "arrive", "meaning_component": "至 (arrow hitting ground / arrival) + 攵 (gentle tapping hand)", "sound_component": "至 (zhì, arrive / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "An arrow arriving at its final ground target 至 guided by a hand 攵; represents bringing about, sending, or arriving at a terminus.", "visual_mnemonic_story_en": "An arrow reaches its final mark (至) propelled by hand (攵), causing completion (致).", "visual_mnemonic_story_es": "Una flecha hace diana al llegar (至) impulsada por la mano (攵), consumando el efecto (致).", "tone_mnemonic_anchor": "51", "cangjie": "MGOIK", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "全球气候变暖引发的极端天气频发，直接导致了部分沿海低洼岛国面临被上升海平面淹没的严峻生存威胁。极端干旱与洪涝灾害更导致大面积粮食作物减产，进一步加剧了全球范围内的饥饿与地缘动荡危机。", "pinyin": "Quánqiú qìhòu biànnuǎn yǐnfā de jíduān tiānqì pínfā, zhíjiē dǎozhì le bùfen yánhǎi dīwā dǎoguó miànlín bèi shàngshēng hǎipíngmiàn yānmò de yánjùn shēngcún wēixié. Jíduān gānhàn yǔ hónglào zāihài gèng dǎozhì dàmiànjī liángshi zuòwù jiǎnchǎn, jìnyíbù jiājù le quánqiú fànwéi nèi de jī'è yǔ dìyuán dòngdàng wēijī.", "en": "Climate change triggers extreme weather, leading low-lying island states to face threats of rising seas. Droughts and floods also lead to major crop reductions, exacerbating hunger and geopolitical unrest.", "es": "El cambio climático provoca anomalías meteorológicas que conducen a la sumersión de atolones por el mar. Sequías y riadas acarrean la ruina de cosechas agravando el hambre y la inestabilidad internacional."}, {"id": "#2", "hanzi": "盲目贪大求全、盲目举债扩张，是许多昔日辉煌的大型企业最终走向资金链断裂、轰然倒闭的核心主因。缺乏敬畏市场规律的盲目决策，必然导致资产负债率居高不下，最终在金融风暴来临时难逃破产厄运。", "pinyin": "Mángmù tāndà-qiúquán, mángmù jǔzhài kuòzhāng, shì xǔduō xīrì huīhuáng de dàxíng qǐyè zuìzhōng zǒuxiàng zījīnliàn duànliè, hōngrán dǎobì de héxīn zhǔyīn. Quēfá jìngwèi shìchǎng guīlǜ de mángmù juécè, bìrán dǎozhì zīchǎn-fùzhàilǜ jūgāobùxià, zuìzhōng zài jīnróng fēngbào láilín shí nántáo pòchǎn èyùn.", "en": "Reckless borrowing and overexpansion are key factors leading once-glorious firms into liquidity defaults and collapse. Disregarding market rules inevitably leads to sky-high debt ratios, courting bankruptcy during storms.", "es": "Endeudarse a ciegas para expandirse condujo a la quiebra a consorcios antes boyantes. Desoír las leyes del mercado acarrea un endeudamiento insostenible que naufraga en la bancarrota al estallar crisis financieras."}]}, {"meanings_summary": {"en": "to suffer from insomnia; sleeplessness; insomnia", "es": "padecer insomnio; no poder dormir; insomnio"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Losing (失) the ability to close eyes in peaceful sleep (眠) results in insomnia (失眠).", "composite_memory_hook_es": "Perder (失) la facultad de cerrar los ojos al plácido sueño (眠) es el insomnio (失眠).", "cultural_and_cognitive_roots": "Traditional Chinese medicine (中医神志学: 阳不入阴 / yang failing to enter yin); sleep represents restoring vital spirit (安神定志).", "tone_sandhi_and_pitch_modulation": "Level high tone followed by rising second tone: 'shī mián' (55-35). Hold high pitch 55 on 'shī', then climb upward smoothly on 'mián'."}, "semantic_boundary_contrasts": {"core_nuance": "失眠 specifically designates the clinical condition or sleepless experience of inability to sleep.", "contrasts": [{"id": "1", "compared_word": "失眠 vs. 熬夜", "pinyin": "áoyè", "analysis": "熬夜 is voluntary staying up late to study, party, or work overtime, while 失眠 is the involuntary, painful inability to fall asleep in bed."}, {"id": "2", "compared_word": "失眠 vs. 睡不着", "pinyin": "shuìbùzháo", "analysis": "睡不着 is an everyday colloquial spoken phrase ('我今晚睡不着'), whereas 失眠 is a formal medical noun and verb."}, {"id": "3", "compared_word": "失眠 vs. 困倦", "pinyin": "kùnjuàn", "analysis": "困倦 describes feeling drowsy and weary with heavy eyelids, while 失眠 is inability to obtain sleep."}]}, "traps_and_cognates": {"look_alikes": [{"character": "矢", "pinyin": "shǐ", "meaning_en": "arrow; vow", "distinction_note": "Top stroke does not cross the horizontal stroke, unlike 失"}, {"character": "夫", "pinyin": "fū", "meaning_en": "man; husband", "distinction_note": "Has straight horizontal top stroke"}, {"character": "眼", "pinyin": "yǎn", "meaning_en": "eye", "distinction_note": "Has 艮 on right of 目 instead of 民 in 眠"}, {"character": "睛", "pinyin": "jīng", "meaning_en": "eyeball", "distinction_note": "Has 青 on right of 目"}], "etymological_cognates": [{"character": "睡", "pinyin": "shuì", "gloss_en": "drooping eyes in sleep"}, {"character": "寐", "pinyin": "mèi", "gloss_en": "sleep soundly under roof"}, {"character": "醒", "pinyin": "xǐng", "gloss_en": "wake from slumber/wine"}, {"character": "梦", "pinyin": "mèng", "gloss_en": "dream while asleep"}]}, "id": "30", "hanzi": "失眠", "pinyin": "shī mián", "level": "HSK 5", "part_of_speech": "Verb / Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to be unable to fall asleep or remain asleep throughout the night; to suffer insomnia", "definition_es": "ser incapaz de conciliar o mantener el sueño durante la noche; desvelarse", "example_phrase": "彻夜失眠 (suffer sleeplessness all night long)"}], "example_sentences": [{"id": "#1", "hanzi": "明天就要迎来期待已久的博士论文答辩，他躺在床上辗转反侧，竟然失眠了整整大半夜。", "pinyin": "Míngtiān jiùyào yínglái qīdài yǐ jiǔ de bóshì lùnwén dábiàn, tā tǎng zài chuáng shàng zhǎnzhuǎn-fǎncè, jìngrán shīmián le zhěngzhěng dàbànyè.", "en": "With tomorrow's long-awaited doctoral defense approaching, he tossed and turned in bed, suffering insomnia for half the night.", "es": "Ante la inminente defensa de su tesis doctoral, dio vueltas en la cama desvelado durante más de media noche."}, {"id": "#2", "hanzi": "长期慢性失眠不仅会加速容颜衰老，更会导致人体免疫细胞活性大幅下降，诱发多种慢性疾病。", "pinyin": "Chángqī mànxìng shīmián bùjǐn huì jiāsù róngyán shuāilǎo, gèng huì dǎozhì réntǐ miǎnyì xìbāo huóxìng dàfú xiàjiàng, yòufā duō zhǒng mànxìng jíbìng.", "en": "Chronic long-term insomnia not only accelerates skin aging, but also causes significant drops in immune cell activity, inducing chronic diseases.", "es": "El insomnio crónico no solo envejece el semblante, sino que deprime las defensas inmunitarias propiciando dolencias crónicas."}], "collocations": [{"hanzi": "慢性失眠", "en": "chronic insomnia"}, {"hanzi": "经常失眠", "en": "frequently suffer from insomnia"}, {"hanzi": "严重失眠", "en": "severe insomnia"}, {"hanzi": "彻夜失眠", "en": "sleepless all night"}, {"hanzi": "引起失眠", "en": "cause insomnia"}, {"hanzi": "治疗失眠", "en": "treat insomnia"}], "idioms": [{"hanzi": "辗转反侧", "pinyin": "zhǎn zhuǎn fǎn cè", "meaning_en": "toss and turn restlessly in bed unable to sleep"}, {"hanzi": "彻夜难眠", "pinyin": "chè yè nán mián", "meaning_en": "unable to fall asleep all night through"}, {"hanzi": "夜不能寐", "pinyin": "yè bù néng mèi", "meaning_en": "unable to sleep at night due to worries"}, {"hanzi": "高枕无忧", "pinyin": "gāo zhěn wú yōu", "meaning_en": "sleep soundly on a high pillow; free from all worries"}], "character_decomposition": [{"character": "失", "pinyin": "shī", "meaning_en": "lose; miss; fail; mistake", "meaning_es": "perder; dejar escapar; fallar; error", "radical": "大", "radical_meaning_en": "big", "meaning_component": "手 (hand) + 一 (object slipping away from grasp)", "sound_component": "失 (shī)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A hand 手 dropping an object that slips through fingers 一; signifies losing, slipping away, or missing.", "visual_mnemonic_story_en": "A hand opens and an object slips away through the fingers, lost (失).", "visual_mnemonic_story_es": "Una mano se abre y un objeto resbala de entre los dedos perdiéndose (失).", "tone_mnemonic_anchor": "55", "cangjie": "HQO", "traditional": ""}, {"character": "眠", "pinyin": "mián", "meaning_en": "sleep; close eyes; dormant", "meaning_es": "dormir; cerrar ojos; letargo", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "目 (eye closing shut) + 民 (blinded eye / sleep)", "sound_component": "民 (mín, people / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Eye radical 目 paired with 民 (eyes closed in blindness/slumber); closing one's eyelids in peaceful sleep or hibernation.", "visual_mnemonic_story_en": "Eyelids (目) close softly shut as a person falls peacefully into deep sleep (眠).", "visual_mnemonic_story_es": "Los párpados (目) se cierran mansos cuando el durmiente concilia el sueño (眠).", "tone_mnemonic_anchor": "35", "cangjie": "BURVP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "漫漫长夜里，许多失眠者越是强迫自己尽快入睡，大脑皮层反而愈发兴奋清醒。心理医生建议，遇到辗转反侧失眠时，不必强赖在床上苦苦熬煎，不妨起身坐在柔和灯光下翻阅几页晦涩书卷，困意往往会在不经意间悄然降临。", "pinyin": "Mànmàn chángyè lǐ, xǔduō shīmiánzhě yuèshì qiǎngpò zìjǐ jǐnkuài rùshuì, dànǎo pícéng fǎn'ér yùfā xīngfèn qīngxǐng. Xīnlǐ yīshēng jiànyì, yùdào zhǎnzhuǎn-fǎncè shīmián shí, búbì qiáng lài zài chuáng shàng kǔkǔ áojiān, bùfáng qǐshēn zuò zài róuhé dēngguāng xià fānyuè jǐ yè huìsè shūjuǎn, kùnyì wǎngwǎng huì zài bùjīngyì jiān qiǎorán jiànglín.", "en": "In the dead of night, the more insomniacs force sleep, the more alert the brain becomes. Therapists suggest leaving bed to read under dim light rather than tossing restlessly; drowsiness soon arrives unbidden.", "es": "En la noche en vela, cuanto más se empeña el insomne en dormir, más se excita la corteza cerebral. Psiquiatras aconsejan levantarse a hojear un libro bajo luz tenue; el sueño vendrá por sí solo sin forzarlo."}, {"id": "#2", "hanzi": "现代都市人失眠的主要诱因之一，是睡前长时间近距离刷短视频或打电子游戏。手机屏幕发射的强烈高频蓝光会抑制松果体分泌褪黑素，从而扰乱正常的昼夜生理节律，导致入睡困难与睡眠浅碎易醒。", "pinyin": "Xiàndài dūshìrén shīmián de zhǔyào yòuyīn zhīyī, shì shuìqián cháng shíjiān jìn jùlí shuā duǎnshìpín huò dǎ diànzǐ yóuxì. Shǒujī píngmù fāshè de qiángliè gāopín lánguāng huì yìzhì sōngguǒtǐ fēnmì tuìhēisù, cóng'ér rǎoluàn zhèngcháng de zhòuyè shēnglǐ jiélǜ, dǎozhì rùshuì kùnnán yǔ shuìmián qiǎnsuì yìxǐng.", "en": "A major trigger of modern urban insomnia is scrolling videos or gaming before bed. High-frequency blue light emitted by phone screens inhibits pineal melatonin, disrupting circadian rhythms and causing light, fragmented sleep.", "es": "Un detonante del insomnio actual es mirar pantallas antes de acostarse. La luz azulada de los móviles inhibe la melatonina en la glándula pineal, quebrando el ritmo circadiano y provocando un descanso superficial y entrecortado."}]}, {"meanings_summary": {"en": "spirit; mind; consciousness; energetic; lively", "es": "espíritu; mente; ánimo; enérgico; vivaz; despierto"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The refined quintessence of grain (精) united with divine consciousness (神) constitutes true human spirit and vitality (精神).", "composite_memory_hook_es": "La quintaesencia refinada del cereal (精) unida a la conciencia divina (神) forja el espíritu y vigor humano (精神).", "cultural_and_cognitive_roots": "In traditional Chinese medicine and philosophy, 精 (vital physical essence) and 神 (conscious mental awareness) form the dual foundation of health.", "tone_sandhi_and_pitch_modulation": "First tone followed by second tone: 'jīng shén' (55-35). When used colloquially as an adjective ('真精神'), 'shén' often softens into a light neutral tone."}, "semantic_boundary_contrasts": {"core_nuance": "精神 refers to mental energy, conscious psychological state, or the overarching soul/ideology of an era, while also acting as an adjective for looking lively.", "contrasts": [{"id": "1", "compared_word": "精神 vs. 思想", "pinyin": "sīxiǎng", "analysis": "思想 focuses on intellectual thought, cognitive ideology, or philosophical viewpoints, whereas 精神 denotes psychological vitality, courage, or emotional energy."}, {"id": "2", "compared_word": "精神 vs. 情绪", "pinyin": "qíngxù", "analysis": "情绪 refers to transient psychological mood swings (e.g. happiness, anger, depression), while 精神 reflects overall vitality, morale, or inner spirit."}, {"id": "3", "compared_word": "精神 vs. 活力", "pinyin": "huólì", "analysis": "活力 emphasizes dynamic physical and bodily stamina, whereas 精神 combines psychological alertness with physical vigor."}]}, "traps_and_cognates": {"look_alikes": [{"character": "晴", "pinyin": "qíng", "meaning_en": "sunny; clear", "distinction_note": "Has sun radical 日 on left instead of rice 米 in 精"}, {"character": "清", "pinyin": "qīng", "meaning_en": "clear; clean", "distinction_note": "Has water radical 氵 on left"}, {"character": "绅", "pinyin": "shēn", "meaning_en": "gentry; gentleman", "distinction_note": "Has silk radical 纟 on left instead of altar 礻 in 神"}, {"character": "伸", "pinyin": "shēn", "meaning_en": "stretch; extend", "distinction_note": "Has person radical 亻 on left of 申"}], "etymological_cognates": [{"character": "心", "pinyin": "xīn", "gloss_en": "heart; conscious mind"}, {"character": "气", "pinyin": "qì", "gloss_en": "vital life breath"}, {"character": "志", "pinyin": "zhì", "gloss_en": "will; aspiration"}, {"character": "魂", "pinyin": "hún", "gloss_en": "ethereal soul"}]}, "id": "31", "hanzi": "精神", "pinyin": "jīng shén", "level": "HSK 5", "part_of_speech": "Noun / Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "spirit, mind, mental state, or conscious psychological vitality", "definition_es": "espíritu, mente, estado anímico o vitalidad psíquica", "example_phrase": "精神饱满 (full of vitality / energetic in spirit)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "vigorous, spirited, lively, looking smart and energetic", "definition_es": "despierto, vivaz, lozano o con aspecto saludable y enérgico", "example_phrase": "小伙子很精神 (the young man looks very sharp and lively)"}], "example_sentences": [{"id": "#1", "hanzi": "规律的作息与充足的睡眠能够让人每天早晨保持饱满的精神状态，显著提高学习和工作效率。", "pinyin": "Guīlǜ de zuòxī yǔ chōngzú de shuìmián nénggòu ràng rén měitiān zǎochén bǎochí bǎomǎn de jīngshén zhuàngtài, xiǎnzhù tígāo xuéxí hé gōngzuò xiàolǜ.", "en": "A regular daily schedule and sufficient sleep enable people to maintain an energetic mental state every morning, significantly boosting study and work efficiency.", "es": "Tener horarios regulares y dormir lo suficiente permite a las personas mantener un ánimo radiante cada mañana, aumentando notablemente la eficiencia."}, {"id": "#2", "hanzi": "这位年轻军官穿上整洁的军装后显得格外精神，步伐坚定而充满自信。", "pinyin": "Zhè wèi niánqīng jūnguān chuānshàng zhěngjié de jūnzhuāng hòu xiǎnde géwài jīngshen, bùfá jiāndìng ér chōngmǎn zìxìn.", "en": "Wearing a crisp uniform, this young military officer looked exceptionally spirited, marching with firm and confident strides.", "es": "Con el pulcro uniforme militar puesto, este joven oficial lucía sumamente apuesto y vivaz, marchando con paso firme y seguro."}], "collocations": [{"hanzi": "精神饱满", "en": "full of energy; high-spirited"}, {"hanzi": "精神状态", "en": "mental state; condition"}, {"hanzi": "时代精神", "en": "spirit of the times; zeitgeist"}, {"hanzi": "精神财富", "en": "spiritual wealth; cultural legacy"}, {"hanzi": "提振精神", "en": "boost one's spirits"}, {"hanzi": "精神压力", "en": "mental stress; psychological strain"}], "idioms": [{"hanzi": "精益求精", "pinyin": "jīng yì qiú jīng", "meaning_en": "constantly perfect one's skills; pursue perfection"}, {"hanzi": "聚精会神", "pinyin": "jù jīng huì shén", "meaning_en": "concentrate one's attention; fully focused"}, {"hanzi": "神采奕奕", "pinyin": "shén cǎi yì yì", "meaning_en": "radiant with vigor and high spirits"}, {"hanzi": "心旷神怡", "pinyin": "xīn kuàng shén yí", "meaning_en": "relaxed in mind and joyful in spirit"}], "character_decomposition": [{"character": "精", "pinyin": "jīng", "meaning_en": "essence; pure; refined; spirit; skilled", "meaning_es": "esencia; puro; refinado; espíritu; hábil", "radical": "米", "radical_meaning_en": "rice", "meaning_component": "米 (husked refined white rice) + 青 (pure clear blue/green)", "sound_component": "青 (qīng, clear / phonetic)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Milled white rice 米 refined to perfection with 青 symbolizing pure clear essence; hence the finest core quality.", "visual_mnemonic_story_en": "Polished premium rice grains (米) cleansed to pristine green purity (青) represent essence (精).", "visual_mnemonic_story_es": "Granos de arroz puro (米) seleccionados con frescura vegetal (青) encarnan la quintaesencia (精).", "tone_mnemonic_anchor": "55", "cangjie": "FDQB", "traditional": ""}, {"character": "神", "pinyin": "shén", "meaning_en": "spirit; deity; soul; expression; mind", "meaning_es": "dios; divinidad; espíritu; alma; expresión", "radical": "礻", "radical_meaning_en": "altar / ritual sign", "meaning_component": "礻 (ancestral altar / spiritual revelation) + 申 (lightning bolts / stretch)", "sound_component": "申 (shēn, stretch / phonetic)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Altar sign 礻 paired with 申 depicting celestial lightning bolts descending from heaven; divinity and invisible soul power.", "visual_mnemonic_story_en": "At a sacred altar (礻), lightning flashes in the sky (申), manifesting divine spirit (神).", "visual_mnemonic_story_es": "Frente al altar sagrado (礻), un rayo cruza el cielo (申) revelando la presencia del espíritu divino (神).", "tone_mnemonic_anchor": "35", "cangjie": "IFLWL", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "健康的生活方式是滋养充沛精神的基石。在当今节奏飞快的社会中，长期的熬夜与心理重压容易导致精神萎靡。唯有坚持科学锻炼与规律睡眠，才能使人神采飞扬，以最佳状态迎接每日挑战。", "pinyin": "Jiànkāng de shēnghuó fāngshì shì zīyǎng chōngpèi jīngshén de jīshí. Zài dāngjīn jiézòu fēikuài de shèhuì zhōng, chángqī de áoyè yǔ xīnlǐ zhòngyā róngyì dǎozhì jīngshén wěimǐ. Wéiyǒu jiānchí kēxué duànliàn yǔ guīlǜ shuìmián, cáinéng shǐ rén shéncǎi-fēiyáng, yǐ zuìjiā zhuàngtài yíngjiē měirì tiǎozhàn.", "en": "A healthy lifestyle forms the cornerstone for nourishing abundant vitality. In fast-paced modern society, chronic late nights and psychological stress easily cause spiritual exhaustion. Only scientific exercise and regular sleep keep one radiant.", "es": "Un estilo de vida saludable cimienta la vitalidad anímica. En la apresurada sociedad moderna, trasnochar y el estrés psíquico minan el vigor. Solo el ejercicio metódico y el sueño regular nos mantienen radiantes ante los retos diarios."}, {"id": "#2", "hanzi": "中华民族在五千年的历史长河中，铸就了坚忍不拔、自强不息的伟大精神。无论面对自然灾害还是外来挑战，这种深沉的文化精神力量始终激励着亿万儿女团结奋斗，在困境中开拓前行，开创出举世瞩目的繁荣发展奇迹。", "pinyin": "Zhōnghuá mínzú zài wǔqiān nián de lìshǐ chánghé zhōng, zhùjiùle jiānrěn-bùbá, zìqiáng-bùxī de wěidà jīngshén. Wúlùn miànduì zìrán zāihài háishì wàilái tiǎozhàn, zhèzhǒng shēnchén de wénhuà jīngshén lìliang shǐzhōng jīlì zhe yìwàn érnǚ tuánjié fèndòu, zài kùnjìng zhōng kāituò qiánxíng, kāichuàng chū jǔshì zhǔmù de fánróng fāzhǎn qíjī.", "en": "Through five thousand years of history, the Chinese nation has forged an indomitable spirit of self-reliance. Facing natural disasters or hardships, this profound cultural spirit inspires unity and perseverance, creating miracles of development.", "es": "A lo largo de cinco milenios, la nación china forjó un espíritu tenaz de superación constante. Ante adversidades naturales o desafíos, esta honda fuerza espiritual impulsa la unión y el avance perseverante, alumbrando milagros de prosperidad admirados por el mundo."}]}, {"meanings_summary": {"en": "expert; specialist; authority in a professional field", "es": "experto; especialista; perito; autoridad profesional"}, "mnemonics_and_roots": {"composite_memory_hook_en": "One who devotes single-minded focus (专) to master an entire intellectual school or discipline (家) is an expert (专家).", "composite_memory_hook_es": "Quien dedica consagración absoluta (专) a dominar una escuela o rama del saber (家) es un experto (专家).", "cultural_and_cognitive_roots": "In classical Chinese, 家 denotes philosophical schools (e.g. 儒家 Confucianism, 道家 Daoism) and masters of recognized crafts (画家, 作家).", "tone_sandhi_and_pitch_modulation": "Two high level first tones: 'zhuān jiā' (55-55). Maintain steady high melodic ceiling without dropping pitch."}, "semantic_boundary_contrasts": {"core_nuance": "专家 denotes an established specialist or authority with deep technical or academic credentials in a specific discipline.", "contrasts": [{"id": "1", "compared_word": "专家 vs. 学者", "pinyin": "xuézhě", "analysis": "学者 highlights academic and theoretical research in universities/humanities, whereas 专家 encompasses practical engineering, clinical, or technical masters."}, {"id": "2", "compared_word": "专家 vs. 行家", "pinyin": "hángjia", "analysis": "行家 emphasizes practical savvy, trade experience, and knack in a commercial market ('这行里的行家'), while 专家 is more formal and authoritative."}, {"id": "3", "compared_word": "专家 vs. 大师", "pinyin": "dàshī", "analysis": "大师 is an exalted title for pinnacle creative or spiritual giants (e.g. painting, chess), whereas 专家 is a standard professional classification."}]}, "traps_and_cognates": {"look_alikes": [{"character": "传", "pinyin": "chuán", "meaning_en": "pass on; transmit", "distinction_note": "Has person radical 亻 on left of 专"}, {"character": "转", "pinyin": "zhuǎn", "meaning_en": "turn; rotate", "distinction_note": "Has vehicle radical 车 on left of 专"}, {"character": "冢", "pinyin": "zhǒng", "meaning_en": "mound; tomb", "distinction_note": "Has 冖 cover over 豕 with extra stroke, unlike 家"}, {"character": "稼", "pinyin": "jià", "meaning_en": "sow grain; crops", "distinction_note": "Has grain radical 禾 on left of 家"}], "etymological_cognates": [{"character": "师", "pinyin": "shī", "gloss_en": "master; teacher"}, {"character": "匠", "pinyin": "jiàng", "gloss_en": "artisan; craftsman"}, {"character": "工", "pinyin": "gōng", "gloss_en": "work; engineer"}, {"character": "儒", "pinyin": "rú", "gloss_en": "scholar"}]}, "id": "32", "hanzi": "专家", "pinyin": "zhuān jiā", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person who has authoritative, specialized knowledge or skill in a specific technical, medical, scientific, or artistic domain", "definition_es": "persona con profundos conocimientos técnicos, científicos o artísticos en una disciplina concreta", "example_phrase": "医学专家 (medical specialist / authority)"}], "example_sentences": [{"id": "#1", "hanzi": "睡眠医学专家指出，长期依赖刺耳的机械闹钟容易诱发心血管疾病与情绪焦虑。", "pinyin": "Shuìmián yīxué zhuānjiā zhǐchū, chángqī yīlài cì'ěr de jīxiè nàozhōng róngyì yòufā xīnxuěguǎn jíbìng yǔ qíngxù jiāolǜ.", "en": "Sleep medicine experts point out that long-term reliance on jarring mechanical alarms easily triggers cardiovascular problems and emotional anxiety.", "es": "Expertos en medicina del sueño señalan que depender crónicamente de alarmas estridentes provoca dolencias cardiovasculares y ansiedad."}, {"id": "#2", "hanzi": "为了攻克技术难关，研究所特意邀请了多位海外人工智能领域的知名专家前来进行学术指导。", "pinyin": "Wèile gōngkè jìshù nánguān, yánjiūsuǒ tèyì yāoqǐngle duō wèi hǎiwài réngōng zhìnéng lǐngyù de zhīmíng zhuānjiā qiánlái jìnxíng xuéshù zhǐdǎo.", "en": "To overcome technological bottlenecks, the research institute specially invited several renowned overseas AI specialists for academic guidance.", "es": "Para superar escollos técnicos, el instituto invitó expresamente a varios célebres expertos foráneos en inteligencia artificial para asesoramiento."}], "collocations": [{"hanzi": "知名专家", "en": "renowned expert; famous specialist"}, {"hanzi": "特聘专家", "en": "specially appointed expert"}, {"hanzi": "行业专家", "en": "industry expert; trade specialist"}, {"hanzi": "专家学者", "en": "experts and scholars"}, {"hanzi": "专家意见", "en": "expert opinion / advisory advice"}, {"hanzi": "咨询专家", "en": "consult an expert"}], "idioms": [{"hanzi": "行家手笔", "pinyin": "háng jiā shǒu bǐ", "meaning_en": "the master stroke of an expert; professional workmanship"}, {"hanzi": "名家辈出", "pinyin": "míng jiā bèi chū", "meaning_en": "celebrated masters emerging generation after generation"}, {"hanzi": "专心致志", "pinyin": "zhuān xīn zhì zhì", "meaning_en": "wholly devoted and deeply concentrated"}, {"hanzi": "博古通今", "pinyin": "bó gǔ tōng jīn", "meaning_en": "erudite in both ancient lore and modern knowledge"}], "character_decomposition": [{"character": "专", "pinyin": "zhuān", "meaning_en": "specialized; concentrated; exclusive; single-minded", "meaning_es": "especializado; dedicado; concentrado; exclusivo", "radical": "一", "radical_meaning_en": "one", "meaning_component": "A hand 寸 rotating a spindle of spun thread; simplified to focused devotion", "sound_component": "Historical phonetic zhān", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Originally depicting a spinning spindle handled with extreme steady care; transformed to mean single-minded specialized focus.", "visual_mnemonic_story_en": "Focusing every stroke of work exclusively on one single (一) path creates mastery (专).", "visual_mnemonic_story_es": "Concentrar cada trazo en una sola (一) meta constante engendra maestría (专).", "tone_mnemonic_anchor": "55", "cangjie": "QNI", "traditional": "專"}, {"character": "家", "pinyin": "jiā", "meaning_en": "family; home; master; specialist", "meaning_es": "familia; hogar; maestro; especialista de renombre", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (sheltering roof) + 豕 (pig / domestic wealth and family school)", "sound_component": "豕 (shǐ / domestic symbol)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "A roof 宀 with domestic livestock 豕 beneath; extended to denote a prestigious household, scholastic tradition, or distinguished master.", "visual_mnemonic_story_en": "Under the roof (宀) of a scholastic household, a master raises knowledge to become a specialist (家).", "visual_mnemonic_story_es": "Bajo el techo (宀) de la escuela o gremio, el virtuoso se corona maestro consumado (家).", "tone_mnemonic_anchor": "55", "cangjie": "JMO", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "随着现代生活节奏不断加快，大众对健康的关注度日益提升。各大医院的睡眠医学专家建议，睡前一小时尽量远离电子屏幕，营造昏暗安静的卧室氛围，从而利用人体自然的生理机制平稳进入深度睡眠。", "pinyin": "Suízhe xiàndài shēnghuó jiézòu bùduàn jiākuài, dàzhòng duì jiànkāng de guānzhùdù rìyì tíshēng. Gè dà yīyuàn de shuìmián yīxué zhuānjiā jiànyì, shuì qián yī xiǎoshí jǐnliàng yuǎnlí diànzǐ píngmù, yíngzào hūn'àn ānjìng de wòshì fēnwéi, cóng'ér lìyòng réntǐ zìrán de shēnglǐ jīzhì píngwěn jìnrù shēndù shuìmián.", "en": "As modern life speeds up, public attention to health steadily climbs. Sleep medicine experts recommend staying away from electronic screens an hour before bed and creating a dim quiet bedroom atmosphere to smoothly enter deep sleep.", "es": "Con el ritmo de vida moderno acelerándose, el interés por la salud crece. Expertos en medicina del sueño aconsejan alejarse de las pantallas una hora antes de dormir y procurar un dormitorio tenue y silencioso para conciliar el sueño profundo."}, {"id": "#2", "hanzi": "在城市规划与环境保护项目中，政府广泛听取了生态学与地质学专家的科学论证。专家们通过大数据模拟分析，提出了兼顾经济发展与绿水青山的多套建设方案，为城市未来的可持续发展奠定了扎实坚实的科学依据。", "pinyin": "Zài chéngshì guīhuà yǔ huánjìng bǎohù xiàngmù zhōng, zhèngfǔ guǎngfàn tīngqǔle shēngtàixué yǔ dìzhìxué zhuānjiā de kēxué lùnzhèng. Zhuānjiāmen tōngguò dàshùjù mónǐ fēnxī, tíchūle jiāngù jīngjì fāzhǎn yǔ lǜshuǐ-qīngshān de duō tào jiànshè fāng'àn, wèi chéngshì wèilái de kěchíxù fāzhǎn diàndìngle zhāshi jiānshí de kēxué yījù.", "en": "In urban planning and environmental projects, the government widely consulted scientific evaluations from ecological and geological experts. Through big data simulations, specialists proposed balanced plans laying solid scientific ground.", "es": "En planes de urbanismo y medio ambiente, las autoridades recabaron dictámenes de expertos en ecología y geología. Mediante simulaciones de macrodatos, los especialistas formularon proyectos equilibrados para garantizar un desarrollo urbano sostenible."}]}, {"meanings_summary": {"en": "to adopt; employ; apply; introduce (a method, policy, or technology)", "es": "adoptar; emplear; utilizar; aplicar (métodos, criterios o tecnologías)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Selectively plucking the best method (采) and putting it into active practice (用) is adopting it (采用).", "composite_memory_hook_es": "Recolectar y elegir la opción idónea (采) para darle uso práctico (用) es adoptar o aplicar (采用).", "cultural_and_cognitive_roots": "Derived from classical governance and agronomy: selecting (采) proven folk techniques and deploying (用) them across the realm.", "tone_sandhi_and_pitch_modulation": "Third tone followed by fourth tone: 'cǎi yòng' (214-51). Dip low with 214 then drop sharply with 51."}, "semantic_boundary_contrasts": {"core_nuance": "采用 implies selecting a policy, measure, method, standard, or material among alternatives and putting it into implementation.", "contrasts": [{"id": "1", "compared_word": "采用 vs. 使用", "pinyin": "shǐyòng", "analysis": "使用 is generic for operating or using any physical tool, phone, or money ('使用工具'), while 采用 focuses on adopting strategic methods, models, or materials."}, {"id": "2", "compared_word": "采用 vs. 采取", "pinyin": "cǎiqǔ", "analysis": "采取 collocates primarily with abstract actions, stances, or measures ('采取行动', '采取态度'), whereas 采用 emphasizes concrete systems, techniques, or inputs."}, {"id": "3", "compared_word": "采用 vs. 采纳", "pinyin": "cǎinà", "analysis": "采纳 specifically means accepting verbal advice, opinions, or proposals from other people ('采纳建议'), whereas 采用 applies to designs and methods."}]}, "traps_and_cognates": {"look_alikes": [{"character": "彩", "pinyin": "cǎi", "meaning_en": "color; prize; splendor", "distinction_note": "Has hair/pattern radical 彡 on right of 采"}, {"character": "踩", "pinyin": "cǎi", "meaning_en": "step on; trample", "distinction_note": "Has foot radical 足 on left of 采"}, {"character": "甩", "pinyin": "shuǎi", "meaning_en": "swing; fling", "distinction_note": "Bottom stroke bends rightwards like a flicking tail, unlike 用"}, {"character": "角", "pinyin": "jiǎo", "meaning_en": "horn; corner", "distinction_note": "Has knife-like top slant, unlike squared top of 用"}], "etymological_cognates": [{"character": "选", "pinyin": "xuǎn", "gloss_en": "choose; select"}, {"character": "取", "pinyin": "qǔ", "gloss_en": "take; seize"}, {"character": "使", "pinyin": "shǐ", "gloss_en": "use; deploy"}, {"character": "行", "pinyin": "xíng", "gloss_en": "put into action"}]}, "id": "33", "hanzi": "采用", "pinyin": "cǎi yòng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to select and implement or put to use a specific technique, proposal, material, or approach after evaluation", "definition_es": "escoger y poner en práctica una determinada técnica, propuesta, material o política tras evaluar su idoneidad", "example_phrase": "采用新技术 (adopt new technology)"}], "example_sentences": [{"id": "#1", "hanzi": "为了减小对心脏的突发惊吓，很多上班族开始采用模拟日出的光线渐亮闹钟来代替刺耳的铃声。", "pinyin": "Wèile jiǎnxiǎo duì xīnzàng de tūfā jīngxià, hěnduō shàngbānzú kāishǐ cǎiyòng mónǐ rìchū de guāngxiàn jiànliàng nàozhōng lái dàitì cì'ěr de língshēng.", "en": "To lessen sudden fright to the heart, many commuters have begun adopting sunrise-simulating light-gradual alarms instead of harsh bells.", "es": "Para mitigar sobresaltos al corazón, muchos oficinistas comenzaron a adoptar alarmas que simulan el amanecer en vez de timbres estridentes."}, {"id": "#2", "hanzi": "这家环保企业在生产过程中大胆采用可降解材料，极大降低了工业废弃物对自然环境的污染。", "pinyin": "Zhè jiā huánbǎo qǐyè zài shēngchǎn guòchéng zhōng dàdǎn cǎiyòng kějiàngjiě cáiliào, jídà jiàngdīle gōngyè fèiqìwù duì zìrán huánjìng de wūrǎn.", "en": "This eco-friendly enterprise boldly adopted biodegradable materials during production, tremendously reducing industrial waste pollution.", "es": "Esta empresa ecológica adoptó resueltamente materiales biodegradables en su producción, reduciendo con creces los residuos contaminantes."}], "collocations": [{"hanzi": "采用方法", "en": "adopt a method"}, {"hanzi": "采用技术", "en": "apply / employ technology"}, {"hanzi": "采用标准", "en": "adopt a standard"}, {"hanzi": "采用建议", "en": "adopt a recommendation / suggestion"}, {"hanzi": "广泛采用", "en": "widely adopt / employ extensively"}, {"hanzi": "决定采用", "en": "decide to adopt"}], "idioms": [{"hanzi": "采长补短", "pinyin": "cǎi cháng bǔ duǎn", "meaning_en": "adopt others' strengths to make up for one's shortcomings"}, {"hanzi": "兼收并蓄", "pinyin": "jiān shōu bìng xù", "meaning_en": "absorb and assimilate broadly; embrace everything"}, {"hanzi": "物尽其用", "pinyin": "wù jìn qí yòng", "meaning_en": "make the best and fullest use of all materials"}, {"hanzi": "博采众长", "pinyin": "bó cǎi zhòng cháng", "meaning_en": "gather and adopt strengths from many sources"}], "character_decomposition": [{"character": "采", "pinyin": "cǎi", "meaning_en": "pick; pluck; collect; choose", "meaning_es": "recoger; recolectar; seleccionar; escoger", "radical": "爫", "radical_meaning_en": "claw / hand grasping from above", "meaning_component": "爫 (hand reaching down) + 木 (tree branch / fruits)", "sound_component": "Pictographic pluck", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A hand 爫 reaching down to pluck ripe fruit or leaves from a tree 木; picking out and selecting the best.", "visual_mnemonic_story_en": "A hand reaching from above (爫) plucks select ripe fruits from a tree (木) to gather (采).", "visual_mnemonic_story_es": "Una mano descendente (爫) recolecta fruta madura del árbol (木) para escoger lo mejor (采).", "tone_mnemonic_anchor": "214", "cangjie": "BD", "traditional": ""}, {"character": "用", "pinyin": "yòng", "meaning_en": "use; employ; apply; consume", "meaning_es": "usar; emplear; aplicar; utilizar", "radical": "用", "radical_meaning_en": "use", "meaning_component": "Depiction of a divinatory turtle shell pierced with strokes, ready to be utilized in ritual", "sound_component": "Self-phonetic yòng", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "Pictograph of an implement, vessel, or oracle bone being put to active operational use.", "visual_mnemonic_story_en": "A framed tool bucket ready in hand to be put to active functional use (用).", "visual_mnemonic_story_es": "Una herramienta encuadrada dispuesta para prestar servicio y utilidad inmediata (用).", "tone_mnemonic_anchor": "51", "cangjie": "BQI", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代智能制造领域，许多工厂纷纷采用全自动机器人流水线来替代繁重的高危人工岗位。这不仅大幅提升了装配精度与产能，还有效避免了工伤事故的发生，为企业带来了显著的竞争优势。", "pinyin": "Zài xiàndài zhìnéng zhìzào lǐngyù, xǔduō gōngchǎng fēnfēn cǎiyòng quánzìdòng jīqìrén liúshuǐxiàn lái tìdài fánzhòng de gāowēi réngōng gǎngwèi. Zhè bùjǐn dàfú tíshēngle zhuāngpèi jīngdù yǔ chǎnnéng, hái yǒuxiào bìmiǎnle gōngshāng shìgù de fāshēng, wèi qǐyè dàiláile xiǎnzhù de jìngzhēng yōushì.", "en": "In intelligent manufacturing, many factories have adopted fully automated robotic assembly lines to replace hazardous manual posts. This not only elevates precision and capacity but also averts workplace injuries, yielding competitive edge.", "es": "En la fabricación inteligente, múltiples fábricas han adoptado líneas automatizadas de robots en sustitución de labores peligrosas. Ello no solo mejora la precisión y la producción, sino que evita percances laborales, generando ventajas competitivas."}, {"id": "#2", "hanzi": "为了应对全球气候变暖带来的挑战，国际建筑行业正积极采用新型隔热节能材料与自然通风系统。这种绿色低碳设计不仅降低了建筑物夏季制冷的电能消耗，还创造出宜居舒适的室内小气候，深受崇尚环保的现代居民青睐。", "pinyin": "Wèile yìngduì quánqiú qìhòu biànnuǎn dàilái de tiǎozhàn, guójì jiànzhù hángyè zhèng jījí cǎiyòng xīnxíng gérè jiénéng cáiliào yǔ zìrán tōngfēng xìtǒng. Zhèzhǒng lǜsè dītàn shèjì bùjǐn jiàngdīle jiànzhùwù xiàjì zhìlěng de diànnéng xiāohào, hái chuàngzào chū yíjū shūshì de shìnèi xiǎoqìhòu, shēnshòu chóngshàng huánbǎo de xiàndài jūmín qīnglài.", "en": "To combat global warming challenges, international architects actively adopt novel thermal insulation materials and natural ventilation. Such eco-designs decrease cooling power consumption while creating comfortable indoor microclimates favored by residents.", "es": "Ante el reto del calentamiento global, la arquitectura internacional adopta nuevos materiales aislantes y ventilación natural. Estos diseños ecológicos reducen el consumo eléctrico de refrigeración y crean microclimas confortables muy valorados por ciudadanos concienciados."}]}, {"meanings_summary": {"en": "gentle; soft; mild; mellow; soothing (light, voice, tone, texture)", "es": "suave; blando; apacible; tenue; meloso (luz, voz, tono, textura)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Pliant bending softness (柔) paired with balanced soothing harmony (和) yields gentle soothing comfort (柔和).", "composite_memory_hook_es": "La elasticidad blanda (柔) hermanada con la melodiosa armonía (和) da lugar a una textura o luz apacible y suave (柔和).", "cultural_and_cognitive_roots": "Daoist aesthetic principle: softness (柔) endures while brittleness breaks; harmonious moderation (中和) creates timeless elegance.", "tone_sandhi_and_pitch_modulation": "Two rising second tones: 'róu hé' (35-35). Rise cleanly across both syllables smoothly."}, "semantic_boundary_contrasts": {"core_nuance": "柔和 describes sensory qualities (lighting, vocal tone, color, melody) or dispositions that are mellow, non-glaring, and gently pleasing.", "contrasts": [{"id": "1", "compared_word": "柔和 vs. 柔软", "pinyin": "róuruǎn", "analysis": "柔软 specifically describes physical, tactile flexibility and plush softness of touch (e.g. beddings, pillows, wool), whereas 柔和 describes light, sound, and mood."}, {"id": "2", "compared_word": "柔和 vs. 温和", "pinyin": "wēnhé", "analysis": "温和 focuses primarily on personality, climate/temperature, or medicinal effects ('脾气温和', '气候温和'), while 柔和 is strongly tied to optical and acoustic sensations."}, {"id": "3", "compared_word": "柔和 vs. 平和", "pinyin": "pínghé", "analysis": "平和 denotes emotional equanimity, balance, and lack of confrontation ('心态平和'), whereas 柔和 is perceptual soothing softness."}]}, "traps_and_cognates": {"look_alikes": [{"character": "揉", "pinyin": "róu", "meaning_en": "rub; knead", "distinction_note": "Has hand radical 扌 on left of 柔"}, {"character": "桑", "pinyin": "sāng", "meaning_en": "mulberry tree", "distinction_note": "Has three hands 又 over 木, lacking spear 矛"}, {"character": "私", "pinyin": "sī", "meaning_en": "private; selfish", "distinction_note": "Has 厶 on right of 禾 instead of 口 in 和"}, {"character": "利", "pinyin": "lì", "meaning_en": "sharp; profit", "distinction_note": "Has knife radical 刂 on right of 禾"}], "etymological_cognates": [{"character": "温", "pinyin": "wēn", "gloss_en": "warm; mild"}, {"character": "软", "pinyin": "ruǎn", "gloss_en": "soft; pliable"}, {"character": "缓", "pinyin": "huǎn", "gloss_en": "gentle; slow"}, {"character": "顺", "pinyin": "shùn", "gloss_en": "smooth; compliant"}]}, "id": "34", "hanzi": "柔和", "pinyin": "róu hé", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "gentle, mild, and pleasing to the senses without sharpness or glare (of light, color, sound, texture, or temperament)", "definition_es": "suave, tenue, templado o agradable a los sentidos sin estridencias (dícese de luz, voz, color o carácter)", "example_phrase": "柔和的光线 (gentle / diffused light)"}], "example_sentences": [{"id": "#1", "hanzi": "清晨柔和的阳光透过薄窗帘洒在床头，唤醒了沉睡中的身体，让人感到格外舒服惬意。", "pinyin": "Qīngchén róuhé de yángguāng tòuguò báo chuānglián sǎ zài chuángtóu, huànxǐngle chénshuì zhōng de shēntǐ, ràng rén gǎndào géwài shūfu qièyì.", "en": "Gentle morning sunlight filtered through the thin curtains onto the bedside, gently awakening the sleeping body and making one feel exceptionally cozy.", "es": "La tenue luz matinal atravesó el fino visillo sobre la cabecera despertando el cuerpo dormido con una sensación sumamente apacible."}, {"id": "#2", "hanzi": "心理咨询师用柔和而平缓的语调与来访者交谈，帮助他们逐渐放松紧绷的神经。", "pinyin": "Xīnlǐ zīxúnshī yòng róuhé ér pínghuǎn de yǔdiào yǔ láifǎngzhě jiāotán, bāngzhù tāmen zhújiàn fàngsōng jǐnbēng de shénjīng.", "en": "The counselor spoke in a gentle and soothing tone with the visitor, helping them gradually relax their tense nerves.", "es": "El terapeuta conversó con el visitante en un tono suave y sosegado, ayudándole a relajar paso a paso sus tensos nervios."}], "collocations": [{"hanzi": "柔和的光线", "en": "soft / gentle light"}, {"hanzi": "声音柔和", "en": "gentle voice / mellow sound"}, {"hanzi": "色调柔和", "en": "subdued / soft hues"}, {"hanzi": "目光柔和", "en": "gentle gaze / kind eyes"}, {"hanzi": "触感柔和", "en": "soft to the touch"}, {"hanzi": "柔和的音乐", "en": "gentle / soothing music"}], "idioms": [{"hanzi": "以柔克刚", "pinyin": "yǐ róu kè gāng", "meaning_en": "overcome hardness with softness; subdue brute force by gentle means"}, {"hanzi": "和风细雨", "pinyin": "hé fēng xì yǔ", "meaning_en": "gentle breeze and mild rain; patient persuasion"}, {"hanzi": "心平气和", "pinyin": "xīn píng qì hé", "meaning_en": "tranquil mind and even temper; calm and good-humored"}, {"hanzi": "温柔体贴", "pinyin": "wēn róu tǐ tiē", "meaning_en": "gentle, considerate, and deeply tender"}], "character_decomposition": [{"character": "柔", "pinyin": "róu", "meaning_en": "soft; pliable; flexible; gentle", "meaning_es": "blando; flexible; maleable; suave", "radical": "木", "radical_meaning_en": "wood / tree", "meaning_component": "矛 (spear handle bent pliantly) + 木 (pliant tree twig)", "sound_component": "矛 (máo / archaic flex)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "A supple tree branch 木 pliable enough to bend without snapping; flexibility and tender softness.", "visual_mnemonic_story_en": "A slender wooden branch (木) bending gracefully like a spear shaft (矛) displays softness (柔).", "visual_mnemonic_story_es": "La rama tierna del árbol (木) que se comba dócil como asta elástica (矛) personifica la suavidad (柔).", "tone_mnemonic_anchor": "35", "cangjie": "NHD", "traditional": ""}, {"character": "和", "pinyin": "hé", "meaning_en": "harmonious; calm; gentle; peace; and", "meaning_es": "armonioso; apacible; templado; paz; y", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "禾 (grain stalks) + 口 (mouth singing or sharing grain)", "sound_component": "禾 (hé, grain / phonetic harmony)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Mouth 口 fed harmoniously with seasonal grain 禾; symbolizes peaceful consensus, balance, and mild harmony.", "visual_mnemonic_story_en": "Stalks of ripe grain (禾) nourishing every hungry mouth (口) cultivate peaceful harmony (和).", "visual_mnemonic_story_es": "Las espigas de trigo (禾) que colman la boca (口) engendran sosiego, calidez y armonía (和).", "tone_mnemonic_anchor": "35", "cangjie": "HDR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "室内设计师在布置卧室时，通常偏好采用米黄色等柔和的色彩系统。柔和的光线不仅能缓解视网膜的日间疲劳，更能从心理层面上消除戒备与焦虑，引导身心在宁静温馨的氛围中逐步放松。", "pinyin": "Shìnèi shèjìshī zài bùzhì wòshì shí, tōngcháng piānhào cǎiyòng mǐhuángsè děng róuhé de sècǎi xìtǒng. Róuhé de guāngxiàn bùjǐn néng huǎnjiě shìwǎngmó de rìjiān píláo, gèng néng cóng xīnlǐ céngmiàn shàng xiāochú jièbèi yǔ jiāolǜ, yǐndǎo shēnxīn zài níngjìng wēnxīn de fēnwéi zhōng zhúbù fàngsōng.", "en": "Interior designers typically prefer soft color palettes like beige when decorating bedrooms. Soft light not only relieves retinal fatigue accumulated during daytime, but also psychologically diffuses tension, guiding mind and body into calm rest.", "es": "Los interioristas prefieren gamas suaves como el crema al decorar dormitorios. La luz tenue mitiga la fatiga ocular y disipa la ansiedad a nivel psicológico, invitando al cuerpo y la mente a relajarse en una atmósfera acogedora."}, {"id": "#2", "hanzi": "暮色降临时，海滩上的风渐渐平息，晚霞为整片海湾披上了一层柔和的金红色轻纱。散步的人们伴着舒缓的浪花声低语交谈，空气中弥漫着宁静的气息，白日里一切喧嚣与烦恼都在这柔和的黄昏景致中融化消散。", "pinyin": "Mùsè jiànglín shí, hǎitān shàng de fēng jiànjiàn píngxī, wǎnxiá wèi zhěng piàn hǎiwān pīshàngle yī céng róuhé de jīnhóngsè qīngshā. Sànbù de rénmen bànzhe shūhuǎn de lànghuā shēng dīyǔ jiāotán, kōngqì zhōng mímàn zhe níngjìng de qìxī, báirì lǐ yīqiè xuānxiāo yǔ fánnǎo dōu zài zhè róuhé de huánghūn jǐngzhì zhōng rónghuà xiāosàn.", "en": "At dusk, coastal breezes softened, and the sunset cast a gentle veil of gold and crimson over the bay. Strollers whispered along the rhythmic waves, as all daytime hubbub dissolved effortlessly into the soothing twilight landscape.", "es": "Al caer el crepúsculo, la brisa marina amainó y el arrebol cubrió la bahía con un velo suave de tonos dorados y rojizos. Los paseantes conversaban al compás de las olas, desvaneciendo las tribulaciones del día en la quietud de la tarde."}]}, {"meanings_summary": {"en": "wish; desire; aspiration; longing", "es": "deseo; anhelo; aspiración; ilusión"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A deep heart's intent (愿) looking toward distant lunar heights (望) creates an earnest wish (愿望).", "composite_memory_hook_es": "El sincero sentir del corazón (愿) oteando esperanzas lejanas (望) da cuerpo al anhelo o deseo (愿望).", "cultural_and_cognitive_roots": "Derived from the ancient poetic custom of gazing at the full moon (望月) while whispering unspoken prayers for reunion and fortune.", "tone_sandhi_and_pitch_modulation": "Two falling fourth tones: 'yuàn wàng' (51-51). Execute two crisp authoritative drops."}, "semantic_boundary_contrasts": {"core_nuance": "愿望 refers to an inner, cherished hope or subjective yearning for happiness, peace, or personal aspirations.", "contrasts": [{"id": "1", "compared_word": "愿望 vs. 希望", "pinyin": "xīwàng", "analysis": "希望 can act as both verb ('我希望...') and noun ('满怀希望'), whereas 愿望 is predominantly a noun signifying a specific cherished wish."}, {"id": "2", "compared_word": "愿望 vs. 理想", "pinyin": "lǐxiǎng", "analysis": "理想 denotes grand, rational life ambitions and socio-political ideals ('崇高理想'), whereas 愿望 often reflects immediate, personal sentiments."}, {"id": "3", "compared_word": "愿望 vs. 欲望", "pinyin": "yùwàng", "analysis": "欲望 carries a strong appetite, instinctive urge, or acquisitive craving ('金钱欲望'), while 愿望 is benign, positive, and gentle."}]}, "traps_and_cognates": {"look_alikes": [{"character": "原", "pinyin": "yuán", "meaning_en": "origin; meadow", "distinction_note": "Lacks heart radical 心 at bottom of 愿"}, {"character": "怨", "pinyin": "yuàn", "meaning_en": "resentment; blame", "distinction_note": "Has 夗 at top instead of 原"}, {"character": "忘", "pinyin": "wàng", "meaning_en": "forget", "distinction_note": "Has 亡 over 心, lacking moon 月"}, {"character": "妄", "pinyin": "wàng", "meaning_en": "absurd; rash", "distinction_note": "Has 亡 over woman radical 女"}], "etymological_cognates": [{"character": "希", "pinyin": "xī", "gloss_en": "hope; rare"}, {"character": "盼", "pinyin": "pàn", "gloss_en": "look forward to"}, {"character": "祈", "pinyin": "qí", "gloss_en": "pray for"}, {"character": "求", "pinyin": "qiú", "gloss_en": "seek; beseech"}]}, "id": "35", "hanzi": "愿望", "pinyin": "yuàn wàng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an earnest desire, wish, or aspiration for a particular state of affairs or future outcome to come true", "definition_es": "deseo o anhelo vehemente de que se cumpla algo favorable o esperado en el porvenir", "example_phrase": "美好的愿望 (cherished / beautiful wish)"}], "example_sentences": [{"id": "#1", "hanzi": "每天清晨能在自然光线中舒服地自然醒来，是很多饱受闹钟折磨的上班族最朴素的愿望。", "pinyin": "Měitiān qīngchén néng zài zìrán guāngxiàn zhōng shūfu de zìrán xǐnglái, shì hěnduō bǎoshòu nàozhōng zhémó de shàngbānzú zuì pǔsù de yuànwàng.", "en": "Being able to wake up comfortably and naturally in morning daylight every day is the most modest wish of many office workers tormented by alarms.", "es": "Poder despertarse plácidamente con la luz natural cada mañana es el anhelo más sencillo de multitud de oficinistas martirizados por el despertador."}, {"id": "#2", "hanzi": "经过多年的刻苦攻读与拼搏，他终于实现了考取重点大学的童年愿望。", "pinyin": "Jīngguò duō nián de kèkǔ gōngdú yǔ pīnbó, tā zhōngyú shíxiànle kǎoqǔ zhòngdiǎn dàxué de tóngnián yuànwàng.", "en": "After years of assiduous study and hard work, he finally realized his childhood wish of gaining admission into a key university.", "es": "Tras años de empeño y estudio tesonero, vio cumplido por fin su sueño de infancia de ingresar en una universidad de prestigio."}], "collocations": [{"hanzi": "实现愿望", "en": "fulfill a wish / realize an aspiration"}, {"hanzi": "美好愿望", "en": "cherished wish; wonderful hope"}, {"hanzi": "表达愿望", "en": "express one's desire / wish"}, {"hanzi": "共同愿望", "en": "shared desire; common aspiration"}, {"hanzi": "强烈的愿望", "en": "fervent wish; strong longing"}, {"hanzi": "童年愿望", "en": "childhood wish"}], "idioms": [{"hanzi": "如愿以偿", "pinyin": "rú yuàn yǐ cháng", "meaning_en": "have one's wish completely fulfilled"}, {"hanzi": "天从人愿", "pinyin": "tiān cóng rén yuàn", "meaning_en": "Heaven fulfills human wishes; events turn out as hoped"}, {"hanzi": "事与愿违", "pinyin": "shì yǔ yuàn wéi", "meaning_en": "things turn out contrary to one's wishes"}, {"hanzi": "梦寐以求", "pinyin": "mèng mèi yǐ qiú", "meaning_en": "crave something even in one's dreams"}], "character_decomposition": [{"character": "愿", "pinyin": "yuàn", "meaning_en": "wish; willing; desire; honest", "meaning_es": "desear; querer; voluntad; anhelo", "radical": "心", "radical_meaning_en": "heart", "meaning_component": "原 (meadow source / sincere plainness) + 心 (inner heart's intent)", "sound_component": "原 (yuán, origin / phonetic)", "stroke_count": "14", "composition_type": "上下结构", "etymology_and_mnemonic": "Heart 心 resting beneath meadow source 原; the honest, unvarnished desire bubbling up from deep within one's soul.", "visual_mnemonic_story_en": "From the original spring source (原) of the heart (心) flows sincere willingness and wish (愿).", "visual_mnemonic_story_es": "Desde el manantial original (原) del corazón (心) brota el anhelo puro y la voluntad (愿).", "tone_mnemonic_anchor": "51", "cangjie": "MHP", "traditional": "願"}, {"character": "望", "pinyin": "wàng", "meaning_en": "look into distance; hope; gaze; expect", "meaning_es": "mirar a lo lejos; esperar; contemplar; anhelar", "radical": "月", "radical_meaning_en": "moon", "meaning_component": "亡 (hide / vanish) + 月 (full moon) + 王/𡈼 (person standing on tiptoe to gaze)", "sound_component": "Historical phonetic wàng", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "A person standing tall on high ground gazing at the distant full moon 月; looking far away with intense longing.", "visual_mnemonic_story_en": "Standing tall on tiptoes to gaze toward the moon (月), eyes filled with hopeful longing (望).", "visual_mnemonic_story_es": "De puntillas sobre una colina contemplando la luna llena (月), la mirada se llena de anhelo y esperanza (望).", "tone_mnemonic_anchor": "51", "cangjie": "YGB", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在孩子纯真的心目中，新年最大的愿望往往不过是得到一件心仪的玩具，或是父母能抽空陪自己去游乐园度过周末。这种简单质朴的心愿，却映射出家庭温暖对童年成长无可替代的珍贵意义。", "pinyin": "Zài háizi chúnzhēn de xīnmù zhōng, xīnnián zuìdà de yuànwàng wǎngwǎng búguò shì dédào yī jiàn xīnyí de wánjù, huòshì fùmǔ néng chōukòng péi zìjǐ qù yóulèyuán dùguò zhōumò. Zhèzhǒng jiǎndān zhìpǔ de xīnyuàn, què yìngshè chū jiātíng wēnnuǎn duì tóngnián chéngzhǎng wúkě tìdài de zhēnguì yìyì.", "en": "In the innocent eyes of children, the greatest New Year wish is often just getting a favorite toy or spending the weekend at an amusement park with parents. Such simple longings mirror the irreplaceable warmth of family in childhood.", "es": "Para el corazón inocente de un niño, el mayor anhelo de Año Nuevo suele ser un juguete soñado o que sus padres le lleven al parque de atracciones. Tan entrañable ilusión refleja el calor familiar insustituible en la infancia."}, {"id": "#2", "hanzi": "渴望和平与繁荣是全人类跨越国界与种族的共同愿望。历史深刻证明，封闭隔阂只会加剧争端，唯有坚持合作共赢与开放包容，才能让各国人民安居乐业的美好憧憬真正化作生动的现实，携手构建和谐美好的地球家园。", "pinyin": "Kěwàng hépíng yǔ fánróng shì quán rénlèi kuàyuè guójiè yǔ zhǒngzú de gòngtóng yuànwàng. Lìshǐ shēnkè zhèngmíng, fēngbì géhé zhǐhuì jiājù zhēngduān, wéiyǒu jiānchí hézuò gòngyíng yǔ kāifàng bāoróng, cáinéng ràng gè guó rénmín ānjū-lèyè de měihǎo chōngjǐng zhēnzhèng huàzuò shēngdòng de xiànshí, xiéshǒu gòujiàn héxié měihǎo de dìqiú jiāyuán.", "en": "Longing for peace and prosperity is a shared aspiration of mankind across borders. History proves isolation heightens conflict; only cooperation and open inclusion transform the dream of peaceful living into reality.", "es": "El anhelo de paz y bonanza une a toda la humanidad por encima de fronteras. La historia demuestra que el aislamiento agrava disputas; solo la cooperación y la inclusión hacen realidad el sueño de vivir en armonía en nuestro planeta común."}]}, {"meanings_summary": {"en": "window curtain; drapes; window blinds", "es": "cortina; visillo; cortinaje de ventana"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A window opening (窗) fitted with a protective hanging cloth (帘) forms the household curtain (窗帘).", "composite_memory_hook_es": "El vano de la ventana (窗) cubierto por un paño suspendido (帘) compone la cortina (窗帘).", "cultural_and_cognitive_roots": "Traditional courtyard houses used bamboo screens (竹帘) in summer and silk padded drapes (布帘) in winter to regulate temperature and social privacy.", "tone_sandhi_and_pitch_modulation": "First tone followed by second tone: 'chuāng lián' (55-35). Hold high 55, then glide up smoothly to 35."}, "semantic_boundary_contrasts": {"core_nuance": "窗帘 refers specifically to window drapes or curtains meant for shading light and protecting indoor privacy.", "contrasts": [{"id": "1", "compared_word": "窗帘 vs. 门帘", "pinyin": "ménlián", "analysis": "门帘 is a curtain hung at a doorway or entrance portal to block cold drafts or insects, whereas 窗帘 is hung at windows."}, {"id": "2", "compared_word": "窗帘 vs. 帷幕", "pinyin": "wéimù", "analysis": "帷幕 refers to large-scale theatrical curtains, formal stage drapes, or figurative political curtains ('拉开帷幕'), not domestic window curtains."}, {"id": "3", "compared_word": "窗帘 vs. 百叶窗", "pinyin": "bǎiyèchuāng", "analysis": "百叶窗 refers to slatted blinds (made of wood, aluminum, or plastic), while 窗帘 broadly denotes fabric drapes or curtains in general."}]}, "traps_and_cognates": {"look_alikes": [{"character": "窜", "pinyin": "cuàn", "meaning_en": "flee; scurry", "distinction_note": "Has rat 鼠 at bottom under 穴 instead of 囱 in 窗"}, {"character": "窟", "pinyin": "kū", "meaning_en": "hole; cave", "distinction_note": "Has 屈 under 穴"}, {"character": "市", "pinyin": "shì", "meaning_en": "market; city", "distinction_note": "Single character with 亠 over 巾, lacking 穴 in 帘"}, {"character": "希", "pinyin": "xī", "meaning_en": "hope", "distinction_note": "Has 乂 over cloth 巾"}], "etymological_cognates": [{"character": "幕", "pinyin": "mù", "gloss_en": "curtain; theatrical drape"}, {"character": "帐", "pinyin": "zhàng", "gloss_en": "canopy; tent; screen"}, {"character": "幔", "pinyin": "màn", "gloss_en": "hanging drapery"}, {"character": "屏", "pinyin": "píng", "gloss_en": "folding screen"}]}, "id": "36", "hanzi": "窗帘", "pinyin": "chuāng lián", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a hanging cloth, screen, or drapery used to cover a window to block out light, provide privacy, or decorate an interior", "definition_es": "paño o tejido suspendido en una ventana para tamizar la luz solar, preservar la intimidad o decorar el aposento", "example_phrase": "拉开窗帘 (draw open the curtains)"}], "example_sentences": [{"id": "#1", "hanzi": "专家建议睡前不要把窗帘拉得过于严实，留出一道缝隙让清晨柔和的阳光洒入房间。", "pinyin": "Zhuānjiā jiànyì shuì qián búyào bǎ chuānglián lā de guòyú yánshi, liúchū yī dào fèngxì ràng qīngchén róuhé de yángguāng sǎ rù fángjiān.", "en": "Experts suggest not drawing the window curtains shut too tightly before sleep, leaving a small gap for gentle morning light to filter in.", "es": "Los especialistas aconsejan no cerrar las cortinas del todo al acostarse, dejando una rendija para que penetre la tenue luz matutina."}, {"id": "#2", "hanzi": "她轻轻拉上卧室的遮光窗帘，隔绝了窗外繁华街道闪烁的霓虹灯光，安静地躺下入睡。", "pinyin": "Tā qīngqīng lāshàng wòshì de zhēguāng chuānglián, géjuéle chuāngwài fánhuá jiēdào shǎnshuò de níhóng dēngguāng, ānjìng de tǎngxià rùshuì.", "en": "She gently drew the bedroom blackout curtains shut, blocking out the glittering neon lights of the busy street, and laid down quietly to sleep.", "es": "Corrió suavemente las cortinas tupidas del dormitorio, aislando el resplandor de los neones de la concurrida calle para dormir en paz."}], "collocations": [{"hanzi": "拉开窗帘", "en": "draw open the curtains"}, {"hanzi": "拉上窗帘", "en": "close / draw the curtains"}, {"hanzi": "遮光窗帘", "en": "blackout curtain"}, {"hanzi": "百叶窗帘", "en": "Venetian blinds / louver curtain"}, {"hanzi": "窗帘布", "en": "curtain fabric"}, {"hanzi": "更换窗帘", "en": "replace window curtains"}], "idioms": [{"hanzi": "开窗见日", "pinyin": "kāi chuāng jiàn rì", "meaning_en": "open the window to see the bright sun; instant clarity"}, {"hanzi": "铁幕窗下", "pinyin": "tiě mù chuāng xià", "meaning_en": "behind heavy iron curtains; cloistered secrecy"}, {"hanzi": "帘卷西风", "pinyin": "lián juǎn xī fēng", "meaning_en": "curtains stirred by autumn west winds; bittersweet wistfulness"}, {"hanzi": "垂帘听政", "pinyin": "chuí lián tīng zhèng", "meaning_en": "govern from behind the curtain (imperial empress dowager rule)"}], "character_decomposition": [{"character": "窗", "pinyin": "chuāng", "meaning_en": "window; opening", "meaning_es": "ventana; tragaluz; vano", "radical": "穴", "radical_meaning_en": "cave / hole", "meaning_component": "穴 (roof opening/cave) + 囱 (chimney / smoke hole with lattice bars)", "sound_component": "囱 (cōng, smoke flue / phonetic)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "A cave dwelling opening 穴 with a wooden lattice 囱 to ventilate smoke and admit natural daylight; hence a window.", "visual_mnemonic_story_en": "A vent cut into a cave roof (穴) crossed with wooden window grates (囱) lets light through the window (窗).", "visual_mnemonic_story_es": "Una abertura en la cueva (穴) cruzada con una celosía (囱) permite que la luz entre por la ventana (窗).", "tone_mnemonic_anchor": "55", "cangjie": "JCHUK", "traditional": ""}, {"character": "帘", "pinyin": "lián", "meaning_en": "curtain; screen; banner", "meaning_es": "cortina; visillo; biombo; tela suspendida", "radical": "巾", "radical_meaning_en": "cloth / towel", "meaning_component": "穴 (window aperture) + 巾 (hanging cloth / textile drapery)", "sound_component": "廉 (lián, phonetic in full traditional form 簾)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A piece of cloth 巾 hung over a window aperture 穴 to shield against draft and sunlight; a hanging drapery screen.", "visual_mnemonic_story_en": "A soft cloth fabric (巾) suspended across an aperture (穴) hangs gracefully as a curtain (帘).", "visual_mnemonic_story_es": "Una tela de paño (巾) suspendida sobre el vano (穴) actúa como cortina protectora (帘).", "tone_mnemonic_anchor": "35", "cangjie": "JCLB", "traditional": "簾"}], "extended_reading_passages": [{"id": "#1", "hanzi": "现代智能家居系统赋予了窗帘崭新的科技内涵。用户可以通过手机软件预设开启时间，每天清晨窗帘便会自动缓缓拉开一道缝隙，让初升的旭日柔和地唤醒睡眠者，帮助人体生物钟实现平稳的自然过渡。", "pinyin": "Xiàndài zhìnéng jiājū xìtǒng fùyǔle chuānglián zhǎnxīn de kējì nèihán. Yònghù kěyǐ tōngguò shǒujī ruǎnjiàn yùshè kāiqǐ shíjiān, měitiān qīngchén chuānglián biàn huì zìdòng huǎnhuǎn lākāi yī dào fèngxì, ràng chūshēng de xùrì róuhé de huànxǐng shuìmiánzhě, bāngzhù réntǐ shēngwùzhōng shíxiàn píngwěn de zìrán guòdù.", "en": "Modern smart home systems give window curtains fresh technological utility. Users preset opening times via smartphone apps, allowing curtains to automatically part slightly at dawn, letting sunrise gently awaken the sleeper.", "es": "La domótica moderna confiere a las cortinas un papel tecnológico puntero. Mediante aplicaciones móviles, se programa su apertura para que el sol matutino despierte plácidamente al durmiente, regulando el reloj biológico."}, {"id": "#2", "hanzi": "老宅书房的那副厚实亚麻窗帘，见证了祖父伏案著书的数十载光阴。每当午后斜阳照耀，拉上一半窗帘便能让斑驳柔和的光影洒在满架线装古籍上。微风吹过，窗帘轻轻摇曳，伴着浓郁的墨香，勾勒出一幅宁静深邃的传统文人生活图景。", "pinyin": "Lǎozhái shūfáng de nà fù hòushí yàmá chuānglián, jiànzhèngle zǔfù fú'àn zhùshū de shùshí zǎi guāngyīn. Měidāng wǔhòu xiéyáng zhàoyào, lāshàng yībàn chuānglián biàn néng ràng bānbó róuhé de guāngyǐng sǎ zài mǎnjià xiànzhuāng gǔjí shàng. Wēifēng chuīguò, chuānglián qīngqīng yáoyè, bànzhe nóngyù de mòxiāng, gōulè chū yī fú níngjìng shēnsuì de chuántǒng wénrén shēnghuó tújǐng.", "en": "The thick linen curtains in the ancestral study witnessed decades of grandfather writing books. Drawing them halfway diffused gentle afternoon shadows over antique shelves, drifting with ink fragrance into an aura of scholarly peace.", "es": "Las gruesas cortinas de lino del viejo despacho presenciaron décadas de labor literaria del abuelo. Correrlas a medias matizaba sombras suaves sobre volúmenes antiguos, trazando un cuadro sereno de aromas de tinta y calma letrada."}]}, {"meanings_summary": {"en": "market; marketplace; commercial arena; market demand", "es": "mercado; plaza de abastos; ámbito comercial; demanda de mercado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A civic trading center (市) situated on a broad public gathering ground (场) constitutes a market (市场).", "composite_memory_hook_es": "El comercio urbano (市) celebrado en una explanada o plaza comunal (场) forma el mercado (市场).", "cultural_and_cognitive_roots": "From the ancient Zhou Dynasty 'well-field' system: farmers gathered at noon on public threshing grounds (场) to trade surpluses (市).", "tone_sandhi_and_pitch_modulation": "Fourth tone followed by third tone: 'shì chǎng' (51-214). Sharp initial fall dropping into a full low-dip third tone."}, "semantic_boundary_contrasts": {"core_nuance": "市场 encompasses both concrete physical marketplaces (farmer's market, supermarket) and abstract commercial macroeconomic systems.", "contrasts": [{"id": "1", "compared_word": "市场 vs. 商场", "pinyin": "shāngchǎng", "analysis": "商场 specifically refers to a large physical commercial department store or modern shopping mall ('去商场购物'), whereas 市场 can refer to abstract economic demand ('股票市场', '全球市场')."}, {"id": "2", "compared_word": "市场 vs. 集市", "pinyin": "jíshì", "analysis": "集市 denotes traditional rural periodic bazaars or country fairs, whereas 市场 is the modern comprehensive economic term."}, {"id": "3", "compared_word": "市场 vs. 行业", "pinyin": "hángyè", "analysis": "行业 categorizes a specific domain of trade/industry (e.g. IT, finance), while 市场 reflects trading transactions and consumer demand."}]}, "traps_and_cognates": {"look_alikes": [{"character": "布", "pinyin": "bù", "meaning_en": "cloth; spread", "distinction_note": "Has 𠂇 at top instead of 亠 in 市"}, {"character": "帅", "pinyin": "shuài", "meaning_en": "commander; handsome", "distinction_note": "Has 刂-like stroke on left of 巾"}, {"character": "扬", "pinyin": "yáng", "meaning_en": "raise; scatter", "distinction_note": "Has hand radical 扌 on left instead of earth 土 in 场"}, {"character": "汤", "pinyin": "tāng", "meaning_en": "soup; hot water", "distinction_note": "Has water radical 氵 on left"}], "etymological_cognates": [{"character": "商", "pinyin": "shāng", "gloss_en": "commerce; merchant"}, {"character": "贾", "pinyin": "gǔ", "gloss_en": "trader; goods"}, {"character": "市", "pinyin": "shì", "gloss_en": "fair; marketplace"}, {"character": "坊", "pinyin": "fāng", "gloss_en": "workshop; urban quarter"}]}, "id": "37", "hanzi": "市场", "pinyin": "shì chǎng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a physical or virtual commercial arena where goods, commodities, and services are traded between buyers and sellers", "definition_es": "espacio físico o virtual donde se compran y venden mercancías, bienes o servicios", "example_phrase": "开拓海外市场 (open up overseas markets)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the collective demand and commercial purchasing potential for a particular product category", "definition_es": "la demanda colectiva y potencial comercial de un determinado tipo de producto o servicio", "example_phrase": "市场潜力巨大 (tremendous market potential)"}], "example_sentences": [{"id": "#1", "hanzi": "敏锐的商家洞察到现代人对健康唤醒的迫切需求，在市场上推出了各式各样模拟自然光线的智能闹钟。", "pinyin": "Mǐnruì de shāngjiā dòngchá dào xiàndàirén duì jiànkāng huànxǐng de pòqiè xūqiú, zài shìchǎng shàng tuīchūle gèshì-gèyàng mónǐ zìrán guāngxiàn de zhìnéng nàozhōng.", "en": "Keen merchants discerned modern people's urgent need for healthy wake-ups and launched various smart alarms simulating natural daylight onto the market.", "es": "Comerciantes perspicaces detectaron la necesidad de un despertar saludable y lanzaron al mercado despertadores inteligentes que simulan la luz natural."}, {"id": "#2", "hanzi": "面对日趋激烈的国际竞争，企业唯有不断加大技术创新投入，才能在全球市场上立于不败之地。", "pinyin": "Miànduì rìqū jīliè de guójì jìngzhēng, qǐyè wéiyǒu bùduàn jiādà jìshù chuàngxīn tóurù, cáinéng zài quánqiú shìchǎng shàng lìyú búbài zhī dì.", "en": "Facing increasingly fierce international competition, enterprises can remain invincible in the global market only by continually increasing technological innovation.", "es": "Ante la encarnizada competencia internacional, las empresas solo se mantendrán invictas en el mercado mundial redoblando su inversión en innovación."}], "collocations": [{"hanzi": "开拓市场", "en": "expand / open up the market"}, {"hanzi": "市场需求", "en": "market demand"}, {"hanzi": "市场份额", "en": "market share"}, {"hanzi": "国际市场", "en": "international market"}, {"hanzi": "市场准入", "en": "market access"}, {"hanzi": "市场竞争", "en": "market competition"}], "idioms": [{"hanzi": "门庭若市", "pinyin": "mén tíng ruò shì", "meaning_en": "courtyard bustling like a crowded marketplace; busy with visitors"}, {"hanzi": "招摇过市", "pinyin": "zhāo yáo guò shì", "meaning_en": "parade boastfully through the streets to attract attention"}, {"hanzi": "日中为市", "pinyin": "rì zhōng wéi shì", "meaning_en": "gather at noon for marketing (ancient trade custom)"}, {"hanzi": "市场繁荣", "pinyin": "shì chǎng fán róng", "meaning_en": "flourishing market and thriving commercial activity"}], "character_decomposition": [{"character": "市", "pinyin": "shì", "meaning_en": "market; city; trade; municipality", "meaning_es": "mercado; ciudad; comercio; municipio", "radical": "巾", "radical_meaning_en": "cloth", "meaning_component": "亠 (city gate roof) + 巾 (market trade banner)", "sound_component": "Pictographic trading post banner", "stroke_count": "5", "composition_type": "上下结构", "etymology_and_mnemonic": "A trading flag 巾 flying high over the town pavilion 亠 where merchants gathered to barter; later denoting city and market.", "visual_mnemonic_story_en": "Under a market roof (亠), trade banners (巾) flutter to welcome merchants to the market (市).", "visual_mnemonic_story_es": "Bajo el pabellón comunal (亠), el estandarte textil (巾) anuncia la plaza comercial y mercado (市).", "tone_mnemonic_anchor": "51", "cangjie": "YBL", "traditional": ""}, {"character": "场", "pinyin": "chǎng", "meaning_en": "open ground; field; threshing floor; scene", "meaning_es": "campo; plaza; explanada; era; escenario", "radical": "土", "radical_meaning_en": "earth / ground", "meaning_component": "土 (earth/ground) + 𠃓/昜 (open sunlight shining broadly)", "sound_component": "昜 (yáng, sunlit open / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "An open leveled ground of earth 土 warmed by sunshine where grain was threshed and people assembled for public events.", "visual_mnemonic_story_en": "A wide plot of leveled earth (土) bathed in open sunlight serves as a public assembly field (场).", "visual_mnemonic_story_es": "Una explanada de tierra llana (土) al sol abierto que sirve de era, plaza o escenario (场).", "tone_mnemonic_anchor": "214", "cangjie": "GNSH", "traditional": "場"}], "extended_reading_passages": [{"id": "#1", "hanzi": "随着消费者对睡眠健康认知的不断深化，全球助眠产品市场迎来爆发式增长。从智能香薰机到光照唤醒灯，各类高科技睡眠产品层出不穷，精准切中都市职场人群的痛点，展现出巨大的市场增长潜力。", "pinyin": "Suízhe xiāofèizhě duì shuìmián jiànkāng rènzhī de bùduàn shēnhuà, quánqiú zhùmián chǎnpǐn shìchǎng yínglái bàofāshì zēngzhǎng. Cóng zhìnéng xiāngxūnjī dào guāngzhào huànxǐngdēng, gèlèi gāokējì shuìmián chǎnpǐn céngchū-bùqióng, jīngzhǔn qièzhòng dūshì zhíchǎng rénqún de tòngdiǎn, zhǎnxiàn chū jùdà de shìchǎng zēngzhǎng qiánlì.", "en": "With deepening consumer awareness of sleep health, the global sleep-aid market is experiencing explosive growth. From aromatherapy diffusers to wake-up lights, diverse gadgets emerge continuously, showing immense market potential.", "es": "Con el aumento de la conciencia sobre la salud del sueño, el mercado global de artículos de descanso vive un auge espectacular. Desde difusores inteligentes hasta lámparas de amanecer, surgen productos que muestran un enorme potencial de mercado."}, {"id": "#2", "hanzi": "开放有序的市场环境是激发实体经济活力的根本保障。政府部门通过持续优化营商环境、打破行业垄断壁垒，有效保护了中小型创新企业的合法权益，促使优质资源在全球市场大循环中实现更加高效的配置。", "pinyin": "Kāifàng yǒuxù de shìchǎng huánjìng shì jīfā shítǐ jīngjì huólì de gēnběn bǎozhàng. Zhèngfǔ bùmén tōngguò chíxù yōuhuà yíngshāng huánjìng, dǎpò hángyè lǒngduàn bìlěi, yǒuxiào bǎohùle zhōng-xiǎoxíng chuàngxīn qǐyè de héfǎ quányì, cùshǐ yōuzhì zīyuán zài quánqiú shìchǎng dàxúnhuán zhōng shíxiàn gèngjiā gāoxiào de pèizhì.", "en": "An open and orderly market environment is the fundamental guarantee for vitalizing the real economy. By optimizing business environments and lowering barriers, governments protect small innovators and allocate resources efficiently.", "es": "Un entorno de mercado abierto y ordenado apuntala la economía productiva. Al mejorar las condiciones comerciales y suprimir monopolios, las autoridades tutelan a pequeñas empresas innovadoras y asignan recursos con suma eficiencia."}]}, {"meanings_summary": {"en": "product; merchandise; goods; manufactured output", "es": "producto; mercancía; artículo fabricado; bien producido"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Goods produced through human labor (产) inspected and certified for consumer taste (品) form a product (产品).", "composite_memory_hook_es": "Bienes engendrados o producidos (产) cuya calidad pasa la prueba de los evaluadores (品) integran un producto (产品).", "cultural_and_cognitive_roots": "Derived from ancient guild standards where newly produced items (产) had to pass threefold taste/grade scrutiny (品) before reaching public trade.", "tone_sandhi_and_pitch_modulation": "Two third tones in succession: 'chǎn pǐn' transforms via tone sandhi into (35-214). Pronounce 'chán pǐn'."}, "semantic_boundary_contrasts": {"core_nuance": "产品 emphasizes the output of manufacturing, software development, or industrial processing designed for commercial utility.", "contrasts": [{"id": "1", "compared_word": "产品 vs. 商品", "pinyin": "shāngpǐn", "analysis": "商品 specifically stresses goods circulating in monetary trade on the market, while 产品 emphasizes the manufactured item itself (even before selling)."}, {"id": "2", "compared_word": "产品 vs. 用品", "pinyin": "yòngpǐn", "analysis": "用品 denotes items grouped by everyday utility function (e.g. 办公用品, 生活用品), whereas 产品 is a broader industrial category."}, {"id": "3", "compared_word": "产品 vs. 作品", "pinyin": "zuòpǐn", "analysis": "作品 refers to creative, artistic, literary, or intellectual works (books, paintings, symphonies), while 产品 refers to commercial/industrial output."}]}, "traps_and_cognates": {"look_alikes": [{"character": "严", "pinyin": "yán", "meaning_en": "strict; severe", "distinction_note": "Has two horizontal bars at top, unlike 产"}, {"character": "立", "pinyin": "lì", "meaning_en": "stand; erect", "distinction_note": "Bottom horizontal stroke is straight without downward sweep"}, {"character": "器", "pinyin": "qì", "meaning_en": "utensil; vessel", "distinction_note": "Has dog 犬 enclosed by four mouths 口"}, {"character": "晶", "pinyin": "jīng", "meaning_en": "crystal; glittering", "distinction_note": "Composed of three suns 日, not mouths 口"}], "etymological_cognates": [{"character": "物", "pinyin": "wù", "gloss_en": "thing; commodity"}, {"character": "货", "pinyin": "huò", "gloss_en": "goods; merchandise"}, {"character": "商", "pinyin": "shāng", "gloss_en": "trade; commodity"}, {"character": "具", "pinyin": "jù", "gloss_en": "tool; appliance"}]}, "id": "38", "hanzi": "产品", "pinyin": "chǎn pǐn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "tangible goods, items, or commercial services manufactured, processed, or developed to satisfy market consumer needs", "definition_es": "artículo manufacturado, bien material o servicio elaborado para satisfacer necesidades en el mercado", "example_phrase": "电子产品 (electronic products / gadgets)"}], "example_sentences": [{"id": "#1", "hanzi": "科研团队历时两年研发出这款新型助眠产品，能通过渐进式柔和光线模拟大自然的日出过程。", "pinyin": "Kēyán tuánduì lìshí liǎng nián yánfā chū zhè kuǎn xīnxíng zhùmián chǎnpǐn, néng tōngguò jiànjìnshì róuhé guāngxiàn mónǐ dàzìrán de rìchū guòchéng.", "en": "The research team spent two years developing this new sleep-aid product, which simulates nature's sunrise through progressive gentle light.", "es": "El equipo científico dedicó dos años a concebir este nuevo producto para dormir, que simula el amanecer natural con luz suave progresiva."}, {"id": "#2", "hanzi": "只有严格把控每一个生产环节的产品质量，企业才能在激烈的市场竞争中赢得消费者的信赖。", "pinyin": "Zhǐyǒu yángé bǎkòng měi yī gè shēngchǎn huánjié de chǎnpǐn zhìliàng, qǐyè cáinéng zài jīliè de shìchǎng jìngzhēng zhōng yíngdé xiāofèizhě de xìnlài.", "en": "Only by strictly controlling product quality at every production phase can an enterprise win consumer trust amid fierce market competition.", "es": "Solo supervisando con rigor la calidad del producto en cada eslabón productivo puede la empresa granjearse la lealtad del consumidor."}], "collocations": [{"hanzi": "产品质量", "en": "product quality"}, {"hanzi": "研发产品", "en": "research and develop a product"}, {"hanzi": "产品设计", "en": "product design"}, {"hanzi": "电子产品", "en": "electronic products"}, {"hanzi": "产品线", "en": "product line"}, {"hanzi": "推广产品", "en": "promote / market a product"}], "idioms": [{"hanzi": "优胜劣汰", "pinyin": "yōu shèng liè tài", "meaning_en": "survival of the fittest; superior wins and inferior is weeded out"}, {"hanzi": "品学兼优", "pinyin": "pǐn xué jiān yōu", "meaning_en": "excelling in both moral character and academic learning"}, {"hanzi": "推陈出新", "pinyin": "tuī chén chū xīn", "meaning_en": "weed through the old to bring forth the new"}, {"hanzi": "价廉物美", "pinyin": "jià lián wù měi", "meaning_en": "excellent quality at a modest price"}], "character_decomposition": [{"character": "产", "pinyin": "chǎn", "meaning_en": "produce; give birth; output; property", "meaning_es": "producir; engendrar; parir; bienes; producción", "radical": "亠", "radical_meaning_en": "lid / roof", "meaning_component": "A newborn plant growing out of fertile soil; simplified from 產", "sound_component": "Historical phonetic component", "stroke_count": "6", "composition_type": "单一结构", "etymology_and_mnemonic": "Depicts a living plant sprouting forth and bearing fruit; represents giving birth, producing, yield, and manufactured output.", "visual_mnemonic_story_en": "Sprouts rising out of fertile land yielding harvest produce (产).", "visual_mnemonic_story_es": "Tallos que brotan de tierra fértil rindiendo cosecha y producción (产).", "tone_mnemonic_anchor": "214", "cangjie": "YHH", "traditional": "產"}, {"character": "品", "pinyin": "pǐn", "meaning_en": "goods; quality; grade; evaluate; taste", "meaning_es": "mercancía; calidad; grado; degustar; catar", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "Three mouths 口 stacked together representing many vessels or people tasting and judging items", "sound_component": "Ideographic cluster of mouths evaluating goods", "stroke_count": "9", "composition_type": "品字结构", "etymology_and_mnemonic": "Three mouths 口 arranged in a pyramid, depicting multiple judges evaluating, savoring, and grading the quality of merchandise.", "visual_mnemonic_story_en": "Three critical mouths (口) sample and appraise goods to ensure certified grade and quality (品).", "visual_mnemonic_story_es": "Tres bocas (口) que degustan y evalúan mercancías para calibrar su calidad y categoría (品).", "tone_mnemonic_anchor": "214", "cangjie": "RRR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代科技企业中，优秀的产品经理必须始终将用户体验置于首位。一款成功的科技硬件产品不仅需要具备出色的工业设计与稳定的功能表现，更应融入对当代人生活痛点的人文关怀，让科技真正润物无声地服务于人。", "pinyin": "Zài xiàndài kējì qǐyè zhōng, yōuxiù de chǎnpǐn jīnglǐ bìxū shǐzhōng jiāng yònghù tǐyàn zhìyú shǒuwèi. Yī kuǎn chénggōng de kējì yìngjiàn chǎnpǐn bùjǐn xūyào jùbèi chūsè de gōngyè shèjì yǔ wěndìng de gōngnéng biǎoxiàn, gèng yīng róngrù duì dāngdàirén shēnghuó tòngdiǎn de rénwén guānhuái, ràng kējì zhēnzhèng rùnwù-wúshēng de fúwù yú rén.", "en": "In tech firms, great product managers prioritize user experience above all. A successful tech hardware product demands exceptional industrial design, stable performance, and humane care addressing daily pain points.", "es": "En las tecnológicas, los jefes de producto priorizan la experiencia del usuario. Un producto de hardware exitoso conjuga un diseño depurado, estabilidad funcional y sensibilidad humana hacia los problemas cotidianos."}, {"id": "#2", "hanzi": "随着全球绿色低碳消费风潮的兴起，节能环保型产品正迅速占据各大消费市场的主流地位。制造厂商积极更新工艺，减少产品在整个生命周期中的能源消耗与碳排放，不仅履行了企业社会责任，也塑造了卓越的品牌形象。", "pinyin": "Suízhe quánqiú lǜsè dītàn xiāofèi fēngcháo de xīngqǐ, jiénéng huánbǎoxíng chǎnpǐn zhèng xùnsù zhànjù gè dà xiāofèi shìchǎng de zhǔliú dìwèi. Zhìzào chǎngshāng jījí gēngxīn gōngyì, jiǎnshǎo chǎnpǐn zài zhěnggè shēngmìng zhōuqī zhōng de néngyuán xiāohào yǔ tànpáifàng, bùjǐn lǚxíngle qǐyè shèhuì zérèn, yě shùzàole zhuóyuè de pǐnpái xíngxiàng.", "en": "With the rise of green consumption, eco-friendly products are rapidly dominating mainstream markets. Manufacturers actively upgrade processes to cut life-cycle energy consumption and carbon emissions, fulfilling social duties while elevating brand image.", "es": "Con el auge del consumo ecológico, los productos energéticamente sostenibles dominan el mercado. Los fabricantes renuevan sus procesos recortando emisiones y huella de carbono a lo largo del ciclo vital del producto, forjando un prestigio ejemplar."}]}, {"meanings_summary": {"en": "to imitate; mimic; emulate; model after; copy", "es": "imitar; remedar; copiar; emular; reproducir pautas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Taking a standard archetype mold (模) and having a person copy its shape (仿) is imitating (模仿).", "composite_memory_hook_es": "Tomar un molde patrón (模) y hacer que la persona reproduzca su diseño (仿) es imitar (模仿).", "cultural_and_cognitive_roots": "Bionics (仿生学): human engineering has historically advanced by observing and copying flight, acoustics, and camouflage from nature.", "tone_sandhi_and_pitch_modulation": "Second tone followed by third tone: 'mó fǎng' (35-214). Smooth rising glide followed by low dipping third tone."}, "semantic_boundary_contrasts": {"core_nuance": "模仿 involves actively observing an external model (behavior, speech, nature) and reproducing its characteristics.", "contrasts": [{"id": "1", "compared_word": "模仿 vs. 模拟", "pinyin": "mónǐ", "analysis": "模拟 emphasizes technical simulation, scientific modeling, or mock testing (e.g. 模拟考试, 模拟飞行), while 模仿 leans toward human or artistic imitation."}, {"id": "2", "compared_word": "模仿 vs. 抄袭", "pinyin": "chāoxí", "analysis": "抄袭 carries strong negative legal and moral condemnation for plagiarizing essays, songs, or patents, whereas 模仿 can be a neutral learning method."}, {"id": "3", "compared_word": "模仿 vs. 效仿", "pinyin": "xiàofǎng", "analysis": "效仿 is more formal, often describing following an admirable historical role model or policy precedent ('效仿先贤')."}]}, "traps_and_cognates": {"look_alikes": [{"character": "摸", "pinyin": "mō", "meaning_en": "touch; feel; grope", "distinction_note": "Has hand radical 扌 on left instead of wood 木 in 模"}, {"character": "膜", "pinyin": "mó", "meaning_en": "membrane; film", "distinction_note": "Has flesh radical 月 on left"}, {"character": "访", "pinyin": "fǎng", "meaning_en": "visit; interview", "distinction_note": "Has speech radical 讠 on left instead of person 亻 in 仿"}, {"character": "防", "pinyin": "fáng", "meaning_en": "defend; guard", "distinction_note": "Has mound radical 阝 on left"}], "etymological_cognates": [{"character": "拟", "pinyin": "nǐ", "gloss_en": "simulate; draft"}, {"character": "抄", "pinyin": "chāo", "gloss_en": "copy; transcribe"}, {"character": "效", "pinyin": "xiào", "gloss_en": "emulate; effect"}, {"character": "学", "pinyin": "xué", "gloss_en": "study; learn by imitation"}]}, "id": "39", "hanzi": "模仿", "pinyin": "mó fǎng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to copy, simulate, or model one's behavior, style, sound, or mechanism after an existing example or natural phenomenon", "definition_es": "reproducir o copiar adrede los ademanes, el aspecto, el funcionamiento o el sonido de un modelo natural o ajeno", "example_phrase": "模仿自然声音 (mimic natural sounds)"}], "example_sentences": [{"id": "#1", "hanzi": "新型健康闹钟通过模仿大自然中鸟鸣和清泉的流动声，让人们在清晨舒缓地苏醒过来。", "pinyin": "Xīnxíng jiànkāng nàozhōng tōngguò mófǎng dàzìrán zhōng niǎomíng hé qīngquán de liúdòng shēng, ràng rénmen zài qīngchén shūhuǎn de sūxǐng guòlái.", "en": "New wellness alarms awaken people soothingly in the morning by mimicking birdsong and flowing springs found in nature.", "es": "Los nuevos despertadores saludables despiertan a las personas con suavidad matutina imitando el trino de pájaros y el fluir de manantiales."}, {"id": "#2", "hanzi": "儿童在语言学习的初期阶段，主要通过大量模仿父母的语音和语调来掌握日常交流表达。", "pinyin": "Értóng zài yǔyán xuéxí de chūqī jiēduàn, zhǔyào tōngguò dàliàng mófǎng fùmǔ de yǔyīn hé yǔdiào lái zhǎngwò rìcháng jiāoliú biǎodá.", "en": "In early stages of language acquisition, children master daily communication expressions mainly through mimicking parents' pronunciation and intonation.", "es": "En fases tempranas de adquisición lingüística, los niños dominan la expresión cotidiana imitando ampliamente la entonación de sus padres."}], "collocations": [{"hanzi": "模仿能力", "en": "imitative ability / capacity to mimic"}, {"hanzi": "盲目模仿", "en": "blindly imitate"}, {"hanzi": "模仿声音", "en": "mimic sounds / voices"}, {"hanzi": "刻意模仿", "en": "deliberately emulate / imitate"}, {"hanzi": "模仿动作", "en": "mimic movements / actions"}, {"hanzi": "善于模仿", "en": "be good at imitating"}], "idioms": [{"hanzi": "东施效颦", "pinyin": "dōng shī xiào pín", "meaning_en": "blindly mimic others with ridiculous and grotesque results"}, {"hanzi": "惟妙惟肖", "pinyin": "wéi miào wéi xiào", "meaning_en": "imitated or portrayed with remarkable fidelity and lifelikeness"}, {"hanzi": "鹦鹉学舌", "pinyin": "yīng wǔ xué shé", "meaning_en": "parrot others' words without genuine comprehension"}, {"hanzi": "生搬硬套", "pinyin": "shēng bān yìng tào", "meaning_en": "mechanically copy and apply rules without adapting to context"}], "character_decomposition": [{"character": "模", "pinyin": "mó", "meaning_en": "mold; pattern; model; standard", "meaning_es": "molde; patrón; modelo; pauta", "radical": "木", "radical_meaning_en": "wood", "meaning_component": "木 (wooden casting mold) + 莫 (dusk / phonetic casting frame)", "sound_component": "莫 (mò, dusk / phonetic)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "A wooden mold 木 used by artisans to cast duplicates into uniform shape; hence a model, archetype, or standard pattern.", "visual_mnemonic_story_en": "Carving wood (木) into a prototype mold (莫) allows accurate reproduction of models (模).", "visual_mnemonic_story_es": "Tallar madera (木) para hacer un molde maestro (莫) permite reproducir fielmente un modelo (模).", "tone_mnemonic_anchor": "35", "cangjie": "DTAK", "traditional": ""}, {"character": "仿", "pinyin": "fǎng", "meaning_en": "resemble; imitate; copy; like", "meaning_es": "parecerse; imitar; asemejarse; copiar", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person / human action) + 方 (square / standard boundary)", "sound_component": "方 (fāng, square / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 aligning gestures according to the square measurements 方 of an existing archetype; imitating.", "visual_mnemonic_story_en": "A person (亻) shaping behavior to fit the exact four-corner frame (方) of a teacher imitates (仿).", "visual_mnemonic_story_es": "Una persona (亻) que ajusta sus ademanes al patrón cuadrado (方) del maestro imita con destreza (仿).", "tone_mnemonic_anchor": "214", "cangjie": "OYHS", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "仿生学是一门建立在向大自然求教基础上的前沿交叉学科。科学家通过深入观察与模仿鸟类飞行的羽翼结构、海豚游动的流线体态，成功研制出阻力极小的超高速飞行器和潜艇，极大推动了现代交通工程的革新跨越。", "pinyin": "Fǎngshēngxué shì yī mén jiànlì zài xiàng dàzìrán qiújiào jīchǔ shàng de qiányán jiāochā xuékē. Kēxuéjiā tōngguò shēnrù guānchá yǔ mófǎng niǎolèi fēixíng de yǔyì jiégòu, hǎitún yóudòng de liúxiàntǐ tài, chénggōng yánzhì chū zǔlì jí xiǎo de chāogāosù fēixíngqì hé qiántǐng, jídà tuīdòngle xiàndài jiāotōng gōngchéng de géxīn kuàyuè.", "en": "Bionics is a frontier discipline built on learning from nature. By observing and mimicking birds' wing structures and dolphins' streamlined bodies, scientists engineered aircraft and submersibles with minimal drag, revolutionizing transit.", "es": "La biónica es una disciplina puntera nacida de aprender de la naturaleza. Imitando el diseño de las alas de aves y la silueta hidrodinámica de delfines, los científicos concibieron naves y sumergibles que reducen la resistencia revolucionando el transporte."}, {"id": "#2", "hanzi": "初涉艺术创作的青年画师，往往需要经历一段临摹大师经典的模仿阶段。然而，真正的艺术家绝不会永远停留于简单机械的模仿。唯有在扎实掌握传统笔墨技巧后勇敢融入个人独到的生命体验，方能破茧成蝶，开创出自成一家的独特美学风格。", "pinyin": "Chūshè yìshù chuàngzuò de qīngnián huàshī, wǎngwǎng xūyào jīnglì yī duàn línmó dàshī jīngdiǎn de mófǎng jiēduàn. Rán'ér, zhēnzhèng de yìshùjiā juébù huì yǒngyuǎn tíngliú yú jiǎndān jīxiè de mófǎng. Wéiyǒu zài zhāshi zhǎngwò chuántǒng bǐmò jìqiǎo hòu yǒnggǎn róngrù gèrén d способ/dúdào de shēngmìng tǐyàn, fāng néng pòjiǎn-chéngdié, kāichuàng chū zìchéng-yījiā de dútè měixué fēnggé.", "en": "Young painters starting in art often pass through a stage of imitating masters. Yet true artists never stagnate in mechanical copying. Only by infusing personal life experience after mastering fundamentals can one forge a distinct aesthetic style.", "es": "Los pintores noveles suelen atravesar una etapa de imitación copiando obras maestras. Con todo, el auténtico creador no se estanca en la copia mecánica; solo infundiendo vivencias propias tras dominar el oficio brota un estilo estético genuino."}]}, {"meanings_summary": {"en": "to avoid; avert; prevent; steer clear of (harm, errors, conflicts)", "es": "evitar; eludir; esquivar; prevenir (daños, errores, colisiones)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Dodging sideways on foot (避) to be spared and exempt from hardship (免) is actively avoiding trouble (避免).", "composite_memory_hook_es": "Apartarse a paso ligero (避) para quedar eximido o a salvo de percances (免) es evitar (避免).", "cultural_and_cognitive_roots": "Classical Sunzi Art of War: true strategic victory lies not in bloody clashes, but in avoiding enemy strongholds (避实击虚) and preventing unnecessary casualties.", "tone_sandhi_and_pitch_modulation": "Fourth tone followed by third tone: 'bì miǎn' (51-214). Sharp decisive fall dropping into low dipping contour."}, "semantic_boundary_contrasts": {"core_nuance": "避免 is an active transitive verb indicating taking prudent preventive measures to forestall errors, accidents, or undesirable outcomes.", "contrasts": [{"id": "1", "compared_word": "避免 vs. 逃避", "pinyin": "táobì", "analysis": "逃避 has a negative connotation of cowardly shirking responsibilities, reality, or legal duties ('逃避现实', '逃避责任'), whereas 避免 is rational preventive caution."}, {"id": "2", "compared_word": "避免 vs. 阻止", "pinyin": "zǔzhǐ", "analysis": "阻止 means actively stepping in to physically halt an action already underway ('阻止他的鲁莽行为'), while 避免 forestalls events beforehand."}, {"id": "3", "compared_word": "避免 vs. 免除", "pinyin": "miǎnchú", "analysis": "免除 means officially waiving, exempting, or removing a duty, tax, or debt ('免除学费'), while 避免 prevents bad consequences."}]}, "traps_and_cognates": {"look_alikes": [{"character": "僻", "pinyin": "pì", "meaning_en": "isolated; remote", "distinction_note": "Has person radical 亻 on left of 辟 instead of walk 辶 in 避"}, {"character": "壁", "pinyin": "bì", "meaning_en": "wall; cliff", "distinction_note": "Has earth radical 土 at bottom"}, {"character": "兔", "pinyin": "tù", "meaning_en": "rabbit; hare", "distinction_note": "Has extra dot inside representing a rabbit's tail, unlike 免"}, {"character": "勉", "pinyin": "miǎn", "meaning_en": "strive; exhort", "distinction_note": "Has power radical 力 on right of 免"}], "etymological_cognates": [{"character": "躲", "pinyin": "duǒ", "gloss_en": "hide; evade"}, {"character": "防", "pinyin": "fáng", "gloss_en": "defend; guard against"}, {"character": "省", "pinyin": "shěng", "gloss_en": "save; spare"}, {"character": "闪", "pinyin": "shǎn", "gloss_en": "dodge; flash"}]}, "id": "40", "hanzi": "避免", "pinyin": "bì miǎn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to take preventive measures to keep an undesirable, unfavorable, or harmful situation from taking place", "definition_es": "tomar precauciones para impedir que suceda una situación desfavorable, perjudicial o conflictiva", "example_phrase": "避免发生意外 (prevent / avoid accidents)"}], "example_sentences": [{"id": "#1", "hanzi": "改用渐亮的光线闹钟能够有效避免身体在深睡眠中突然受到惊吓，从而呵护心血管系统健康。", "pinyin": "Gǎiyòng jiànliàng de guāngxiàn nàozhōng nénggòu yǒuxiào bìmiǎn shēntǐ zài shēn shuìmián zhōng tūrán shòudào jīngxià, cóng'ér hēhù xīnxuěguǎn xìtǒng jiànkāng.", "en": "Switching to a light-gradual alarm can effectively avoid the body being abruptly startled during deep sleep, protecting cardiovascular health.", "es": "Pasarse a un despertador de luz gradual previene eficazmente que el cuerpo sufra sobresaltos en pleno sueño profundo, cuidando el corazón."}, {"id": "#2", "hanzi": "在方案制订过程中多方征求团队意见，有助于及时发现设计漏洞，避免不必要的人力与资金浪费。", "pinyin": "Zài fāng'àn zhìdìng guòchéng zhōng duōfāng zhēngqiú tuánduì yìjiàn, yǒuzhùyú jíshí fāxiàn shèjì lòudòng, bìmiǎn bú bìyào de rénlì yǔ zījīn làngfèi.", "en": "Soliciting multi-party team feedback while formulating plans helps detect design loopholes promptly and avoids unnecessary waste of labor and funds.", "es": "Consultar al equipo al trazar un plan ayuda a detectar fallos a tiempo, evitando despilfarros innecesarios de personal y presupuesto."}], "collocations": [{"hanzi": "避免发生", "en": "prevent from happening; avoid occurring"}, {"hanzi": "不可避免", "en": "unavoidable; inevitable"}, {"hanzi": "有效避免", "en": "effectively avert / prevent"}, {"hanzi": "避免冲突", "en": "avoid conflict / confrontation"}, {"hanzi": "避免错误", "en": "avoid mistakes / errors"}, {"hanzi": "尽量避免", "en": "try one's best to avoid"}], "idioms": [{"hanzi": "在所难免", "pinyin": "zài suǒ nán miǎn", "meaning_en": "hard to avoid; virtually inevitable"}, {"hanzi": "防患未然", "pinyin": "fáng huàn wèi rán", "meaning_en": "take preventive measures before mishaps occur"}, {"hanzi": "未雨绸缪", "pinyin": "wèi yǔ chóu móu", "meaning_en": "repair house before it rains; plan ahead prudently"}, {"hanzi": "避实就虚", "pinyin": "bì shí jiù xū", "meaning_en": "avoid the enemy's strength and strike at his weakness"}], "character_decomposition": [{"character": "避", "pinyin": "bì", "meaning_en": "avoid; evade; shun; seek shelter", "meaning_es": "evitar; esquivar; huir de; resguardarse", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (walking/moving away) + 辟 (law punishment / danger)", "sound_component": "辟 (bì/pì, punish / phonetic)", "stroke_count": "16", "composition_type": "半包围结构", "etymology_and_mnemonic": "Walking footsteps 辶 actively moving aside to evade criminal punishment or danger 辟; dodging peril.", "visual_mnemonic_story_en": "Stepping along the path (辶) away from hazardous confrontations (辟) to avoid danger (避).", "visual_mnemonic_story_es": "Apresurar los pasos (辶) para sortear una sanción o peligro eminente (辟) esquivándolo a tiempo (避).", "tone_mnemonic_anchor": "51", "cangjie": "YSRJ", "traditional": ""}, {"character": "免", "pinyin": "miǎn", "meaning_en": "exempt; excuse; remove; avoid", "meaning_es": "eximir; dispensar; quitar; librar de", "radical": "刀", "radical_meaning_en": "knife", "meaning_component": "Pictograph of an official taking off a heavy ceremonial helmet to be excused from duty", "sound_component": "Phonetic carrier in traditional scripts", "stroke_count": "7", "composition_type": "单一结构", "etymology_and_mnemonic": "Removing headgear or shedding an official burden; signifies exemption, forgiveness, or being spared from danger.", "visual_mnemonic_story_en": "Taking off a heavy restrictive helmet to be exempt and spared from burdensome trial (免).", "visual_mnemonic_story_es": "Despojarse del pesado casco militar quedando exonerado o libre de penalidad (免).", "tone_mnemonic_anchor": "214", "cangjie": "NAU", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在现代航空安全管理体系中，预防性检修是避免重大飞行安全事故的核心屏障。地勤机务人员严格依照规范流程对引擎、电子雷达及液压线路展开细致排查，唯有将隐患消灭在萌芽状态，才能确保万米高空飞行万无一失。", "pinyin": "Zài xiàndài hángkōng ānquán guǎnlǐ tǐxì zhōng, yùfángxìng jiǎnxiū shì bìmiǎn zhòngdà fēixíng ānquán shìgù de héxīn píngzhàng. Dìqín jīwù rényuán yángé yīzhào guīfàn liúchéng duì yǐnqíng, diànzǐ léidá jí yèyā xiànlù zhǎnkāi xìzhì páichá, wéiyǒu jiāng yǐnhuàn xiāomiè zài méngyá zhuàngtài, cáinéng quèbǎo wàn mǐ gāokōng fēixíng wànwúyīshī.", "en": "In modern aviation safety, preventive maintenance is the core barrier to avoiding major flight accidents. Ground crews scrupulously inspect engines, radars, and hydraulics according to protocol, nipping hazards in the bud to ensure absolute safety.", "es": "En la seguridad aeronáutica, las revisiones preventivas son la barrera clave para evitar siniestros. El personal de tierra inspecciona minuciosamente motores y circuitos para atajar riesgos en su origen y garantizar vuelos seguros."}, {"id": "#2", "hanzi": "人际交往中难免会产生观点分歧，明智的沟通者懂得换位思考，通过委婉温和的表达来避免正面语言冲突。学会倾听对方的真实顾虑，不仅能够有效化解误会与隔阂，更能为双方维系长久而稳固的信任基石。", "pinyin": "Rénjì jiāowǎng zhōng nánmiǎn huì chǎnshēng guāndiǎn fēnqí, míngzhì de gōutōngzhě dǒngde huànwèi-sīkǎo, tōngguò wěiwǎn wēnhé de biǎodá lái bìmiǎn zhèngmiàn yǔyán chōngtū. Xuéhuì qīngtīng duìfāng de zhēnshí gùlǜ, bùjǐn nénggòu yǒuxiào huàjiě wùhuì yǔ géhé, gèng néng wèi shuāngfāng wéixì chángjiǔ ér wěngù de xìnlài jīshí.", "en": "In interpersonal exchanges, divergent views inevitably arise. Wise communicators practice empathy and use gentle phrasing to avoid direct clashes. Listening to genuine concerns resolves misunderstandings and cements long-lasting trust.", "es": "En el trato humano surgen desacuerdos de forma inevitable. Quien se comunica con sensatez sabe ponerse en el lugar del otro y expresarse con tacto para eludir choques frontales, disipando malentendidos y consolidando la confianza mutua."}]}, {"meanings_summary": {"en": "tradition; traditional; conventional; heritage", "es": "tradición; tradicional; convencional; legado cultural"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Passing along down the ages (传) through an uninterrupted lineage thread (统) constitutes living tradition (传统).", "composite_memory_hook_es": "Transmitir de generación en generación (传) a lo largo de un hilo conductor histórico (统) conforma la tradición (传统).", "cultural_and_cognitive_roots": "Derived from historiographical lineages (正统, 道统): Confucian cultural continuity preserved like a seamless silk thread passing across dynastic shifts.", "tone_sandhi_and_pitch_modulation": "Second tone followed by third tone: 'chuán tǒng' (35-214). Smooth rising glide followed by dip-and-rise contour."}, "semantic_boundary_contrasts": {"core_nuance": "传统 refers to long-standing cultural customs, ethical practices, and time-honored conventions passed down across generations.", "contrasts": [{"id": "1", "compared_word": "传统 vs. 习俗", "pinyin": "xísú", "analysis": "习俗 focuses on specific folk customs and habits (e.g. eating zongzi, lion dances), whereas 传统 encompasses deep philosophical values, artistic lineages, and institutions."}, {"id": "2", "compared_word": "传统 vs. 常规", "pinyin": "chángguī", "analysis": "常规 refers to routine administrative rules, standard operational procedures, or normal conventions, lacking 传统's historical cultural depth."}, {"id": "3", "compared_word": "传统 vs. 古老", "pinyin": "gǔlǎo", "analysis": "古老 simply describes age and ancient vintage ('古老的城堡'), while 传统 emphasizes living transmission and active generational heritage."}]}, "traps_and_cognates": {"look_alikes": [{"character": "专", "pinyin": "zhuān", "meaning_en": "specialized; focused", "distinction_note": "Lacks person radical 亻 on left of 传"}, {"character": "转", "pinyin": "zhuǎn", "meaning_en": "turn; shift", "distinction_note": "Has vehicle radical 车 on left of 专"}, {"character": "统", "pinyin": "tǒng", "meaning_en": "unify; tradition", "distinction_note": "Has silk radical 纟 on left of 充"}, {"character": "充", "pinyin": "chōng", "meaning_en": "fill; charge", "distinction_note": "Lacks silk radical 纟 on left"}], "etymological_cognates": [{"character": "承", "pinyin": "chéng", "gloss_en": "inherit; carry on"}, {"character": "继", "pinyin": "jì", "gloss_en": "continue; succeed"}, {"character": "俗", "pinyin": "sú", "gloss_en": "custom; convention"}, {"character": "祖", "pinyin": "zǔ", "gloss_en": "ancestor; origin"}]}, "id": "41", "hanzi": "传统", "pinyin": "chuán tǒng", "level": "HSK 5", "part_of_speech": "Noun / Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "historical customs, ethical norms, cultural values, and practices handed down from generation to generation", "definition_es": "costumbres históricas, valores éticos y prácticas culturales transmitidas de generación en generación", "example_phrase": "优良传统 (fine tradition / glorious heritage)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "conforming to long-established custom or practice rather than modern innovations", "definition_es": "que se apega a las pautas y hábitos consuetudinarios frente a las novedades modernas", "example_phrase": "传统手工艺 (traditional handicraft / craftsmanship)"}], "example_sentences": [{"id": "#1", "hanzi": "与传统机械闹钟刺耳的铃声相比，新型智能光照唤醒设备更符合人体自然清醒的生理规律。", "pinyin": "Yǔ chuántǒng jīxiè nàozhōng cì'ěr de língshēng xiāngbǐ, xīnxíng zhìnéng guāngzhào huànxǐng shèbèi gèng fúhé réntǐ zìrán qīngxǐng de shēnglǐ guīlǜ.", "en": "Compared to the harsh ringing of traditional mechanical alarms, new smart lighting wake-up devices conform better to natural physiological waking laws.", "es": "Frente al estridente timbre del despertador tradicional mecánico, los nuevos dispositivos de luz inteligente armonizan mejor con la fisiología humana."}, {"id": "#2", "hanzi": "每逢中秋佳节，全家人围坐在一起品尝月饼、共赏明月，是中华民族流传千百年的美好传统。", "pinyin": "Měiféng zhōngqiū jiājié, quánjiā rén wéizuò zài yīqǐ pǐncháng yuèbǐng, gòngshǎng míngyuè, shì Zhōnghuá mínzú liúchuán qiānbǎi nián de měihǎo chuántǒng.", "en": "Every Mid-Autumn Festival, the entire family gathering to savor mooncakes and admire the full moon is a cherished tradition passed down for centuries.", "es": "Cada Fiesta del Medio Otoño, la familia congregada degustando pasteles de luna bajo el plenilunio celebra una hermosa tradición centenaria."}], "collocations": [{"hanzi": "传统文化", "en": "traditional culture"}, {"hanzi": "传统美德", "en": "traditional virtues"}, {"hanzi": "继承传统", "en": "inherit / carry forward traditions"}, {"hanzi": "发扬传统", "en": "carry forward / promote traditional heritage"}, {"hanzi": "传统节日", "en": "traditional festival"}, {"hanzi": "打破传统", "en": "break with tradition"}], "idioms": [{"hanzi": "薪火相传", "pinyin": "xīn huǒ xiāng chuán", "meaning_en": "pass the torch from generation to generation"}, {"hanzi": "因循守旧", "pinyin": "yīn xún shǒu jiù", "meaning_en": "stick to conventions and resist reform"}, {"hanzi": "继往开来", "pinyin": "jì wǎng kāi lái", "meaning_en": "carry forward past heritage and forge ahead into future"}, {"hanzi": "代代相传", "pinyin": "dài dài xiāng chuán", "meaning_en": "handed down from generation to generation"}], "character_decomposition": [{"character": "传", "pinyin": "chuán", "meaning_en": "pass on; hand down; transmit; impart", "meaning_es": "transmitir; difundir; traspasar; propagar", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person passing along) + 专 (spinning spindle thread / focused transmission)", "sound_component": "专 (zhuān, carrier / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A postal relay person 亻 handing down messages like uninterrupted spun thread 专 along roads; transmitting knowledge.", "visual_mnemonic_story_en": "A messenger person (亻) carrying single-minded focus (专) transmits news across generations (传).", "visual_mnemonic_story_es": "Un mensajero (亻) que corre con devoción concentrada (专) transmite legados y noticias sin cesar (传).", "tone_mnemonic_anchor": "35", "cangjie": "OQNI", "traditional": "傳"}, {"character": "统", "pinyin": "tǒng", "meaning_en": "interconnected thread; unify; gather; govern", "meaning_es": "hilo conductor; unificar; reunir; regir; sistema", "radical": "纟", "radical_meaning_en": "silk", "meaning_component": "纟 (continuous silk strand) + 充 (fill up / nourish completely)", "sound_component": "充 (chōng, phonetic carrier)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "The main guiding thread 纟 that gathers and unifies all filling fibers 充 into a coherent fabric; lineage and system.", "visual_mnemonic_story_en": "A continuous silk thread (纟) gathering all parts into an interconnected whole (充) unifies the system (统).", "visual_mnemonic_story_es": "La hebra de seda (纟) que enlaza y nutre la totalidad del tejido (充) mantiene unido el linaje (统).", "tone_mnemonic_anchor": "214", "cangjie": "VMYIU", "traditional": "統"}], "extended_reading_passages": [{"id": "#1", "hanzi": "优秀传统文化是一座取之不竭的精神宝库。在现代文创设计中，青年设计师巧妙地将传统水墨写意美学与现代数码科技相融合，让陈列在博物馆深处的千年非物质文化遗产重新焕发出蓬勃的当代生机。", "pinyin": "Yōuxiù chuántǒng wénhuà shì yī zuò qǔzhībùjié de jīngshén bǎokù. Zài xiàndài wénchuàng shèjì zhōng, qīngnián shèjìshī qiǎomiào de jiāng chuántǒng shuǐmò xièyì měixué yǔ xiàndài shùmǎ kējì xiāng rónghé, ràng chénliè zài bówùguǎn shēnchù de qiān nián fēiwùzhì wénhuà yíchǎn chóngxīn huànfā chū péngbó de dāngdài shēngjī.", "en": "Fine traditional culture is an inexhaustible treasure house of spirit. In contemporary creative design, young artists blend ink-wash aesthetics with digital technologies, breathing vibrant life into intangible cultural heritage.", "es": "La cultura tradicional es un manantial inagotable de riqueza espiritual. En el diseño contemporáneo, los creadores funden la aguada clásica con tecnologías digitales, revitalizando el patrimonio inmaterial con brío renovado."}, {"id": "#2", "hanzi": "随着全球化浪潮奔涌向前，如何在坚守民族文化传统的同时拥抱世界文明，成为各国共同探索的重要时代课题。历史证明，唯有立足自身优秀的文化传统根基，以包容开放的胸襟博采众长，文明之树才能根深叶茂、历久弥新。", "pinyin": "Suízhe quánqiúhuà làngcháo bēnyǒng qiánxiáng, rúhé zài jiānshǒu mínzú wénhuà chuántǒng de tóngshí yōngbào shìjiè wénmíng, chéngwéi gè guó gòngtóng tànsuǒ de zhòngyào shídài kètí. Lìshǐ zhèngmíng, wéiyǒu lìzú zìshēn yōuxiù de wénhuà chuántǒng gēnjī, yǐ bāoróng kāifàng de xiōngjīn bócǎi-zhòngcháng, wénmíng zhī shù cáinéng gēnshēn-yèmào, lìjiǔ-míxīn.", "en": "As globalization surges, preserving national traditions while embracing world civilizations has become a vital shared question. Grounded in cultural roots while adopting diverse strengths, civilization flourishes with enduring vitality.", "es": "Con el avance imparable de la globalización, preservar las tradiciones patrias al tiempo que se abraza la civilización mundial es un reto clave. Solo arraigados en el legado propio y abiertos al diálogo florece la cultura con perenne vigor."}]}];
